# Rate limiting storage
rate_limits: dict[str, list[float]] = defaultdict(list)
_rate_limits_last_prune = 0.0

# App-wide IP blocking — {ip: expires_at_iso_or_None}, loaded at startup from
# blocked_ips and kept in sync in-process so the middleware check on every
# request never touches the database.
_blocked_ips: dict[str, Optional[str]] = {}


def _is_ip_blocked(ip: str) -> bool:
    """Check the in-process blocked-IP cache. Lazily evicts expired entries.

    The cache is keyed by canonical address (ipguard.canonical_ip); the lookup
    folds the caller's address the same way, but only when something is blocked.
    """
    if not _blocked_ips:
        return False
    if ip not in _blocked_ips:
        ip = ipguard.canonical_ip(ip) or ip
        if ip not in _blocked_ips:
            return False
    expires_at = _blocked_ips[ip]
    if expires_at is None:
        return True
    try:
        if datetime.now(timezone.utc) < datetime.fromisoformat(expires_at.replace(" ", "T")).replace(tzinfo=timezone.utc):
            return True
    except ValueError:
        return True
    # Expired — evict from cache (DB row is left for the admin's own record; harmless)
    del _blocked_ips[ip]
    return False


# Paths only vulnerability scanners ask for — the portal serves none of them.
_PROBE_PATH_RE = re.compile(
    r"(^|/)\.(env|git|aws|ssh|svn|hg|htpasswd|htaccess|DS_Store)(\b|/|$)"
    r"|\.git-credentials"
    r"|\.(php\d?|aspx?|jsp|cgi)$"
    r"|(^|/)(wp-admin|wp-login|wp-content|wp-includes|phpmyadmin|cgi-bin|vendor/phpunit)(/|$)",
    re.IGNORECASE,
)
# Prefixes that relay to other applications, where such paths can be legitimate.
# User uploads are exempt too: their URLs are user-influenced (chat images).
_PROBE_EXEMPT_PREFIXES = ("/proxy/", "/search/", "/api/", "/static/uploads/")
_PROBE_TABLE_MAX = 20000                            # hard cap per table
_probe_strikes: dict[str, tuple[int, float]] = {}   # ip -> (count, first_seen)
_probe_blocks: dict[str, float] = {}                # ip -> monotonic expiry
_probe_last_prune = 0.0


def _is_local_address(ip: str) -> bool:
    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return True
    if addr.version == 6 and addr.ipv4_mapped:
        addr = addr.ipv4_mapped
    return addr.is_loopback or addr.is_private or addr.is_link_local


def _is_scanner_probe(request: web.Request, status: int) -> bool:
    """True for a failed request to a scanner-only path that no browser made.

    Current browsers attach Sec-Fetch-Site to every request they make over
    HTTPS and page script cannot remove it, so requiring its absence means a
    web page, an email or a chat message full of <img> tags cannot make a
    visitor's browser earn strikes (and a block) on that visitor's behalf.
    Safari before 16.4 sends no such header, so image loads (the way a page
    triggers requests without user action) are skipped by Accept as well.
    That exception is best-effort, which is why the feature is opt-in.
    """
    return (
        status in (401, 404, 405)
        and "Sec-Fetch-Site" not in request.headers
        and not request.headers.get("Accept", "").lower().startswith("image/")
        and not request.path.startswith(_PROBE_EXEMPT_PREFIXES)
        and _PROBE_PATH_RE.search(request.path) is not None
    )


def _is_probe_blocked(ip: str) -> bool:
    expires = _probe_blocks.get(ip)
    if expires is None:
        return False
    if monotonic() < expires:
        return True
    del _probe_blocks[ip]
    return False


def _record_probe(ip: str, path: str, user_agent: Optional[str] = None) -> None:
    """Count a scanner-style request; block the client once it repeats."""
    global _probe_last_prune
    # Never block the proxies themselves, local callers, this server's own
    # addresses or anything on a never-ban list: media-server hooks, link
    # previews and tunnelled connections reach the portal from those, and users
    # can aim them at probe-like paths. Every automatic block asks the same
    # helper, _never_ban_reason.
    if Config.PROBE_BLOCK_STRIKES <= 0 or _never_ban_reason(ip) is not None:
        return
    now = monotonic()
    # Sweep expired entries at most once a minute, and cap both tables, so a
    # flood of distinct addresses costs O(1) per request and bounded memory.
    if now - _probe_last_prune > 60 and (len(_probe_strikes) > 5000 or len(_probe_blocks) > 5000):
        _probe_last_prune = now
        for k in [k for k, (_, first) in _probe_strikes.items() if now - first > 600]:
            del _probe_strikes[k]
        for k in [k for k, exp in _probe_blocks.items() if exp <= now]:
            del _probe_blocks[k]
    while len(_probe_strikes) >= _PROBE_TABLE_MAX:
        del _probe_strikes[next(iter(_probe_strikes))]
    while len(_probe_blocks) >= _PROBE_TABLE_MAX:
        del _probe_blocks[next(iter(_probe_blocks))]
    count, first = _probe_strikes.get(ip, (0, now))
    if now - first > 600:
        count, first = 0, now
    count += 1
    if count >= Config.PROBE_BLOCK_STRIKES:
        _probe_strikes.pop(ip, None)
        _probe_blocks[ip] = now + Config.PROBE_BLOCK_SECONDS
        logger.info(
            f"Blocking {ip} for {Config.PROBE_BLOCK_SECONDS}s after repeated scanner probes (last: {path[:80]})"
        )
        security_event_nowait(
            "probe_block", ip=ip, user_agent=user_agent, result="blocked",
            details={"path": path[:80], "seconds": Config.PROBE_BLOCK_SECONDS})
    else:
        _probe_strikes[ip] = (count, first)


_CHAT_UPLOAD_URL_RE = re.compile(r"/static/uploads/chat/[A-Za-z0-9._-]+")


def _valid_chat_upload_url(url) -> bool:
    """A chat image/attachment URL must name one file in the chat upload dir."""
    return (
        isinstance(url, str)
        and ".." not in url
        and _CHAT_UPLOAD_URL_RE.fullmatch(url) is not None
    )


def safe_error_message(e: Exception) -> str:
    """Return a safe error message without exposing internal details."""
    error_msg = str(e)
    # Don't expose file paths or internal details
    if '/' in error_msg or '\\' in error_msg:
        return "An internal error occurred"
    # Truncate very long messages
    if len(error_msg) > 200:
        return error_msg[:200] + "..."
    # Allow UNIQUE constraint errors to pass through (helpful for duplicate names)
    if "UNIQUE constraint" in error_msg:
        return "A record with this name or identifier already exists"
    return error_msg


async def read_multipart_part(part, limit: int) -> tuple[bytes, bool]:
    """Read one multipart ``file`` part up to ``limit`` bytes.

    aiohttp's ``BodyPartReader.read()`` takes no size argument in the
    version pinned here — it reads the whole part unconditionally, which
    is exactly what a per-file size cap needs to avoid. Stream it in
    chunks instead and stop as soon as ``limit`` is exceeded.

    Returns ``(data, oversized)`` — ``data`` is truncated at ``limit`` and
    ``oversized`` is True if there was more where that came from.
    """
    buf = bytearray()
    oversized = False
    async for chunk in part:
        buf.extend(chunk)
        if len(buf) > limit:
            oversized = True
            del buf[limit:]
            break
    return bytes(buf), oversized

