async def http_update_service(request: web.Request) -> web.Response:
    """Update a service (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    service_id = request.match_info.get("id")
    if not service_id or not service_id.isdigit():
        return web.json_response({"error": "Invalid service ID"}, status=400)

    service_id = int(service_id)

    # Check service exists
    service = await db.get_service_by_id(service_id)
    if not service:
        return web.json_response({"error": "Service not found"}, status=404)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    # Build update fields
    updates = {}
    # Common fields
    for field in ["name", "path", "plugin", "host", "port", "icon"]:
        if field in data:
            updates[field] = data[field]
    if "enabled" in data:
        updates["enabled"] = 1 if data["enabled"] else 0
    if "required_scopes" in data:
        scopes = data["required_scopes"]
        if isinstance(scopes, str):
            scopes = [s.strip() for s in scopes.split(",") if s.strip()]
        updates["required_scopes"] = ",".join(scopes)
    # A changed effective SSH target (the host and port the ssh plugin dials:
    # the config's own host/port when set, else the columns) drops the SSH
    # host-key pin, whether or not a config is sent with the edit.
    target_changed = _service_target_changed(
        service, updates, data.get("config") if "config" in data else None)
    if "config" in data:
        new_config = data["config"]
        if isinstance(new_config, dict):
            # The SSH host-key pin is only set by the accept route or an admin
            # pre-filling a valid fingerprint.
            if "host_key_ignore" in new_config and not isinstance(new_config["host_key_ignore"], bool):
                return web.json_response({"error": "Invalid host key setting"}, status=400)
            new_config = hostkeys.guard_replacement(
                service.get("config"), new_config,
                target_changed=target_changed, trusted_incoming=True)
            updates["config"] = new_config   # a dict: stored encrypted
        else:
            updates["config"] = json.dumps(new_config)
    elif target_changed and isinstance(service.get("config"), dict) and (
            hostkeys.FINGERPRINT_KEY in service["config"] or hostkeys.REFUSED_KEY in service["config"]):
        updates["config"] = hostkeys.guard_replacement(
            service["config"], service["config"], target_changed=True)

    # Managed service fields
    for field in ["display_name", "description", "binary_path", "working_dir"]:
        if field in data:
            updates[field] = data[field]
    if "ports" in data:
        updates["ports"] = json.dumps(data["ports"])

    if "systemd_unit" in data:
        unit = (data["systemd_unit"] or "").strip() or None
        if unit and not system_monitor._validate_service_name(unit):
            return web.json_response({"error": "Invalid systemd unit name"}, status=400)
        updates["systemd_unit"] = unit

    if not updates:
        return web.json_response({"error": "No fields to update"}, status=400)

    try:
        # Use the unified update method
        await db.update_service_full(service_id, **updates)

        # Get updated service
        updated = await db.get_service_by_id(service_id)
        logger.info(f"Service {service_id} updated by user {token.user_id}: {list(updates.keys())}")

        response = {
            "id": updated["id"],
            "name": updated["name"],
            "path": updated["path"],
            "plugin": updated.get("plugin", "tcp_tunnel"),
            "host": updated.get("host", ""),
            "port": updated.get("port", 0),
            "enabled": bool(updated["enabled"]),
            "required_scopes": updated["required_scopes"],
            "service_type": updated.get("service_type", "proxy"),
            "icon": updated.get("icon", "server"),
            "systemd_unit": updated.get("systemd_unit"),
        }
        if updated.get("service_type") == "managed":
            response.update({
                "display_name": updated.get("display_name") or updated["name"],
                "description": updated.get("description", ""),
                "status": updated.get("status", "stopped"),
            })
        return web.json_response(response)
    except Exception as e:
        logger.warning(f"Failed to update service {service_id}: {e}")
        return web.json_response({"error": safe_error_message(e)}, status=400)


async def http_get_service(request: web.Request) -> web.Response:
    """Get a single service by ID."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    service_id = request.match_info.get("id")
    if not service_id or not service_id.isdigit():
        return web.json_response({"error": "Invalid service ID"}, status=400)

    service = await db.get_service_by_id(int(service_id))
    if not service:
        return web.json_response({"error": "Service not found"}, status=404)

    # Check authorization for non-admin users
    if not token.has_scope("admin") and not token.has_scope("*"):
        if not check_service_authorization(service, token):
            return web.json_response({"error": "Access denied"}, status=403)

    response = {
        "id": service["id"],
        "name": service["name"],
        "path": service["path"],
        "plugin": service.get("plugin", "tcp_tunnel"),
        "host": service.get("host", ""),
        "port": service.get("port", 0),
        "enabled": bool(service["enabled"]),
        "required_scopes": service["required_scopes"],
        "config": redact_service_config(service.get("config", {})),
        "service_type": service.get("service_type", "proxy"),
        "icon": service.get("icon", "server"),
        "systemd_unit": service.get("systemd_unit"),
    }

    if service.get("systemd_unit"):
        unit_status = await asyncio.to_thread(system_monitor.get_service_status, service["systemd_unit"])
        response["systemd_status"] = unit_status["sub_state"] if unit_status else "unknown"
        response["status"] = "running" if unit_status and unit_status["sub_state"] == "running" else "stopped"

    # Include process management fields for managed services
    if service.get("service_type") == "managed":
        response.update({
            "display_name": service.get("display_name") or service["name"],
            "description": service.get("description", ""),
            "status": service.get("status", "stopped"),
            "pid": service.get("pid"),
            "binary_path": service.get("binary_path"),
            "working_dir": service.get("working_dir"),
            "ports": service.get("ports", []),
            "health_status": service.get("health_status", "unknown"),
            "last_health_check": service.get("last_health_check"),
            "restart_count": service.get("restart_count", 0),
            "last_started_at": service.get("last_started_at"),
            "last_stopped_at": service.get("last_stopped_at"),
            "error_message": service.get("error_message"),
        })

    return web.json_response(response)


