async def _audit_service_control(token: "TokenPayload", service: dict, action: str) -> None:
    """Audit entry for a start, stop or restart of a service done through the portal. A stop asked
    for here is deliberately silent to the health alerts, so it must leave a record."""
    actor = await db.get_user_by_id(token.user_id)
    await audit_log(
        f"service.{action}", token.user_id, (actor or {}).get("username", "unknown"),
        target_id=service["id"], target_type="service", target_name=service.get("name"),
        details={"service_id": service["id"], "service_name": service.get("name"), "action": action,
                 "systemd_unit": service.get("systemd_unit") if service.get("service_type") != "managed" else None},
    )


async def _control_systemd_bound_service(
    service: dict, action: str, token: "TokenPayload"
) -> web.Response:
    """Start/stop/restart a proxy-type (or any) service bound to a systemd unit.

    This reuses system_monitor.control_service(), the same validated
    `sudo systemctl <action> <unit>.service` call already exposed under
    System Monitor — it's just wired into the Services panel here so a
    service row (e.g. a game server or file share behind the reverse
    proxy) doesn't need SSH access to be restarted.
    """
    unit = service["systemd_unit"]
    success, message = await asyncio.to_thread(system_monitor.control_service, unit, action)
    if not success:
        return web.json_response({"error": message}, status=400)

    logger.info(f"Service {service['id']} ({unit}.service) {action} by user {token.user_id}")
    admin_user = await db.get_user_by_id(token.user_id)
    await db.log_activity(
        token.user_id, get_display_name(admin_user) if admin_user else "admin",
        f"service_{action}", f"{action.capitalize()}ed service '{service.get('name', service['id'])}' ({unit})"
    )
    await _audit_service_control(token, service, action)
    unit_status = await asyncio.to_thread(system_monitor.get_service_status, unit)
    status = "running" if unit_status and unit_status["sub_state"] == "running" else "stopped"
    return web.json_response({
        "success": True,
        "service": {
            "id": service["id"],
            "name": service["name"],
            "status": status,
            "pid": unit_status.get("main_pid") if unit_status else None,
        }
    })


async def http_start_service(request: web.Request) -> web.Response:
    """Start a managed/systemd-bound service (admin or a user with a 'control' grant)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    service_id = request.match_info.get("id")
    if not service_id or not service_id.isdigit():
        return web.json_response({"error": "Invalid service ID"}, status=400)

    service_id = int(service_id)

    if not await _can_control_service(token, service_id, "control"):
        return forbidden_response(request)

    service = await db.get_service_by_id(service_id)
    if not service:
        return web.json_response({"error": "Service not found"}, status=404)

    if service.get("service_type") != "managed":
        if not service.get("systemd_unit"):
            return web.json_response(
                {"error": "This service has no start/stop/restart control configured. "
                          "Bind it to a systemd unit to enable it."},
                status=400
            )
        return await _control_systemd_bound_service(service, "start", token)

    if not _service_manager:
        return web.json_response({"error": "Service manager not initialized"}, status=503)

    success, error = await _service_manager.start_service(service_id)
    if success:
        logger.info(f"Service {service_id} started by user {token.user_id}")
        await _audit_service_control(token, service, "start")
        updated = await db.get_service_by_id(service_id)
        admin_user = await db.get_user_by_id(token.user_id)
        await db.log_activity(token.user_id, get_display_name(admin_user) if admin_user else "admin", "service_start", f"Started service '{service.get('name', service_id)}'")
        return web.json_response({
            "success": True,
            "service": {
                "id": updated["id"],
                "name": updated["name"],
                "status": updated.get("status", "stopped"),
                "pid": updated.get("pid"),
            }
        })
    else:
        return web.json_response({"error": error}, status=400)


