# Allowed shells for terminal and SSH connections

async def http_create_user_connection(request: web.Request) -> web.Response:
    """Create a new user connection."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    # Check if non-admin users are allowed to create connections
    if not token.has_scope("admin") and not token.has_scope("*"):
        allow = await db.get_setting("allow_user_connections")
        if allow == "false":
            return web.json_response({"error": "Adding connections is currently disabled by an administrator"}, status=403)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    if not isinstance(data, dict):
        return web.json_response({"error": "Invalid request"}, status=400)
    if not isinstance(data.get("type", ""), str):
        return web.json_response({"error": "Invalid connection type"}, status=400)
    if not isinstance(data.get("name", ""), str):
        return web.json_response({"error": "Invalid connection name"}, status=400)
    if not isinstance(data.get("host", ""), str):
        return web.json_response({"error": "Invalid host"}, status=400)
    name = data.get("name", "").strip()
    conn_type = data.get("type", "").strip().lower()
    host = data.get("host", "").strip()
    port = data.get("port")
    config = data.get("config", {})
    if config is None:
        config = {}
    if not isinstance(config, dict):
        return web.json_response({"error": "Config must be an object"}, status=400)
    ssh_key_id = data.get("ssh_key_id")
    icon = data.get("icon")
    portal_access = 1 if data.get("portal_access", 1) else 0
    api_access = 1 if data.get("api_access", 0) else 0

    # Validate required fields
    if not name:
        return web.json_response({"error": "Connection name required"}, status=400)

    if conn_type not in CONNECTION_TYPES:
        return web.json_response({
            "error": f"Invalid connection type. Use one of: {', '.join(CONNECTION_TYPES.keys())}"
        }, status=400)

    if not host:
        return web.json_response({"error": "Host required"}, status=400)

    # Get default port if not specified
    type_info = CONNECTION_TYPES[conn_type]
    if port is None:
        port = type_info["default_port"]
    elif port:
        try:
            port = int(port)
            if port < 1 or port > 65535:
                return web.json_response({"error": "Invalid port number"}, status=400)
        except ValueError:
            return web.json_response({"error": "Invalid port number"}, status=400)

    # Block local/internal targets for user connections (security): the host
    # and any URL in the config, literal or resolved.
    if not await _user_targets_allowed(host, config, port or 0):
        return web.json_response({"error": "Host not allowed"}, status=403)
    _missing = _mediamtx_missing_urls(conn_type, config)
    if _missing:
        return web.json_response(
            {"error": f"{', '.join(_missing)} required for this connection type"}, status=400)
    if _vpn_mode_refused(conn_type, config):
        return web.json_response({"error": "Only SOCKS mode is available for this connection type"}, status=400)

    # Validate SSH key ownership if specified
    if ssh_key_id:
        from ssh_keys import get_key_by_id
        key = await get_key_by_id(int(ssh_key_id))
        if not key or key["user_id"] != token.user_id:
            return web.json_response({"error": "Invalid SSH key"}, status=400)

    # Use default icon if not specified
    if not icon:
        icon = type_info["icon"]

    # A new connection never arrives with a host-key pin (only accepting a
    # key sets one) and the opt-out must be a real boolean.
    if "host_key_ignore" in config and not isinstance(config["host_key_ignore"], bool):
        return web.json_response({"error": "Invalid host key setting"}, status=400)
    config = hostkeys.strip_new_pin(config)

    # Enforce config size limit to prevent oversized database entries
    config_str = json.dumps(config) if isinstance(config, dict) else (config or "{}")
    if len(config_str) > 10240:  # 10 KB
        return web.json_response({"error": "Config too large (max 10 KB)"}, status=400)

    try:
        conn_id = await db.create_user_connection(
            user_id=token.user_id,
            name=name,
            conn_type=conn_type,
            host=host,
            port=port,
            config=config_str,
            ssh_key_id=ssh_key_id,
            icon=icon,
            portal_access=portal_access,
            api_access=api_access
        )

        logger.info(f"Connection '{name}' ({conn_type}) created by user {token.user_id}")
        user = await db.get_user_by_id(token.user_id)
        await db.log_activity(token.user_id, get_display_name(user) if user else "unknown", "connection_create", f"Created {conn_type} connection '{name}'")

        return web.json_response({
            "id": conn_id,
            "name": name,
            "type": conn_type,
            "host": host,
            "port": port,
            "icon": icon,
            "portal_access": portal_access,
            "api_access": api_access
        }, status=201)

    except Exception as e:
        if "UNIQUE constraint" in str(e):
            return web.json_response({"error": "Connection with this name already exists"}, status=400)
        logger.error(f"Failed to create connection: {e}")
        return web.json_response({"error": "Failed to create connection"}, status=500)


async def http_list_user_connections(request: web.Request) -> web.Response:
    """List all connections for the authenticated user."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    # Optional filter by type
    conn_type = request.query.get("type")

    try:
        if conn_type:
            connections = await db.get_user_connections_by_type(token.user_id, conn_type)
        else:
            connections = await db.get_user_connections(token.user_id)

        return web.json_response({
            "connections": [_externalize_connection(redact_connection_config(c)) for c in connections]
        })
    except Exception as e:
        logger.error(f"Failed to list connections: {e}")
        return web.json_response({"error": "Failed to list connections"}, status=500)


async def http_get_user_connection(request: web.Request) -> web.Response:
    """Get a specific user connection."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    conn_uuid = request.match_info.get("id")
    if not conn_uuid:
        return web.json_response({"error": "Invalid connection ID"}, status=400)

    connection = await db.get_accessible_connection(conn_uuid, token.user_id)
    if not connection:
        return web.json_response({"error": "Connection not found"}, status=404)

    return web.json_response(_externalize_connection(redact_connection_config(connection)))


async def http_update_user_connection(request: web.Request) -> web.Response:
    """Update a user connection."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    conn_uuid = request.match_info.get("id")
    if not conn_uuid:
        return web.json_response({"error": "Invalid connection ID"}, status=400)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    if not isinstance(data, dict):
        return web.json_response({"error": "Invalid request"}, status=400)

    # A type must be a known type name before any policy check reads it
    # (same normalisation as on create).
    if "type" in data:
        if not isinstance(data["type"], str):
            return web.json_response({"error": "Invalid connection type"}, status=400)
        data["type"] = data["type"].strip().lower()
        if data["type"] not in CONNECTION_TYPES:
            return web.json_response({"error": "Invalid connection type"}, status=400)
    if "name" in data:
        if not isinstance(data["name"], str):
            return web.json_response({"error": "Invalid connection name"}, status=400)
        data["name"] = data["name"].strip()
        if not data["name"]:
            return web.json_response({"error": "Connection name required"}, status=400)

    # Validate port if being updated
    if "port" in data and data["port"]:
        try:
            port = int(data["port"])
            if port < 1 or port > 65535:
                return web.json_response({"error": "Invalid port number"}, status=400)
            data["port"] = port
        except ValueError:
            return web.json_response({"error": "Invalid port number"}, status=400)

    if "host" in data:
        if not isinstance(data["host"], str):
            return web.json_response({"error": "Invalid host"}, status=400)
        data["host"] = data["host"].strip()
        if not data["host"]:
            return web.json_response({"error": "Host required"}, status=400)

    if "config" in data and not isinstance(data["config"], dict):
        return web.json_response({"error": "Config must be an object"}, status=400)

    # Resolve UUID to internal connection
    connection = await db.get_user_connection_by_uuid(conn_uuid, token.user_id)
    if not connection:
        return web.json_response({"error": "Connection not found"}, status=404)
    int_id = connection["id"]

    # Merge incoming config with existing config to preserve fields not in the form
    # (e.g., passwords, private keys, and other sensitive fields that are not shown during edit)
    config = data.get("config", {})
    if isinstance(config, dict):
        existing_config = connection.get("config", {})
        if isinstance(existing_config, str):
            existing_config = json.loads(existing_config) if existing_config else {}
        if isinstance(existing_config, dict):
            # Existing config provides defaults; incoming config overrides.
            # The SSH host-key pin is the exception: it only ever comes from
            # the accept route, and a changed host or port drops it.
            if "host_key_ignore" in config and not isinstance(config["host_key_ignore"], bool):
                return web.json_response({"error": "Invalid host key setting"}, status=400)
            target_changed = (
                ("host" in data and data["host"] != connection.get("host"))
                or ("port" in data and (data["port"] or None) != (connection.get("port") or None)))
            data["config"] = hostkeys.guard_config(
                existing_config, config, target_changed=target_changed)

    # Enforce config size limit
    config_check = data.get("config", {})
    config_size = len(json.dumps(config_check) if isinstance(config_check, dict) else str(config_check or ""))
    if config_size > 10240:  # 10 KB
        return web.json_response({"error": "Config too large (max 10 KB)"}, status=400)

    # Block local/internal targets for user connections (security): the
    # resulting host and any URL in the resulting (merged) config.
    new_host = data["host"] if "host" in data else None
    if new_host is not None or "config" in data:
        if not await _user_targets_allowed(new_host, data.get("config"), 0):
            return web.json_response({"error": "Host not allowed"}, status=403)
    if "config" in data or "type" in data:
        _missing = _mediamtx_missing_urls(
            data.get("type", connection.get("type")), data.get("config", connection.get("config")))
        if _missing:
            return web.json_response(
                {"error": f"{', '.join(_missing)} required for this connection type"}, status=400)
        if _vpn_mode_refused(data.get("type", connection.get("type")),
                             data.get("config", connection.get("config"))):
            return web.json_response(
                {"error": "Only SOCKS mode is available for this connection type"}, status=400)

    try:
        if await db.update_user_connection(int_id, token.user_id, **data):
            logger.info(f"Connection {conn_uuid} updated by user {token.user_id}")
            return web.json_response({"status": "updated"})
        else:
            return web.json_response({"error": "No changes"}, status=404)
    except Exception as e:
        if "UNIQUE constraint" in str(e):
            return web.json_response({"error": "Connection with this name already exists"}, status=400)
        logger.error(f"Failed to update connection: {e}")
        return web.json_response({"error": "Failed to update connection"}, status=500)


async def http_delete_user_connection(request: web.Request) -> web.Response:
    """Delete a user connection."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    conn_uuid = request.match_info.get("id")
    if not conn_uuid:
        return web.json_response({"error": "Invalid connection ID"}, status=400)

    connection = await db.get_user_connection_by_uuid(conn_uuid, token.user_id)
    if not connection:
        return web.json_response({"error": "Connection not found"}, status=404)

    if await db.delete_user_connection(connection["id"], token.user_id):
        logger.info(f"Connection {conn_uuid} deleted by user {token.user_id}")
        return web.json_response({"status": "deleted"})
    else:
        return web.json_response({"error": "Connection not found"}, status=404)


async def http_toggle_connection_pin(request: web.Request) -> web.Response:
    """Toggle pin status for a connection."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    conn_uuid = request.match_info.get("id")
    if not conn_uuid:
        return web.json_response({"error": "Invalid connection ID"}, status=400)

    connection = await db.get_user_connection_by_uuid(conn_uuid, token.user_id)
    if not connection:
        return web.json_response({"error": "Connection not found"}, status=404)

    result = await db.toggle_connection_pin(connection["id"], token.user_id)
    if result is None:
        return web.json_response({"error": "Connection not found"}, status=404)
    return web.json_response({"is_pinned": result})


async def http_get_connection_types(request: web.Request) -> web.Response:
    """Get available connection types with plugin config schemas."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    # Include plugin schemas for dynamic form generation
    types_with_schemas = {}
    for type_name, type_info in CONNECTION_TYPES.items():
        plugin_name = type_info.get("plugin")
        plugin = get_plugin(plugin_name) if plugin_name else None

        schema = plugin.info.config_schema if plugin and hasattr(plugin, 'info') else {}
        if plugin_name == "vpn_tunnel":
            # User connections may only use SOCKS mode: do not offer TUN/TAP.
            schema = copy.deepcopy(schema)
            schema.get("properties", {}).get("mode", {})["enum"] = ["socks"]

        types_with_schemas[type_name] = {
            **type_info,
            "config_schema": schema
        }

    return web.json_response({"types": types_with_schemas})


async def http_connect_user_connection(request: web.Request) -> web.Response:
    """Get connection details for launching a user connection."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    conn_uuid = request.match_info.get("id")
    if not conn_uuid:
        return web.json_response({"error": "Invalid connection ID"}, status=400)

    connection = await db.get_accessible_connection(conn_uuid, token.user_id)
    if not connection:
        return web.json_response({"error": "Connection not found"}, status=404)

    # Record usage
    await db.record_connection_usage(connection["id"], token.user_id)

    # Get SSH key public key if associated
    ssh_public_key = None
    if connection.get("ssh_key_id"):
        from ssh_keys import get_key_by_id
        key = await get_key_by_id(connection["ssh_key_id"])
        if key:
            ssh_public_key = key["public_key"]

    return web.json_response({
        "connection": _externalize_connection(redact_connection_config(connection)),
        "ssh_public_key": ssh_public_key,
        "websocket_url": f"/ws/user-connection/{conn_uuid}"
    })


async def http_accept_connection_host_key(request: web.Request) -> web.Response:
    """POST /api/connections/{id}/host-key/accept - pin (or replace) an SSH
    connection's host key.

    Owner only: the connection is looked up as the signed-in user's own, so a
    grantee of a shared connection gets 404. This is the only way a user
    connection gets a pin; no WebSocket message can reach it.
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not has_full_user_scope(token):
        return full_scope_required_response()
    connection = await db.get_user_connection_by_uuid(request.match_info.get("id", ""), token.user_id)
    if not connection or connection.get("user_id") != token.user_id:
        return web.json_response({"error": "Connection not found"}, status=404)
    if connection.get("type") not in sftp_browser.SFTP_ELIGIBLE_TYPES:
        return web.json_response({"error": "Connection is not SSH/SFTP type"}, status=400)
    body, fp, err = await _read_accept_request(request)
    if err:
        return err
    target = _user_connection_ssh_target(connection)
    err = _check_accepted_prompt(body, fp, "connection", connection["id"], token.user_id, target)
    if err:
        return err

    config = dict(connection.get("config") or {})
    config[hostkeys.FINGERPRINT_KEY] = fp
    config.pop(hostkeys.REFUSED_KEY, None)
    if not await db.update_user_connection_config_if_target(
            connection["id"], token.user_id, config, connection.get("host"), connection.get("port")):
        return _stale_host_key("The connection was changed while this prompt was open; connect again")
    logger.info(f"SSH host key accepted for connection {connection['id']} by user {token.user_id}: {fp}")
    user = await db.get_user_by_id(token.user_id)
    await db.log_activity(token.user_id, get_display_name(user) if user else "unknown",
                          "host_key_accept", f"Accepted host key for connection '{connection.get('name')}' ({fp})")
    await security_event("host_key_accepted", request=request, user=user, user_id=token.user_id,
                         details={"kind": "connection", "id": connection["id"], "fingerprint": fp})
    return web.json_response({"status": "accepted", "fingerprint": fp})


async def http_accept_service_host_key(request: web.Request) -> web.Response:
    """POST /api/services/{id}/host-key/accept - pin (or replace) the host key
    of an admin-defined SSH service. Admin only, with a full-scope credential."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)
    if not has_full_user_scope(token):
        return full_scope_required_response()
    service_id = request.match_info.get("id", "")
    if not service_id.isdigit():
        return web.json_response({"error": "Invalid service ID"}, status=400)
    service = await db.get_service_by_id(int(service_id))
    if not service:
        return web.json_response({"error": "Service not found"}, status=404)
    if service.get("plugin") != "ssh":
        return web.json_response({"error": "Service is not an SSH service"}, status=400)
    body, fp, err = await _read_accept_request(request)
    if err:
        return err
    err = _check_accepted_prompt(body, fp, "service", service["id"], token.user_id, _service_ssh_target(service))
    if err:
        return err

    config = dict(service.get("config") or {})
    config[hostkeys.FINGERPRINT_KEY] = fp
    config.pop(hostkeys.REFUSED_KEY, None)
    if not await db.update_service_config_if_target(
            service["id"], config, service.get("host"), service.get("port")):
        return _stale_host_key("The service was changed while this prompt was open; connect again")
    logger.info(f"SSH host key accepted for service {service['id']} by user {token.user_id}: {fp}")
    user = await db.get_user_by_id(token.user_id)
    await db.log_activity(token.user_id, get_display_name(user) if user else "unknown",
                          "host_key_accept", f"Accepted host key for service '{service.get('name')}' ({fp})")
    await security_event("host_key_accepted", request=request, user=user, user_id=token.user_id,
                         details={"kind": "service", "id": service["id"], "fingerprint": fp})
    return web.json_response({"status": "accepted", "fingerprint": fp})


async def http_users_lookup(request: web.Request) -> web.Response:
    """Username prefix search for the share/grant picker (any authed user).

    Returns only {id, username} — no role, email or status."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    q = request.query.get("q", "")
    results = await db.find_usernames(q, limit=10)
    return web.json_response({"users": results})


async def http_list_connection_shares(request: web.Request) -> web.Response:
    """List who a connection is shared with (owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    conn_uuid = request.match_info.get("id", "")
    connection = await db.get_user_connection_by_uuid(conn_uuid, token.user_id)
    if not connection:
        return web.json_response({"error": "Connection not found"}, status=404)
    shares = await db.list_connection_shares(connection["id"])
    return web.json_response({"shares": shares})


async def http_add_connection_shares(request: web.Request) -> web.Response:
    """Share a connection with one or more users by username (owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    conn_uuid = request.match_info.get("id", "")
    connection = await db.get_user_connection_by_uuid(conn_uuid, token.user_id)
    if not connection:
        return web.json_response({"error": "Connection not found"}, status=404)
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)

    usernames = data.get("usernames") or ([data["username"]] if data.get("username") else [])
    added, skipped = [], []
    for name in usernames[:50]:
        u = await db.get_user_by_username(str(name).strip())
        if not u or u["id"] == token.user_id:
            skipped.append(name)
            continue
        if await db.add_connection_share(connection["id"], u["id"], token.user_id):
            added.append(u["username"])
        else:
            skipped.append(name)
    if added:
        actor = await db.get_user_by_id(token.user_id)
        await audit_log(
            "connection.share", token.user_id, (actor or {}).get("username", "unknown"),
            target_id=connection["id"], target_type="connection",
            target_name=connection.get("name"), details={"grantees": added},
        )
    return web.json_response({"added": added, "skipped": skipped,
                              "shares": await db.list_connection_shares(connection["id"])})


async def http_remove_connection_share(request: web.Request) -> web.Response:
    """Revoke a share. Owner may revoke anyone; a grantee may pass 'me'."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    conn_uuid = request.match_info.get("id", "")
    grantee_raw = request.match_info.get("grantee", "")

    if grantee_raw == "me":
        connection = await db.get_accessible_connection(conn_uuid, token.user_id)
        if not connection or not connection.get("shared"):
            return web.json_response({"error": "Not a shared connection"}, status=404)
        await db.remove_connection_share(connection["id"], token.user_id)
        return web.json_response({"success": True})

    connection = await db.get_user_connection_by_uuid(conn_uuid, token.user_id)
    if not connection:
        return web.json_response({"error": "Connection not found"}, status=404)
    if not grantee_raw.isdigit():
        return web.json_response({"error": "Invalid grantee"}, status=400)
    ok = await db.remove_connection_share(connection["id"], int(grantee_raw))
    if ok:
        actor = await db.get_user_by_id(token.user_id)
        await audit_log(
            "connection.unshare", token.user_id, (actor or {}).get("username", "unknown"),
            target_id=connection["id"], target_type="connection",
            target_name=connection.get("name"), details={"grantee_id": int(grantee_raw)},
        )
    return web.json_response({"success": ok,
                              "shares": await db.list_connection_shares(connection["id"])})


# =============================================================================
# User Streams API (OBS/RTMP streaming)
# =============================================================================


def generate_stream_key() -> str:
    """Generate a unique private stream key for OBS/RTMP publishing."""
    import secrets
    return f"live_{secrets.token_urlsafe(24)}"


def generate_public_key() -> str:
    """Generate a unique public key for read-only stream access (viewing)."""
    import secrets
    return f"pub_{secrets.token_urlsafe(16)}"


async def http_list_user_streams(request: web.Request) -> web.Response:
    """List all streams for the authenticated user."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    streams = await db.get_user_streams(token.user_id)
    # How many members follow each of the owner's streams: a number, never names
    counts = await db.count_followers_for_streams([s["id"] for s in streams])
    # Strip internal hash fields — these are implementation details not needed by clients
    for stream in streams:
        stream.pop("stream_key_hash", None)
        stream.pop("public_key_hash", None)
        stream["follower_count"] = counts.get(stream["id"], 0)
    return web.json_response({"streams": streams})


_STREAM_NAME_MAX = 100
_STREAM_DESCRIPTION_MAX = 2000
_STREAM_FLAG_FIELDS = ("is_public", "allow_unauthenticated", "rtmp_enabled")
_GOLIVE_MESSAGE_MAX = 200
_GOLIVE_AUDIENCES = ("followers", "everyone")
# Looked at before the per-character control-character strip, so a huge body cannot keep the
# event loop busy; generous enough that a message of mostly control characters still passes.
_GOLIVE_MESSAGE_PRESTRIP_MAX = 1000


def _strip_control_chars(text: str) -> str:
    """Text without control characters: tab, newline and carriage return become a
    space, every other control, line/paragraph separator and bidirectional override
    is dropped. Runs of spaces are kept as typed."""
    out = []
    for ch in text:
        if ch in "\t\n\r":
            out.append(" ")
        elif (unicodedata.category(ch) == "Cc" or ch in "\u2028\u2029"
              or "\u202a" <= ch <= "\u202e" or "\u2066" <= ch <= "\u2069"):
            continue
        else:
            out.append(ch)
    return "".join(out)


def _has_surrogate(text: str) -> bool:
    """True when the text holds a lone surrogate code point (JSON allows "\\ud800"; UTF-8
    cannot encode it, so storing or sending it later fails with a 500)."""
    try:
        text.encode("utf-8")
    except UnicodeEncodeError:
        return True
    return False


def _validate_stream_fields(data: dict):
    """Check the types of the stream settings a client sent (create and update).

    Returns (clean, None) with the checked values (flags stored as 0/1, name and
    description stripped), or (None, message) for the first invalid one. Only the
    fields present in `data` are looked at.
    """
    clean = {}
    for key in _STREAM_FLAG_FIELDS:
        if key in data:
            v = data[key]
            if type(v) is bool or (type(v) is int and v in (0, 1)):
                clean[key] = int(v)
            else:
                return None, f"{key} must be true, false, 0 or 1"
    for key in ("name", "description", "golive_message"):
        v = data.get(key)
        if isinstance(v, str) and _has_surrogate(v):
            return None, f"{key} contains characters that cannot be stored"
    if "name" in data:
        v = data["name"]
        if not isinstance(v, str) or not v.strip():
            return None, "Stream name is required"
        if len(v.strip()) > _STREAM_NAME_MAX:
            return None, f"Stream name must be at most {_STREAM_NAME_MAX} characters"
        clean["name"] = v.strip()
    if "description" in data:
        v = data["description"]
        if v is not None and not isinstance(v, str):
            return None, "description must be a string or null"
        if v is not None and len(v) > _STREAM_DESCRIPTION_MAX:
            return None, f"description must be at most {_STREAM_DESCRIPTION_MAX} characters"
        clean["description"] = v.strip() if v is not None else None
    if "golive_message" in data:
        v = data["golive_message"]
        if v is not None and not isinstance(v, str):
            return None, "golive_message must be a string or null"
        if v is not None and len(v) > _GOLIVE_MESSAGE_PRESTRIP_MAX:
            return None, f"golive_message must be at most {_GOLIVE_MESSAGE_MAX} characters"
        v = _strip_control_chars(v).strip() if v is not None else ""
        if len(v) > _GOLIVE_MESSAGE_MAX:
            return None, f"golive_message must be at most {_GOLIVE_MESSAGE_MAX} characters"
        clean["golive_message"] = v or None      # empty: the default message is used
    if "golive_audience" in data:
        v = data["golive_audience"]
        if v not in _GOLIVE_AUDIENCES:
            return None, "golive_audience must be \"followers\" or \"everyone\""
        clean["golive_audience"] = v
    return clean, None


# ---------------------------------------------------------------------------
# Go-live announcement: cooldown, message template, payload
# ---------------------------------------------------------------------------

# A stream is announced at most once per cooldown, however often it starts again
# (a retried media hook, an encoder restarted a few times). Kept in the database.
_GOLIVE_COOLDOWN_SECONDS = 600
_golive_now = time               # module level so tests can move the clock
_GOLIVE_DEFAULT_MESSAGE = "{title} just went live"
_GOLIVE_RENDER_MAX = 400
_GOLIVE_PLACEHOLDER = re.compile(r"\{(streamer|title|url)\}")
_PUBLIC_HOST_RE = re.compile(r"^[A-Za-z0-9.-]{1,253}$")


def _render_golive_message(template, streamer: str, title: str, url: str) -> str:
    """The go-live message: the template with {streamer}, {title} and {url} replaced
    by literal text in a single pass. Nothing else is interpreted: any other brace
    text (including '{0.__class__}') stays as written, and a value that itself
    contains '{url}' is not replaced again. No str.format, no template engine."""
    tpl = template if isinstance(template, str) and template.strip() else _GOLIVE_DEFAULT_MESSAGE
    values = {"streamer": _strip_control_chars(str(streamer or "")),
              "title": _strip_control_chars(str(title or "")),
              "url": _strip_control_chars(str(url or ""))}
    out = _GOLIVE_PLACEHOLDER.sub(lambda m: values[m.group(1)], _strip_control_chars(tpl))
    return " ".join(out.split())[:_GOLIVE_RENDER_MAX]


def _public_base_url() -> str:
    """The portal's public base URL ("https://host[:port]", no path), from the
    PUBLIC_BASE_URL setting or else https:// plus the configured HOSTNAME. Never
    from a request's Host header. Empty when nothing usable is configured."""
    configured = (Config.PUBLIC_BASE_URL or "").strip()
    if configured:
        try:
            parts = urlsplit(configured)
            port = parts.port
        except ValueError:
            return ""
        if (parts.scheme in ("http", "https") and parts.hostname and _PUBLIC_HOST_RE.match(parts.hostname)
                and not parts.username and not parts.password
                and parts.path in ("", "/") and not parts.query and not parts.fragment):
            return f"{parts.scheme}://{parts.hostname}" + (f":{port}" if port else "")
        return ""
    host = (Config.HOSTNAME or "").strip()
    return f"https://{host}" if _PUBLIC_HOST_RE.match(host) else ""


def _watch_url(stream_id: int) -> str:
    """The logged-in watch page of a stream (no share key in it)."""
    base = _public_base_url()
    return f"{base}/watch/{int(stream_id)}" if base else ""


def _golive_payload(stream: dict) -> dict:
    """What a go-live announcement carries: the streamer's display name, the title,
    the watch URL and the rendered message. Never a stream key, a pub_ key, an
    RTMP address or a path."""
    streamer = stream.get("owner_nickname") or stream.get("owner_username") or "Someone"
    title = stream.get("name") or ""
    url = _watch_url(stream["id"])
    return {
        "stream_id": stream["id"], "stream_name": title,
        "owner_username": stream.get("owner_username"),
        "streamer": streamer, "title": title, "url": url,
        "message": _render_golive_message(stream.get("golive_message"), streamer, title, url),
    }


_GOLIVE_BATCH = 100               # notifications inserted per transaction
_golive_tasks: set = set()        # strong references: a task nobody holds can be collected mid-run


def _spawn_go_live(stream_id: int) -> asyncio.Task:
    """Start the announcement in the background so the publish hook answers at once."""
    task = asyncio.create_task(_announce_go_live(stream_id), name="golive-fanout")
    _golive_tasks.add(task)
    task.add_done_callback(_golive_tasks.discard)
    return task


def _go_live_card_text(payload: dict) -> str:
    """The plain-text fallback of a go-live card (what a client that does not know
    the stream_card type shows): streamer, title and the logged-in watch link."""
    text = f"{payload['streamer']} is live: {payload['title']}"
    return f"{text} - {payload['url']}" if payload.get("url") else text


async def _channel_open_to_members(channel) -> bool:
    """Whether an ordinary member (any member, no special standing) can read the channel."""
    return bool(await _can_read_channel(channel, 0, "user"))


async def _announce_channel(stream: dict):
    """The admin's announce channel when a card for this stream may go there, else
    None. Only for a public stream, and only while the channel is one an ordinary
    member can read (not private, not the chat of a stream that is not public).
    Judged again at every announcement, not only when the setting was saved."""
    if not stream.get("is_public"):
        return None
    raw = await db.get_setting("stream_announce_channel_id")
    if not raw or not str(raw).isdigit():
        return None
    channel = await db.get_chat_channel(int(raw))
    if not channel or not await _channel_open_to_members(channel):
        return None
    return channel


async def _post_go_live_card(stream: dict, payload: dict, channel: dict) -> Optional[int]:
    """Insert one stream_card message (a system post by the stream's owner, through
    the normal encrypted insert) into `channel` and show it to the people in it.
    Returns the message id. If the card cannot be linked to its stream, the message is
    removed again and the error is raised."""
    streamer = payload["streamer"]
    # The message row and the search index carry the account username, as a normal send
    # does; the display name lives only in the card data (and the frame shown to the room).
    account = stream.get("owner_username")
    if not account:
        owner = await db.get_user_by_id(stream["user_id"])
        account = (owner or {}).get("username") or streamer
    msg_id = await db.create_chat_message(
        channel["id"], stream["user_id"], account, _go_live_card_text(payload), message_type="stream_card")
    try:
        await db.add_stream_card(msg_id, stream["id"], channel["id"], streamer, payload["title"])
    except Exception:
        # The stream is gone (foreign key) or the insert failed: nothing else can find
        # this message, so it goes now, with its search entry, and the caller logs it.
        try:
            await db.delete_chat_message(msg_id)
        except Exception as e:
            logger.warning(f"Removing the unlinked go-live card {msg_id} failed: {type(e).__name__}: {e}")
        raise
    await broadcast_to_channel(channel["name"], {
        "type": "message", "id": msg_id, "user_id": stream["user_id"], "username": streamer,
        "message": _go_live_card_text(payload), "message_type": "stream_card",
        "card": {"stream_id": stream["id"], "streamer": streamer, "title": payload["title"]},
        "role": "user", "anonymous": False, "avatar": {}, "reactions": [],
        "created_at": datetime.now(timezone.utc).isoformat()})
    return msg_id


async def _remove_stream_cards(stream_id: int, only_open_to_members: bool) -> int:
    """Delete a stream's go-live cards and tell the rooms they were in.

    With only_open_to_members, only the card in the stream's own chat stays, and only
    while that chat is closed to ordinary members (the stream is not public), so the
    owner and admins keep it. A card in any other channel goes, whoever can read that
    channel (a private channel with members is no reason to keep it: those members
    may not watch the stream). Without it (the stream is deleted) every card goes.
    Never raises."""
    removed = 0
    try:
        own_id = None
        if only_open_to_members:
            stream = await db.get_user_stream(stream_id)
            own_id = stream.get("chat_channel_id") if stream else None
        for card in await db.get_cards_of_stream(stream_id):
            channel = await db.get_chat_channel(card["channel_id"])
            if (only_open_to_members and channel and own_id and card["channel_id"] == own_id
                    and not await _channel_open_to_members(channel)):
                continue
            await db.scrub_reply_previews(card["message_id"])     # a reply keeps no copy of the card's text
            if await db.delete_chat_message(card["message_id"]):
                removed += 1
                if channel:
                    await broadcast_to_channel(channel["name"], {
                        "type": "message_deleted", "message_id": card["message_id"], "deleted_by": None})
    except Exception as e:
        logger.warning(f"Removing go-live cards of stream {stream_id} failed: {type(e).__name__}: {e}")
    return removed


async def _post_go_live_cards(stream: dict, payload: dict) -> None:
    """The announce card: into the stream's own chat and, when allowed, the announce channel.

    A stream that is not public never gets a card in a channel ordinary members can
    read (its own chat is closed to them, except a default channel, which is
    skipped for that reason)."""
    targets = []
    own = await db.get_chat_channel(stream["chat_channel_id"]) if stream.get("chat_channel_id") else None
    if own and (stream.get("is_public") or not await _channel_open_to_members(own)):
        targets.append(own)
    extra = await _announce_channel(stream)
    if extra and not any(extra["id"] == t["id"] for t in targets):
        targets.append(extra)
    written = []          # (message id, channel) of the cards this run wrote
    for channel in targets:
        try:
            written.append((await _post_go_live_card(stream, payload, channel), channel))
        except Exception as e:
            logger.warning(f"Go-live card for stream {stream['id']} in channel {channel['id']} failed: "
                           f"{type(e).__name__}: {e}")
    # The stream may have been made private while the cards were being written
    fresh = await db.get_user_stream(stream["id"])
    if fresh and not fresh.get("is_public"):
        await _remove_stream_cards(stream["id"], only_open_to_members=True)
    elif fresh is None:
        # The stream was deleted while they were written: its card rows went with it
        # (cascade), so _remove_stream_cards cannot find them. Remove the messages
        # written in this run directly. Never raises.
        for msg_id, channel in written:
            try:
                await db.scrub_reply_previews(msg_id)
                if await db.delete_chat_message(msg_id):
                    await broadcast_to_channel(channel["name"], {
                        "type": "message_deleted", "message_id": msg_id, "deleted_by": None})
            except Exception as e:
                logger.warning(f"Removing go-live card {msg_id} of deleted stream {stream['id']} failed: "
                               f"{type(e).__name__}: {e}")


async def _notify_go_live(stream: dict, payload: dict) -> int:
    """The in-portal notification for a go-live, to the stream's audience.

    'followers': the members who follow it; 'everyone': every member. In both cases
    only a member who may watch the stream at that moment (checked again for each
    batch against the stream as it is then) and never the streamer. Inserted in
    batches of _GOLIVE_BATCH, one commit each, yielding to the event loop between
    batches, then pushed to the sockets that are open. Returns the number notified."""
    stream_id = stream["id"]
    if (stream.get("golive_audience") or "everyone") == "followers":
        candidates = await db.get_follower_audience(stream_id)
    else:
        candidates = await db.get_all_users()
    data = {"stream_id": stream_id, "streamer": payload["streamer"], "title": payload["title"]}
    if payload["url"]:
        data["url"] = payload["url"]
    title = f"{payload['streamer']} is live!"
    notified = 0
    for i in range(0, len(candidates), _GOLIVE_BATCH):
        current = await db.get_user_stream(stream_id) or None      # access as it is now
        if not current:
            break
        rows = []
        for user in candidates[i:i + _GOLIVE_BATCH]:
            uid = user["id"]
            role = user.get("role") or ("admin" if user.get("is_admin") else "user")
            if uid == current.get("user_id") or not _stream_read_allowed(current, uid, role, False):
                continue
            rows.append((uid, "stream_live", title, payload["message"], data))
        if rows:
            for uid, notif_id in await db.create_notifications_bulk(rows):
                await _push_notification_frame(uid, notif_id, "stream_live", title, payload["message"], data)
            notified += len(rows)
        await asyncio.sleep(0)
    return notified


async def _announce_go_live(stream_id: int) -> None:
    """Tell people a stream went live: the stream.live webhook, the announce card(s)
    in chat and the in-portal notification to the stream's audience (only to those
    who may watch it). The caller has already won the cooldown (db.claim_golive);
    this runs in the background and never raises."""
    try:
        stream = await db.get_user_stream(stream_id)
        if not stream:
            return
        payload = _golive_payload(stream)
        asyncio.create_task(fire_webhook_event(
            "stream.live", payload, meta={"stream_public": bool(stream.get("is_public"))}))
    except Exception as e:
        logger.warning(f"Go-live announcement for stream {stream_id} failed: {type(e).__name__}: {e}")
        return
    for step in (_post_go_live_cards, _notify_go_live):
        try:
            await step(stream, payload)
        except Exception as e:
            logger.warning(f"Go-live {step.__name__.strip('_')} for stream {stream_id} failed: "
                           f"{type(e).__name__}: {e}")


async def http_create_user_stream(request: web.Request) -> web.Response:
    """Create a new stream for the authenticated user."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    # Check if non-admin users are allowed to create streams
    if not token.has_scope("admin") and not token.has_scope("*"):
        allow = await db.get_setting("allow_user_streams")
        if allow == "false":
            return web.json_response({"error": "Creating streams is currently disabled by an administrator"}, status=403)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    if not isinstance(data, dict):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    clean, problem = _validate_stream_fields(data)
    if problem:
        return web.json_response({"error": problem}, status=400)
    if "name" not in clean:
        return web.json_response({"error": "Stream name is required"}, status=400)
    name = clean["name"]
    description = clean.get("description") or ""
    is_public = bool(clean.get("is_public", 0))
    audience = clean.get("golive_audience", "followers")      # a new stream announces to followers

    # Generate unique keys
    stream_key = generate_stream_key()  # Private key for publishing
    public_key = generate_public_key()  # Public key for viewing

    try:
        stream_id = await db.create_user_stream(
            user_id=token.user_id,
            name=name,
            stream_key=stream_key,
            public_key=public_key,
            description=description,
            is_public=is_public,
            golive_audience=audience
        )

        # Create a chat channel for every stream
        try:
            user = await db.get_user_by_id(token.user_id)
            channel_name = f"stream-{user['username']}-{stream_id}"
            chat_channel_id = await db.create_chat_channel(
                name=channel_name,
                description=f"Chat for {name} by {user['username']}",
                created_by=token.user_id
            )
            await db.update_user_stream(stream_id, chat_channel_id=chat_channel_id)
        except Exception as chan_err:
            # Chat channel failed — delete the orphaned stream
            logger.error(f"Failed to create chat channel for stream {stream_id}: {chan_err}")
            await db.delete_user_stream(stream_id, token.user_id)
            return web.json_response({"error": "Failed to create stream chat channel"}, status=500)

        stream = await db.get_user_stream(stream_id)
        # Strip internal hash fields from response
        if stream:
            stream.pop("stream_key_hash", None)
            stream.pop("public_key_hash", None)
        return web.json_response({"stream": stream}, status=201)

    except Exception as e:
        if "UNIQUE constraint failed" in str(e):
            return web.json_response({"error": "Stream name already exists"}, status=409)
        logger.error(f"Failed to create stream: {e}")
        return web.json_response({"error": "Failed to create stream"}, status=500)


_SQLITE_INT_MAX = 2 ** 63 - 1


def _row_id(raw) -> int:
    """An id taken from a URL, ready for the database. Not a number: ValueError, as int().
    A number SQLite cannot hold (it would raise OverflowError, a 500) is turned into 0, an id
    no row has, so the handler gives the same answer as for an unknown id."""
    value = int(raw)
    if value < 1 or value > _SQLITE_INT_MAX:
        return 0
    return value


async def http_get_user_stream(request: web.Request) -> web.Response:
    """Get a specific stream by numeric ID or public key (pub_xxx).

    Key visibility rules:
    - Owner: sees both stream_key (for OBS) and public_key (for sharing)
    - Non-owner viewing public stream: sees public_key only (for playback)
    - Non-owner viewing private stream: no keys visible
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    stream_id = request.match_info.get("id")

    # Accept either numeric ID or public key (pub_xxx)
    stream = None
    if stream_id and stream_id.startswith("pub_"):
        stream = await db.get_stream_by_public_key(stream_id)
    else:
        try:
            stream = await db.get_user_stream(_row_id(stream_id))
        except (ValueError, TypeError):
            return web.json_response({"error": "Invalid stream ID"}, status=400)

    if not stream:
        return web.json_response({"error": "Stream not found"}, status=404)

    is_owner = stream["user_id"] == token.user_id
    is_public = stream.get("is_public", False)
    is_admin = token.has_scope("admin") or token.has_scope("*")

    # Non-owners cannot access private streams (return 404 to prevent enumeration)
    if not is_owner and not is_public and not is_admin:
        return web.json_response({"error": "Stream not found"}, status=404)

    # Always strip internal hash fields — these are implementation details
    stream.pop("stream_key_hash", None)
    stream.pop("public_key_hash", None)

    if not is_owner:
        # Always hide the private stream_key from non-owners
        stream.pop("stream_key", None)
        # Also hide public_key for private streams, except from an admin by role (not by
        # token scope): the read gate lets them watch it, and playback needs the key.
        if not is_public and not (has_full_user_scope(token)
                                  and await get_user_role_from_token(token) in ("admin", "superadmin")):
            stream.pop("public_key", None)
    if is_owner:
        stream["follower_count"] = await db.count_followers(stream["id"])    # a number, never names
    if has_full_user_scope(token):      # a stream key is not a login as its owner: no follow state
        stream["following"] = stream["id"] in set(await db.get_followed_stream_ids(token.user_id))

    return web.json_response({"stream": stream})


# The stream fields a client may change (what the stream settings screen sends)
_STREAM_CLIENT_FIELDS = frozenset({"name", "description", "is_public",
                                   "allow_unauthenticated", "rtmp_enabled", "golive_message",
                                   "golive_audience"})


async def http_update_user_stream(request: web.Request) -> web.Response:
    """Update a stream (owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    stream_id = request.match_info.get("id")
    try:
        stream_id = _row_id(stream_id)
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid stream ID"}, status=400)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    # Get existing stream to check ownership
    stream = await db.get_user_stream(stream_id)
    if not stream:
        return web.json_response({"error": "Stream not found"}, status=404)

    if stream["user_id"] is not None and stream["user_id"] != token.user_id:
        return web.json_response({"error": "Stream not found"}, status=404)

    # Only what the stream settings screen sends is taken from the client. The
    # chat channel, live state, viewer count and start/end times belong to the
    # server: a client that could name them could bind its stream to another
    # channel (hiding it, and deleting it with the stream) or fake being live.
    if not isinstance(data, dict):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    data = {k: v for k, v in data.items() if k in _STREAM_CLIENT_FIELDS}
    if not data:
        return web.json_response({"error": "No editable stream fields given"}, status=400)
    data, problem = _validate_stream_fields(data)
    if problem:
        return web.json_response({"error": problem}, status=400)

    # Create chat channel if one doesn't exist (for legacy streams)
    if not stream.get("chat_channel_id"):
        user = await db.get_user_by_id(token.user_id)
        channel_name = f"stream-{user['username']}-{stream_id}"
        chat_channel_id = await db.create_chat_channel(
            name=channel_name,
            description=f"Chat for {stream['name']} by {user['username']}",
            created_by=token.user_id
        )
        data["chat_channel_id"] = chat_channel_id

    # A stream switched from public to private must not keep a playback key that
    # may have been shared while it was public.
    became_private = (
        "is_public" in data and not data["is_public"] and bool(stream.get("is_public"))
    )

    success = await db.update_user_stream(stream_id, user_id=token.user_id, **data)
    if success:
        # Viewers are asked again at once; a viewer who lost access gets no new
        # playlist or segment from here on.
        _stream_access_changed(stream_id, drop_sessions=any(
            k in data and bool(data[k]) != bool(stream.get(k)) for k in ("is_public", "allow_unauthenticated")))
        if "is_public" in data and bool(data["is_public"]) != bool(stream.get("is_public")):
            # A visibility change in either direction starts follows afresh. Going private
            # drops them all; going public drops what is left from while it was private (an
            # administrator who followed it and was demoted since), so no stale follow wakes up.
            await db.remove_stream_follows(stream_id)
        rotated_key = None
        if became_private:
            rotated_key = generate_public_key()
            if not await db.regenerate_public_key(stream_id, rotated_key, user_id=token.user_id):
                rotated_key = None
                logger.error(f"Failed to rotate playback key for stream {stream_id} after it became private")
            _stream_access_changed(stream_id)
        if not (data["is_public"] if "is_public" in data else stream.get("is_public")):
            # Sockets already in the chat room (and its voice call) belong to members
            # who can no longer read it: put them out now, not at their next request.
            # Whenever the stream is not public after the update, also when the
            # request did not carry is_public (the stream was private already: the
            # room may still hold sockets from before).
            await _evict_unreadable_by_id(stream.get("chat_channel_id") or data.get("chat_channel_id"))
            # Its go-live cards leave every channel ordinary members can read (the
            # announce channel). Follows are cleared by the visibility change above, not
            # here: an edit of a stream that is already private must keep the follows its
            # owner and administrators made.
            await _remove_stream_cards(stream_id, only_open_to_members=True)
        # Revoke all RTMP tokens if rtmp_enabled was toggled off
        if data.get("rtmp_enabled") is False or data.get("rtmp_enabled") == 0:
            revoked = await db.revoke_rtmp_tokens_for_stream(stream_id)
            if revoked:
                logger.info(f"Revoked {revoked} RTMP token(s) for stream {stream_id}")
        updated_stream = await db.get_user_stream(stream_id)
        # Strip internal hash fields from response
        if updated_stream:
            updated_stream.pop("stream_key_hash", None)
            updated_stream.pop("public_key_hash", None)
        response = {"stream": updated_stream}
        if rotated_key:
            response["public_key"] = rotated_key
        return web.json_response(response)
    return web.json_response({"error": "Failed to update stream"}, status=500)


async def http_delete_user_stream(request: web.Request) -> web.Response:
    """Delete a stream (owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    stream_id = request.match_info.get("id")
    try:
        stream_id = _row_id(stream_id)
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid stream ID"}, status=400)

    stream = await db.get_user_stream(stream_id)
    if not stream:
        return web.json_response({"error": "Stream not found"}, status=404)

    # Verify ownership before any mutations
    if stream["user_id"] is not None and stream["user_id"] != token.user_id:
        return web.json_response({"error": "Stream not found"}, status=404)

    # The go-live cards are chat messages; they are removed with the stream
    await _remove_stream_cards(stream_id, only_open_to_members=False)
    success = await db.delete_user_stream(stream_id, user_id=token.user_id)
    if not success:
        return web.json_response({"error": "Stream not found"}, status=404)
    _stream_access_changed(stream_id)

    # Delete the chat channel with its stream, unless it is a default channel or
    # another stream still uses it (delete_chat_channel refuses default channels)
    if stream.get("chat_channel_id") and not await db.count_streams_for_chat_channel(stream["chat_channel_id"]):
        await db.delete_chat_channel(stream["chat_channel_id"])

    return web.json_response({"success": True})


async def http_regenerate_stream_key(request: web.Request) -> web.Response:
    """Regenerate stream key (owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    stream_id = request.match_info.get("id")
    try:
        stream_id = _row_id(stream_id)
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid stream ID"}, status=400)

    new_key = generate_stream_key()

    success = await db.regenerate_stream_key(stream_id, new_key, user_id=token.user_id)
    if success:
        _stream_access_changed(stream_id)
        return web.json_response({"stream_key": new_key})
    return web.json_response({"error": "Not authorized or stream not found"}, status=403)


async def http_regenerate_public_key(request: web.Request) -> web.Response:
    """Rotate the playback key ("share link") of a stream (owner only).

    The previous pub_ key stops resolving immediately; the new key is returned.
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    stream_id = request.match_info.get("id")
    try:
        stream_id = _row_id(stream_id)
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid stream ID"}, status=400)

    new_key = generate_public_key()

    success = await db.regenerate_public_key(stream_id, new_key, user_id=token.user_id)
    if success:
        _stream_access_changed(stream_id)
        return web.json_response({"public_key": new_key})
    return web.json_response({"error": "Not authorized or stream not found"}, status=403)


async def http_create_rtmp_token(request: web.Request) -> web.Response:
    """Generate a temporary RTMP publish token (owner only).

    Returns a single-use token for plain RTMP (non-TLS) publishing.
    Token expires after RTMP_TOKEN_EXPIRY_MINUTES (default 15 min).
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    # Global kill switch
    if not Config.RTMP_PLAIN_ENABLED:
        return web.json_response({"error": "Plain RTMP is not enabled on this server"}, status=403)

    stream_id = request.match_info.get("id")
    try:
        stream_id = _row_id(stream_id)
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid stream ID"}, status=400)

    # Verify ownership and rtmp_enabled
    stream = await db.get_user_stream(stream_id)
    if not stream:
        return web.json_response({"error": "Stream not found"}, status=404)
    if stream["user_id"] != token.user_id:
        return web.json_response({"error": "Not authorized"}, status=403)
    if not stream.get("rtmp_enabled"):
        return web.json_response({"error": "RTMP is not enabled for this stream"}, status=400)

    # Generate token: rtmp_ prefix + 32 random URL-safe chars
    rtmp_token = f"rtmp_{secrets.token_urlsafe(24)}"
    token_hash = hashlib.sha256(rtmp_token.encode()).hexdigest()
    expires_at = (datetime.now(timezone.utc) + timedelta(minutes=Config.RTMP_TOKEN_EXPIRY_MINUTES)).isoformat()

    await db.create_rtmp_token(stream_id, token.user_id, token_hash, expires_at)

    # RTMP URL uses the streaming hostname (direct, bypasses Cloudflare)
    rtmp_url = f"rtmp://{Config.STREAM_HOSTNAME}:{Config.RTMP_PLAIN_PORT}/live"

    return web.json_response({
        "token": rtmp_token,
        "expires_in": Config.RTMP_TOKEN_EXPIRY_MINUTES * 60,
        "grace_seconds": Config.RTMP_TOKEN_GRACE_SECONDS,
        "rtmp_url": rtmp_url,
    })


async def http_upload_stream_thumbnail(request: web.Request) -> web.Response:
    """Upload a thumbnail for a stream (owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    stream_id = request.match_info.get("id")
    try:
        stream_id = _row_id(stream_id)
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid stream ID"}, status=400)

    # Get existing stream to check ownership
    stream = await db.get_user_stream(stream_id)
    if not stream:
        return web.json_response({"error": "Stream not found"}, status=404)

    if stream["user_id"] is not None and stream["user_id"] != token.user_id:
        return web.json_response({"error": "Stream not found"}, status=404)

    # Parse multipart data
    try:
        reader = await request.multipart()
        field = await reader.next()

        if field is None or field.name != "thumbnail":
            return web.json_response({"error": "No thumbnail file provided"}, status=400)

        # Validate content type
        content_type = field.headers.get(aiohttp.hdrs.CONTENT_TYPE, "")
        if not content_type.startswith("image/"):
            return web.json_response({"error": "File must be an image"}, status=400)

        # Determine file extension
        ext_map = {
            "image/jpeg": ".jpg",
            "image/png": ".png",
            "image/gif": ".gif",
            "image/webp": ".webp",
        }
        ext = ext_map.get(content_type, ".jpg")

        # Generate unique filename
        filename = f"{uuid.uuid4().hex}{ext}"
        upload_dir = Path(__file__).parent / "static" / "uploads" / "thumbnails"
        upload_dir.mkdir(parents=True, exist_ok=True)
        filepath = upload_dir / filename

        # Read and save file (limit to 5MB)
        size = 0
        max_size = 5 * 1024 * 1024  # 5MB

        with open(filepath, "wb") as f:
            while True:
                chunk = await field.read_chunk()
                if not chunk:
                    break
                size += len(chunk)
                if size > max_size:
                    f.close()
                    filepath.unlink()
                    return web.json_response({"error": "File too large (max 5MB)"}, status=400)
                f.write(chunk)

        # Delete old thumbnail if exists (with path traversal protection)
        if stream.get("thumbnail_url"):
            thumb_dir = (Path(__file__).parent / "static" / "uploads" / "thumbnails").resolve()
            old_path = (Path(__file__).parent / stream["thumbnail_url"].lstrip("/")).resolve()
            if old_path.exists() and str(old_path).startswith(str(thumb_dir)):
                try:
                    old_path.unlink()
                except OSError:
                    pass

        # Update database with new thumbnail URL
        thumbnail_url = f"/static/uploads/thumbnails/{filename}"
        await db.update_user_stream(stream_id, user_id=token.user_id, thumbnail_url=thumbnail_url)

        return web.json_response({
            "success": True,
            "thumbnail_url": thumbnail_url
        })

    except Exception as e:
        logger.error(f"Thumbnail upload error: {e}")
        return web.json_response({"error": "Upload failed"}, status=500)


async def http_delete_stream_thumbnail(request: web.Request) -> web.Response:
    """Delete a stream's thumbnail (owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    stream_id = request.match_info.get("id")
    try:
        stream_id = _row_id(stream_id)
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid stream ID"}, status=400)

    stream = await db.get_user_stream(stream_id)
    if not stream:
        return web.json_response({"error": "Stream not found"}, status=404)

    if stream["user_id"] != token.user_id:
        return web.json_response({"error": "Not authorized"}, status=403)

    # Delete file if exists (with path traversal protection)
    if stream.get("thumbnail_url"):
        thumb_dir = (Path(__file__).parent / "static" / "uploads" / "thumbnails").resolve()
        old_path = (Path(__file__).parent / stream["thumbnail_url"].lstrip("/")).resolve()
        if old_path.exists() and str(old_path).startswith(str(thumb_dir)):
            try:
                old_path.unlink()
            except OSError:
                pass

    # Clear thumbnail URL in database
    await db.update_user_stream(stream_id, user_id=token.user_id, thumbnail_url=None)

    return web.json_response({"success": True})


async def _chat_role_of_user(user_id) -> str:
    """Role used for chat policy decisions, honouring the legacy admin flag."""
    user = await db.get_user_by_id(user_id)
    if not user:
        return "user"
    return user.get("role") or ("superadmin" if user.get("is_admin") else "user")


async def http_get_stream_bans(request: web.Request) -> web.Response:
    """Get all bans for a stream (stream owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        stream_id = _row_id(request.match_info.get("id"))
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid stream ID"}, status=400)

    # Verify ownership
    stream = await db.get_user_stream(stream_id)
    if not stream or stream["user_id"] != token.user_id:
        # Allow admins to view bans
        if not token.has_scope("admin") and not token.has_scope("*"):
            return web.json_response({"error": "Not authorized"}, status=403)

    viewer_role = await _chat_role_of_user(token.user_id)
    bans = _mask_ban_rows(await db.get_stream_bans(stream_id), token.user_id, viewer_role)
    return web.json_response({"bans": bans})


async def http_create_stream_ban(request: web.Request) -> web.Response:
    """Ban a user from stream chat (stream owner only).

    Request body:
    - user_id: int - User ID to ban
    - reason: str (optional) - Reason for ban
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        stream_id = _row_id(request.match_info.get("id"))
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid stream ID"}, status=400)

    # Verify ownership
    stream = await db.get_user_stream(stream_id)
    if not stream:
        return web.json_response({"error": "Stream not found"}, status=404)

    # Only owner or admin can ban
    if stream["user_id"] != token.user_id:
        if not token.has_scope("admin") and not token.has_scope("*"):
            return web.json_response({"error": "Not authorized"}, status=403)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    try:
        user_id = int(data.get("user_id"))
    except (TypeError, ValueError):
        return web.json_response({"error": "Valid user_id required"}, status=400)
    if abs(user_id) > _SQLITE_INT_MAX:
        return web.json_response({"error": "Valid user_id required"}, status=400)

    # Can't ban yourself
    if user_id == token.user_id:
        return web.json_response({"error": "Cannot ban yourself"}, status=400)

    # Can't ban the stream owner
    if user_id == stream["user_id"]:
        return web.json_response({"error": "Cannot ban the stream owner"}, status=400)

    reason = data.get("reason", "")

    ban_id = await db.create_stream_ban(
        stream_id=stream_id,
        user_id=user_id,
        banned_by=token.user_id,
        reason=reason
    )

    if ban_id:
        # A banned member does not stay in the stream chat's text room or its voice call.
        await _evict_unreadable_by_id(stream.get("chat_channel_id"))
        await _voice_eject_if_not_allowed(user_id)
        # Get banned user's username for the response
        banned_user = await db.get_user_by_id(user_id)
        logger.info(f"User {banned_user['username'] if banned_user else user_id} banned from stream {stream['name']} by user {token.user_id}")
        # Same alert as a ban over the websocket (and the same cooldown key). A target who
        # chats anonymously, or who cannot be found, is never named.
        banner = await db.get_user_by_id(token.user_id)
        ban_channel = await db.get_chat_channel(stream["chat_channel_id"]) if stream.get("chat_channel_id") else None
        alerts.moderation_action(
            "ban", actor=(banner["username"] if banner else "a moderator"),
            target=(banned_user["username"] if banned_user else None),
            anonymous=bool(banned_user is None or banned_user.get("chat_anonymous")),
            actor_id=token.user_id, target_id=user_id, reason=reason, where=stream["name"],
            actor_anonymous=bool(banner and banner.get("chat_anonymous")),
            actor_role=(banner or {}).get("role"),
            private=await _alert_context_private(ban_channel, stream))
        return web.json_response({
            "success": True,
            "ban_id": ban_id,
            "message": f"User banned from stream chat"
        }, status=201)

    return web.json_response({"error": "User may already be banned"}, status=400)


async def http_remove_stream_ban(request: web.Request) -> web.Response:
    """Remove a ban from stream chat (stream owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        stream_id = _row_id(request.match_info.get("id"))
        user_id = _row_id(request.match_info.get("user_id"))
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid ID"}, status=400)

    # Verify ownership
    stream = await db.get_user_stream(stream_id)
    if not stream:
        return web.json_response({"error": "Stream not found"}, status=404)

    # Only owner or admin can unban
    if stream["user_id"] != token.user_id:
        if not token.has_scope("admin") and not token.has_scope("*"):
            return web.json_response({"error": "Not authorized"}, status=403)

    # Without staff rights only the named ban goes: a ban made from an anonymous
    # post must not react to an account id the caller guessed.
    caller_role = await _chat_role_of_user(token.user_id)
    success = await db.remove_stream_ban(
        stream_id, user_id, include_anonymous=caller_role in _CHAT_STAFF_ROLES)
    if success:
        logger.info(f"User {user_id} unbanned from stream {stream['name']} by user {token.user_id}")
        return web.json_response({"success": True, "message": "User unbanned"})

    return web.json_response({"error": "Ban not found"}, status=404)


async def http_remove_stream_ban_by_id(request: web.Request) -> web.Response:
    """Remove a ban from stream chat by the id of the ban (stream owner only).

    This is the way to lift a ban made from an anonymous post: the ban list
    shows such a ban without the account, and only its ban id.
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        stream_id = _row_id(request.match_info.get("id"))
        ban_id = _row_id(request.match_info.get("ban_id"))
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid ID"}, status=400)

    stream = await db.get_user_stream(stream_id)
    if not stream:
        return web.json_response({"error": "Stream not found"}, status=404)

    # Only owner or admin can unban
    if stream["user_id"] != token.user_id:
        if not token.has_scope("admin") and not token.has_scope("*"):
            return web.json_response({"error": "Not authorized"}, status=403)

    removed = await db.remove_stream_ban_by_id(stream_id, ban_id)
    if not removed:
        return web.json_response({"error": "Ban not found"}, status=404)
    logger.info(f"Ban {ban_id} removed from stream {stream['name']} by user {token.user_id}")
    return web.json_response({"success": True, "message": "User unbanned"})


async def http_get_public_streams(request: web.Request) -> web.Response:
    """Get all public streams (community streams).

    This endpoint is accessible to all authenticated users.
    - Private stream_key is never included (security)
    - Public key (pub_xxx) is included for playback URLs
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    live_only = request.query.get("live", "false").lower() == "true"
    streams = await db.get_public_streams(live_only=live_only)

    # Remove private stream keys and internal hashes from public listing (security)
    # Keep public_key for playback URLs
    full = has_full_user_scope(token)       # a stream key is not a login as its owner: no follow state
    followed = set(await db.get_followed_stream_ids(token.user_id)) if full else set()
    for stream in streams:
        stream.pop("stream_key", None)
        stream.pop("stream_key_hash", None)
        stream.pop("public_key_hash", None)
        if full:
            stream["following"] = stream["id"] in followed  # the viewer's own follow only

    return web.json_response({"streams": streams})


# ---------------------------------------------------------------------------
# Follows and the live-now list
# ---------------------------------------------------------------------------

_STREAM_FOLLOW_NOT_FOUND = {"error": "Stream not found"}


async def _follow_context(request: web.Request):
    """(token, user_id, role) of a member using a full-authority credential, or a
    response to return. A stream key is not a way to sign in as its owner."""
    token = await authenticate_request(request, allow_stream_key=False)
    if not token:
        return None, unauthorized_response(request)
    if not has_full_user_scope(token):
        return None, forbidden_response(request)
    return (token, token.user_id, await get_user_role_from_token(token)), None


async def _viewable_stream_for_follow(request: web.Request, user_id: int, role: str):
    """The stream named in the path when this member may watch it, else None. A
    non-numeric id, an unknown stream and a stream the member may not watch are
    all the same answer: a private stream's existence is not revealed."""
    try:
        stream_id = _row_id(request.match_info.get("id", ""))
    except (ValueError, TypeError):
        return None
    stream = await db.get_user_stream(stream_id)
    if not stream or not _stream_read_allowed(stream, user_id, role, False):
        return None
    return stream


async def http_follow_stream(request: web.Request) -> web.Response:
    """PUT /api/streams/{id}/follow: follow a stream the member may watch."""
    ctx, refusal = await _follow_context(request)
    if refusal is not None:
        return refusal
    _token, user_id, role = ctx
    stream = await _viewable_stream_for_follow(request, user_id, role)
    if not stream:
        return web.json_response(_STREAM_FOLLOW_NOT_FOUND, status=404)
    result = await db.follow_stream(user_id, stream["id"])
    if result == "limit":
        return web.json_response(
            {"error": f"You can follow at most {db.FOLLOW_LIMIT_PER_USER} streams"}, status=400)
    return web.json_response({"following": True, "stream_id": stream["id"]})


async def http_unfollow_stream(request: web.Request) -> web.Response:
    """DELETE /api/streams/{id}/follow: stop following. Always answers the same
    (own follow only), whatever the stream is, so it reveals nothing."""
    ctx, refusal = await _follow_context(request)
    if refusal is not None:
        return refusal
    _token, user_id, _role = ctx
    try:
        stream_id = _row_id(request.match_info.get("id", ""))
    except (ValueError, TypeError):
        return web.json_response(_STREAM_FOLLOW_NOT_FOUND, status=404)
    if not stream_id:       # out of the database's range: no stream, so no follow
        return web.json_response(_STREAM_FOLLOW_NOT_FOUND, status=404)
    await db.unfollow_stream(user_id, stream_id)
    return web.json_response({"following": False, "stream_id": stream_id})


async def http_my_follows(request: web.Request) -> web.Response:
    """GET /api/me/follows: the streams this member follows (their own list only)."""
    ctx, refusal = await _follow_context(request)
    if refusal is not None:
        return refusal
    _token, user_id, _role = ctx
    return web.json_response({"stream_ids": await db.get_followed_stream_ids(user_id)})


async def http_live_now(request: web.Request) -> web.Response:
    """GET /api/streams/live: the streams live now that this member may watch, from
    the same state the chat's stream_status frames carry. No key of any kind."""
    token = await authenticate_request(request, allow_stream_key=False)
    if not token:
        return unauthorized_response(request)
    user_id, role = token.user_id, "user"
    if has_full_user_scope(token):
        role = await get_user_role_from_token(token)
    else:
        user_id = None          # a narrow credential is not a viewer: nothing is listed
    followed = set(await db.get_followed_stream_ids(token.user_id)) if user_id else set()
    out = []
    for st in await db.get_live_streams():
        if user_id is None or not _stream_read_allowed(st, user_id, role, False):
            continue
        out.append({"id": st["id"], "name": st["name"],
                    "streamer": st.get("owner_nickname") or st.get("owner_username") or "Someone",
                    "viewer_count": st.get("viewer_count") or 0, "started_at": st.get("started_at"),
                    "following": st["id"] in followed})
    return web.json_response({"streams": out})


async def http_get_open_streams(request: web.Request) -> web.Response:
    """Get streams that allow unauthenticated public access.

    No authentication required. Returns streams where
    is_public=1 AND allow_unauthenticated=1.
    Private stream_key is never included.
    """
    streams = await db.get_open_streams()
    return web.json_response({"streams": streams})


async def http_live_page(request: web.Request) -> web.Response:
    """Serve the public live streams page (no auth required)."""
    html = load_static_file("live.html")
    # Inject dynamic hostname for canonical URLs and OG tags
    hostname = Config.HOSTNAME or "localhost"
    html = html.replace("{{HOSTNAME}}", _html.escape(hostname))
    return web.Response(text=html, content_type="text/html")


# =============================================================================
# VOD Recording Pipeline — Chunked recording with live SFTP offload
#
# Architecture:
#   1. On stream publish, ffmpeg segments the HLS input into 5-minute MKV
#      chunks in a local staging directory.
#   2. A background uploader task polls for completed chunks and uploads
#      each to the user's remote SFTP storage, deleting the local copy
#      once confirmed.
#   3. On stream disconnect, ffmpeg is stopped, the final chunk is
#      uploaded, and the local staging directory is cleaned up.
#
# Remote folder structure:
#   {remote_path}/{StreamName}/{YYYY-MM-DD_HH-MM-SS}/
#     chunk_000.mkv
#     chunk_001.mkv
#     ...
# =============================================================================

VOD_SEGMENT_DURATION = 300  # seconds per chunk (5 minutes)


async def start_vod_recording(stream: dict, stream_key: str) -> None:
    """Start chunked VOD recording with live SFTP offload."""
    stream_id = stream["id"]
    user_id = stream["user_id"]

    if stream_id in active_recordings:
        return

    # Only record if user has VOD storage configured
    storage = await db.get_vod_storage(user_id)
    if not storage:
        logger.debug(f"No VOD storage for user {user_id}, skipping recording")
        return

    mtx_config = await _get_mediamtx_config()
    if not mtx_config:
        logger.warning("MediaMTX not configured, cannot start VOD recording")
        return

    # Use RTSPS for reliable recording (HLS LL-HLS segments expire too fast for ffmpeg)
    rtsps_port = 8322  # MediaMTX default RTSPS port (strict TLS)
    source_url = f"rtsps://127.0.0.1:{rtsps_port}/live/{stream_key}"

    # Build paths — date-only remote dir so chunks accumulate across restarts
    date_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    safe_name = re.sub(r'[^\w\s-]', '', stream.get("name", "stream")).strip().replace(' ', '_')[:50] or "stream"
    remote_base = storage["remote_path"].rstrip("/")
    remote_session_dir = f"{remote_base}/{safe_name}/{date_str}"

    # The staging folder must be usable and have room, otherwise skip this
    # recording and say so where the stream owner can see it.
    skip_reason = None
    if not _vod_staging_usable:
        skip_reason = "no usable VOD staging folder (it was refused at start; see the start-up log)"
    else:
        try:
            own = os.path.abspath(VOD_TEMP_DIR) == Config.VOD_TEMP_DIR_DEFAULT
            vod_staging.ensure_private_dir(VOD_TEMP_DIR, (STATIC_DIR,), _PROJECT_ROOT, allow_temp=own)
            enough, free = await asyncio.to_thread(vod_staging.has_free_space, VOD_TEMP_DIR, VOD_MIN_FREE_BYTES)
            if not enough:
                skip_reason = (
                    f"only {vod_staging.format_size(free)} free in the VOD staging folder "
                    f"(needs {vod_staging.format_size(VOD_MIN_FREE_BYTES)})"
                )
        except (OSError, ValueError) as e:
            skip_reason = f"VOD staging folder is not usable: {e}"
    if skip_reason:
        logger.warning(f"VOD recording not started for '{stream.get('name', '')}': {skip_reason}")
        try:
            await db.log_activity(
                user_id, get_display_name(stream), "vod_skipped",
                f"VOD recording for '{stream.get('name', '')}' was not started: {skip_reason}",
            )
        except Exception as e:
            logger.debug(f"Could not log VOD skip: {e}")
        return

    session_dir = os.path.join(VOD_TEMP_DIR, f"{stream_id}_{date_str}_{int(time())}")
    # The folder is busy from now until the recording has uploaded its last chunk
    # and cleaned up; the periodic recovery must not touch it in between.
    _vod_busy_dirs.add(session_dir)
    registered = False
    try:
        os.makedirs(session_dir, mode=0o700, exist_ok=True)
        try:
            vod_staging.write_sidecar(session_dir, {
                "stream_id": stream_id,
                "user_id": user_id,
                "stream_name": stream.get("name", ""),
                "remote_session_dir": remote_session_dir,
            })
        except OSError as e:
            logger.warning(f"Could not write VOD session record in {session_dir}: {e}")

        # Check remote SFTP for existing chunks to continue numbering
        start_number = 0
        conn, sftp, error = await _connect_vod_sftp(user_id)
        if not error:
            try:
                await _sftp_makedirs(sftp, remote_session_dir)
                existing = await sftp.listdir(remote_session_dir)
                for fname in existing:
                    m = re.match(r'chunk_(\d+)\.mkv$', fname)
                    if m:
                        n = int(m.group(1)) + 1
                        if n > start_number:
                            start_number = n
                if start_number > 0:
                    logger.info(f"VOD resuming at chunk_{start_number:03d} in {safe_name}/{date_str}")
            except Exception as e:
                logger.debug(f"Could not check remote chunks: {e}")
            finally:
                conn.close()

        # Chunks an earlier session left unuploaded for the same remote folder keep
        # their numbers; reusing one would overwrite them when they are uploaded.
        start_number = max(
            start_number,
            await asyncio.to_thread(vod_staging.next_free_chunk_number, VOD_TEMP_DIR, remote_session_dir, session_dir),
        )

        # Wait for MediaMTX stream to be ready
        await asyncio.sleep(2)

        # ffmpeg segment muxer: lossless remux into 5-minute MKV chunks via RTSPS
        cmd = [
            "ffmpeg", "-y",
            "-rtsp_transport", "tcp",
            "-i", source_url,
            "-c", "copy",
            "-f", "segment",
            "-segment_time", str(VOD_SEGMENT_DURATION),
            "-segment_format", "matroska",
            "-segment_start_number", str(start_number),
            "-reset_timestamps", "1",
            os.path.join(session_dir, "chunk_%03d.mkv"),
        ]

        try:
            process = await _media_exec(
                cmd, "best_effort",
                stdout=asyncio.subprocess.DEVNULL,
                stderr=asyncio.subprocess.PIPE,
            )
        except FileNotFoundError:
            logger.error("ffmpeg not found, cannot start VOD recording")
            vod_staging.remove_if_empty(session_dir)
            return
        except Exception as e:
            logger.error(f"Failed to start VOD recording: {e}")
            vod_staging.remove_if_empty(session_dir)
            return

        stop_event = asyncio.Event()
        recording = {
            "process": process,
            "session_dir": session_dir,
            "remote_session_dir": remote_session_dir,
            "user_id": user_id,
            "stream_name": stream.get("name", ""),
            "started_at": datetime.now(timezone.utc),
            "stop_event": stop_event,
            "upload_task": None,
            "uploaded": set(),  # local paths already uploaded
        }

        # Start background chunk uploader
        recording["upload_task"] = asyncio.create_task(
            _vod_chunk_uploader(recording)
        )

        async with _stream_state_lock:
            active_recordings[stream_id] = recording
        registered = True
        logger.info(f"VOD recording started: {safe_name}/{date_str}/ from chunk_{start_number:03d} (every {VOD_SEGMENT_DURATION}s)")
    finally:
        if not registered:
            _vod_busy_dirs.discard(session_dir)


def _vod_cleanup_session_dir(session_dir: str) -> None:
    """Remove an emptied staging directory; keep (and report) one that still holds chunks."""
    _vod_busy_dirs.discard(session_dir)
    if vod_staging.remove_if_empty(session_dir):
        return
    try:
        left = [n for n in os.listdir(session_dir) if n != vod_staging.SIDECAR_NAME]
    except OSError:
        return
    if left:
        logger.warning(
            f"VOD staging dir has {len(left)} leftover file(s): {session_dir} "
            f"(they are uploaded by the next recovery pass)"
        )


async def _vod_chunk_uploader(recording: dict) -> None:
    """Background loop that uploads completed chunks to SFTP during broadcast."""
    stop_event: asyncio.Event = recording["stop_event"]
    session_dir = recording["session_dir"]
    uploaded: set = recording["uploaded"]
    process = recording["process"]
    last_chunk_count = 0
    stale_checks = 0
    # Stale threshold: if no new chunk in 2x segment time, warn (checked every 30s)
    stale_threshold = (VOD_SEGMENT_DURATION * 2) // 30

    while not stop_event.is_set():
        # Detect if ffmpeg exited on its own (e.g. HLS source 404)
        if process.returncode is not None:
            logger.info(f"VOD ffmpeg exited (code {process.returncode}), finalizing upload")
            break
        try:
            await _do_vod_chunk_upload(recording, final=False)
        except Exception as e:
            logger.error(f"VOD chunk upload error (will retry): {e}")

        # Stale chunk detection: warn if ffmpeg stopped producing new segments
        try:
            current_count = sum(1 for _ in Path(session_dir).glob("chunk_*.mkv"))
            if current_count == last_chunk_count and current_count > 0:
                stale_checks += 1
                if stale_checks >= stale_threshold:
                    # Check if the single file is growing (ffmpeg stuck in one segment)
                    files = sorted(Path(session_dir).glob("chunk_*.mkv"))
                    if files:
                        size_mb = files[-1].stat().st_size / (1024 * 1024)
                        expected_mb = (VOD_SEGMENT_DURATION * 5)  # rough estimate per 5min at high bitrate
                        if size_mb > expected_mb:
                            logger.warning(
                                f"VOD segmenter appears stuck: {files[-1].name} is {size_mb:.0f}MB "
                                f"(expected ~{expected_mb}MB per segment), {stale_checks * 30}s without new chunk"
                            )
            else:
                stale_checks = 0
                last_chunk_count = current_count
        except OSError:
            pass

        # Wait up to 30 seconds or until stop signal
        try:
            await asyncio.wait_for(stop_event.wait(), timeout=30)
        except asyncio.TimeoutError:
            pass

    # Final pass — ffmpeg has exited, all chunks are complete
    try:
        await _do_vod_chunk_upload(recording, final=True)
    except Exception as e:
        logger.error(f"VOD final upload error: {e}")

    # If ffmpeg exited on its own (not via stop_vod_recording), clean up
    if not stop_event.is_set():
        stop_event.set()
        # Remove from active_recordings
        for sid, rec in list(active_recordings.items()):
            if rec is recording:
                active_recordings.pop(sid, None)
                break
        # Clean up local staging directory
        _vod_cleanup_session_dir(session_dir)
        logger.info(f"VOD recording auto-stopped for '{recording['stream_name']}' (ffmpeg exited)")


async def _do_vod_chunk_upload(recording: dict, final: bool = False, no_overwrite: bool = False) -> None:
    """Upload pending completed chunks to SFTP.

    With no_overwrite, a chunk whose remote name is taken is uploaded under a
    "_recovered" name instead (used for chunks left over from an earlier run).
    """
    session_dir = recording["session_dir"]
    remote_dir = recording["remote_session_dir"]
    user_id = recording["user_id"]
    uploaded: set = recording["uploaded"]

    # Discover chunk files
    try:
        chunk_files = sorted(
            p for p in Path(session_dir).glob("chunk_*.mkv")
        )
    except OSError:
        return

    if not chunk_files:
        return

    # While recording, the last file is still being written by ffmpeg
    pending = chunk_files if final else chunk_files[:-1]
    pending = [p for p in pending if str(p) not in uploaded and p.stat().st_size > 0]

    if not pending:
        return

    conn, sftp, error = await _connect_vod_sftp(user_id)
    if error:
        logger.error(f"VOD chunk upload SFTP connect failed: {error}")
        return

    try:
        # Ensure remote directory tree exists
        await _sftp_makedirs(sftp, remote_dir)

        for local_path in pending:
            remote_path = f"{remote_dir}/{local_path.name}"
            try:
                if no_overwrite:
                    remote_path = await _vod_free_remote_name(sftp, remote_dir, local_path.name)
                # Upload under a temporary name and rename on success, so an
                # interrupted put never leaves a truncated chunk under the
                # final name. 5-minute timeout per chunk upload (prevents
                # hanging on dead connections).
                part_path = remote_path + _VOD_PART_SUFFIX
                try:
                    await asyncio.wait_for(sftp.put(str(local_path), part_path), timeout=300)
                    await _vod_finish_remote_upload(sftp, part_path, remote_path)
                except BaseException:
                    await _vod_remove_partial(sftp, part_path)
                    raise
                uploaded.add(str(local_path))
                local_path.unlink()
                logger.info(f"VOD chunk uploaded: {remote_path}")
            except asyncio.TimeoutError:
                logger.error(f"VOD chunk upload timed out ({local_path.name}), will retry")
            except Exception as e:
                logger.error(f"VOD chunk upload failed ({local_path.name}): {e}")
    finally:
        conn.close()


_VOD_PART_SUFFIX = ".part"


async def _vod_finish_remote_upload(sftp, part_path: str, final_path: str) -> None:
    """Rename a fully uploaded temporary chunk to its final name (atomic when the server allows)."""
    posix_rename = getattr(sftp, "posix_rename", None)
    if posix_rename is not None:
        try:
            await posix_rename(part_path, final_path)
            return
        except asyncssh.SFTPOpUnsupported:
            pass  # the server lacks the OpenSSH extension; use the plain rename
    try:
        await sftp.rename(part_path, final_path)
    except asyncssh.SFTPError:
        # A plain rename does not replace an existing file. Only the live
        # uploader can get here with the name taken (a retried chunk).
        await sftp.remove(final_path)
        await sftp.rename(part_path, final_path)


async def _vod_remove_partial(sftp, part_path: str) -> None:
    """Best effort: delete a temporary remote chunk after a failed upload."""
    try:
        await asyncio.wait_for(sftp.remove(part_path), timeout=15)
    except Exception as e:  # the connection may be gone; the caller re-raises the real error
        logger.debug(f"VOD partial chunk {part_path} could not be removed: {e!r}")


async def _vod_free_remote_name(sftp, remote_dir: str, name: str) -> str:
    """Return remote_dir/name, or a "_recovered" variant when that name is already taken."""
    stem, dot, ext = name.rpartition(".")
    candidate = f"{remote_dir}/{name}"
    n = 0
    while True:
        try:
            await sftp.stat(candidate)
        except asyncssh.SFTPNoSuchFile:
            return candidate
        n += 1
        candidate = f"{remote_dir}/{stem}_recovered{n}{dot}{ext}"
        if n > 999:
            raise RuntimeError(f"no free remote name for {name}")


def _vod_prepare_staging() -> list:
    """Create the staging folder, move in an old /tmp one, and list leftover sessions.

    Runs once at start, before any recording can begin. A configured folder
    that is not safe to use (the filesystem root, a mount point, /tmp, a home
    directory, the project folder, a non-empty folder the portal did not
    create, ...) is refused with a log line and the default folder is used
    instead; the refused folder is not touched. Returns the session
    directories that hold chunks from an earlier run. When no folder is
    usable, _vod_staging_usable stays False, nothing is touched and the list
    is empty.
    """
    global VOD_TEMP_DIR, _vod_staging_usable
    _vod_staging_usable = False
    default = Config.VOD_TEMP_DIR_DEFAULT
    try:
        own = os.path.abspath(VOD_TEMP_DIR) == default  # the portal's own location: adopt it as it is
        vod_staging.ensure_private_dir(VOD_TEMP_DIR, (STATIC_DIR,), _PROJECT_ROOT,
                                       adopt_nonempty=own, allow_temp=own)
    except (OSError, ValueError) as e:
        if os.path.abspath(VOD_TEMP_DIR) == default:
            logger.error(
                f"VOD staging folder {VOD_TEMP_DIR} is not usable: {e}. It was left untouched; "
                f"VOD recording, recovery and cleanup are off until this is fixed"
            )
            return []
        logger.error(
            f"VOD_TEMP_DIR {VOD_TEMP_DIR} refused: {e}. It was left untouched; "
            f"using the default folder {default} instead"
        )
        try:
            # The default folder is the portal's own: adopt it even if a
            # previous run left files in it without a marker.
            vod_staging.ensure_private_dir(default, (STATIC_DIR,), _PROJECT_ROOT,
                                           adopt_nonempty=True, allow_temp=True)
        except (OSError, ValueError) as e2:
            logger.error(
                f"VOD staging folder {default} is not usable: {e2}. It was left untouched; "
                f"VOD recording, recovery and cleanup are off until this is fixed"
            )
            return []
        VOD_TEMP_DIR = default
        Config.VOD_TEMP_DIR = default  # update_manager reads it for snapshots and rollback
    _vod_staging_usable = True
    logger.info(f"VOD staging folder: {VOD_TEMP_DIR}")
    if not Config.STAGE_MODE:  # a staged instance must not touch the host's /tmp
        try:
            result = vod_staging.migrate_legacy(VOD_TEMP_DIR)
        except Exception as e:
            logger.error(f"VOD staging migration failed: {e}")
            result = {"moved": [], "skipped": []}
        if result["moved"]:
            logger.info(f"Moved {len(result['moved'])} VOD staging folder(s) from {vod_staging.LEGACY_DIR}")
        for name, why in result["skipped"]:
            logger.warning(f"VOD staging migration skipped {name}: {why}")
    return vod_staging.list_session_dirs(VOD_TEMP_DIR)


async def _vod_has_destination(user_id: int) -> Optional[str]:
    """None when the owner and the owner's VOD storage still exist, else the reason they do not.

    A database error is not an answer: it returns None so nothing is removed on a guess.
    """
    try:
        if not await db.get_user_by_id(user_id):
            return "the owner no longer exists"
        if not await db.get_vod_storage(user_id):
            return "the owner has no VOD storage configured"
    except Exception as e:
        logger.debug(f"VOD recovery could not look up user {user_id}: {e}")
    return None


def _vod_drop_stale(session_dir: str, reason: str) -> bool:
    """Remove an undeliverable session once it is 14 days old. Returns True when it was removed."""
    name = os.path.basename(session_dir)
    if not vod_staging.is_stale(session_dir):
        logger.warning(
            f"VOD staging dir {name} cannot be delivered ({reason}); "
            f"kept until it is {vod_staging.STALE_DAYS} days old"
        )
        return False
    count, size = vod_staging.remove_stale_session(session_dir)
    logger.warning(
        f"VOD staging: removed {name} after {vod_staging.STALE_DAYS} days, it could not be delivered "
        f"({reason}): {count} chunk(s), {size} bytes"
    )
    return True


async def recover_vod_staging(session_dirs: Optional[list] = None) -> None:
    """Upload chunks that an earlier run left in the staging folder.

    Called at start and again from the data cleanup loop, so an SFTP storage
    that was down at start gets another try. Only one pass runs at a time; a
    second call returns at once. Without *session_dirs* the folder is listed
    afresh. Folders that a recording is using are skipped.
    """
    global _vod_recovery_running
    if _vod_recovery_running:
        logger.debug("VOD recovery already running; skipped")
        return
    if not _vod_staging_usable:
        logger.warning("VOD recovery skipped: there is no usable VOD staging folder")
        return
    _vod_recovery_running = True
    try:
        if session_dirs is None:
            session_dirs = await asyncio.to_thread(vod_staging.list_session_dirs, VOD_TEMP_DIR)
        for session_dir in session_dirs:
            if session_dir in _vod_busy_dirs or any(
                rec.get("session_dir") == session_dir for rec in list(active_recordings.values())
            ):
                continue
            await _vod_recover_one(session_dir)
    finally:
        _vod_recovery_running = False


async def _vod_recover_one(session_dir: str) -> None:
    chunks = vod_staging.chunk_files(session_dir)
    for c in list(chunks):  # an empty chunk is never uploaded and would keep the folder alive
        try:
            if os.path.getsize(c) == 0:
                os.unlink(c)
                chunks.remove(c)
        except OSError:
            pass
    if not chunks:
        vod_staging.remove_if_empty(session_dir)
        return
    meta = vod_staging.read_sidecar(session_dir)
    if not meta:
        _vod_drop_stale(
            session_dir,
            "it has no usable session record; upload the chunks by hand if you need them",
        )
        return
    gone = await _vod_has_destination(meta["user_id"])
    if gone:
        _vod_drop_stale(session_dir, gone)
        return
    logger.info(f"VOD recovery: {len(chunks)} chunk(s) from {os.path.basename(session_dir)}")
    recording = {
        "session_dir": session_dir,
        "remote_session_dir": meta["remote_session_dir"],
        "user_id": meta["user_id"],
        "stream_name": meta.get("stream_name", ""),
        "uploaded": set(),
    }
    try:
        await _do_vod_chunk_upload(recording, final=True, no_overwrite=True)
    except Exception as e:
        logger.error(f"VOD recovery upload error for {session_dir}: {e}")
    _vod_cleanup_session_dir(session_dir)


async def _sftp_makedirs(sftp, path: str) -> None:
    """Recursively create remote directories (like os.makedirs)."""
    parts = path.strip("/").split("/")
    current = ""
    for part in parts:
        current += f"/{part}"
        try:
            await sftp.stat(current)
        except asyncssh.SFTPNoSuchFile:
            try:
                await sftp.mkdir(current)
            except asyncssh.SFTPError:
                pass  # May already exist from race condition


async def stop_vod_recording(stream_id: int, force: bool = False) -> None:
    """Stop recording, finalize last chunk, upload remaining, clean up.

    When force=False (stream disconnect), wait for ffmpeg to exit naturally
    as the RTSPS source disappearing causes ffmpeg to finish the current
    chunk and exit cleanly. Only use force=True on server shutdown.
    """
    async with _stream_state_lock:
        recording = active_recordings.pop(stream_id, None)
    if not recording:
        return

    process = recording["process"]

    if force:
        # Server shutdown — SIGINT immediately to finalize MKV headers
        try:
            process.send_signal(signal.SIGINT)
            await asyncio.wait_for(process.wait(), timeout=15)
        except asyncio.TimeoutError:
            logger.warning("ffmpeg did not exit cleanly, terminating")
            process.terminate()
            try:
                await asyncio.wait_for(process.wait(), timeout=5)
            except asyncio.TimeoutError:
                process.kill()
                await process.wait()
        except ProcessLookupError:
            pass
    else:
        # Normal disconnect — let ffmpeg finish the current chunk naturally.
        # When the RTSPS source ends, ffmpeg finalizes the segment and exits.
        try:
            await asyncio.wait_for(process.wait(), timeout=300)
            logger.info(f"VOD ffmpeg exited naturally (code {process.returncode})")
        except asyncio.TimeoutError:
            logger.warning("ffmpeg did not exit after source ended, sending SIGINT")
            try:
                process.send_signal(signal.SIGINT)
                await asyncio.wait_for(process.wait(), timeout=15)
            except asyncio.TimeoutError:
                process.terminate()
                try:
                    await asyncio.wait_for(process.wait(), timeout=5)
                except asyncio.TimeoutError:
                    process.kill()
                    await process.wait()
            except ProcessLookupError:
                pass

    # Signal uploader to do final pass then exit
    recording["stop_event"].set()

    # Wait for uploader to finish final upload
    upload_task = recording.get("upload_task")
    if upload_task:
        try:
            await asyncio.wait_for(upload_task, timeout=120)
        except asyncio.TimeoutError:
            logger.warning("VOD final upload timed out")
            upload_task.cancel()
        except (asyncio.CancelledError, Exception) as e:
            if not isinstance(e, asyncio.CancelledError):
                logger.warning(f"VOD uploader task ended with error: {e}")
            # Uploader crashed — do a final upload pass directly
            try:
                await _do_vod_chunk_upload(recording, final=True)
            except Exception as upload_err:
                logger.error(f"VOD recovery upload failed: {upload_err}")

    # Clean up local staging directory
    session_dir = recording["session_dir"]
    _vod_cleanup_session_dir(session_dir)

    logger.info(f"VOD recording stopped for '{recording['stream_name']}'")


async def stop_all_recordings() -> None:
    """Stop all active VOD recordings (called on server shutdown)."""
    async with _stream_state_lock:
        # Cancel any pending disconnect grace tasks
        for stream_id, task in list(_disconnect_grace_tasks.items()):
            if not task.done():
                task.cancel()
        _disconnect_grace_tasks.clear()

        if not active_recordings:
            return
        logger.info(f"Stopping {len(active_recordings)} active VOD recording(s)...")
        stream_ids = list(active_recordings.keys())
    for stream_id in stream_ids:
        await stop_vod_recording(stream_id, force=True)


async def _handle_disconnect_grace(stream: dict) -> None:
    """Grace period before triggering encoding/offline on stream disconnect.

    Waits 7 seconds, then re-checks if the stream reconnected. If still disconnected,
    proceeds with encoding (if VOD active) or offline transition. This prevents
    accidental brief disconnects from triggering the full finalization flow.
    """
    stream_id = stream["id"]
    stream_name = stream.get("name", "?")
    try:
        await asyncio.sleep(7)

        # Did it reconnect during the grace period? A reconnect's publish auth
        # pops this task from _disconnect_grace_tasks (and cancels it), so if we
        # are no longer the registered task we were superseded. Don't re-check
        # is_live here: it is still 1 until this task clears it, so that check
        # always aborted and left streams stuck "live" after every disconnect.
        async with _stream_state_lock:
            superseded = _disconnect_grace_tasks.get(stream_id) is not asyncio.current_task()
        if superseded:
            logger.info(f"Stream {stream_name} reconnected during grace period, aborting disconnect")
            return

        # Stop multi-platform relays
        await stop_stream_relays(stream_id)

        # Still disconnected — proceed with encoding/offline transition
        async with _stream_state_lock:
            has_vod = stream_id in active_recordings

        if has_vod:
            # Transition to encoding state — VOD chunks still being finalized
            await db.set_stream_encoding(stream_id)
            logger.info(f"Stream {stream_name} ended (after grace period), encoding VODs...")

            # Broadcast encoding status to chat channel
            if stream.get("chat_channel_id"):
                channel = await db.get_chat_channel(stream["chat_channel_id"])
                if channel:
                    await broadcast_to_channel(channel["name"], {
                        "type": "stream_status",
                        "stream_id": stream_id,
                        "is_live": 2  # encoding
                    })

            # Finalize VOD in background, then transition to offline
            asyncio.create_task(_finalize_stream_offline(stream))
        else:
            # No VOD recording — go straight to offline
            await db.set_stream_live(stream_id, False)
            logger.info(f"Stream {stream_name} ended (after grace period)")
            await db.log_activity(stream.get("user_id"), get_display_name(stream), _stream_activity_type("stream_offline", stream), f"Stream '{stream_name}' went offline")
            asyncio.create_task(fire_webhook_event("stream.offline", {
                "stream_id": stream_id, "stream_name": stream_name,
                "owner_username": stream.get("owner_username")
            }, meta={"stream_public": bool(stream.get("is_public"))}))

            if stream.get("chat_channel_id"):
                channel = await db.get_chat_channel(stream["chat_channel_id"])
                if channel:
                    await broadcast_to_channel(channel["name"], {
                        "type": "stream_status",
                        "stream_id": stream_id,
                        "is_live": 0
                    })

            # Clear chat history for the stream's channel
            if stream.get("chat_channel_id") and not await _stream_chat_shared(stream["chat_channel_id"]):
                clear_stats = {}
                deleted = await db.clear_channel_messages(stream["chat_channel_id"], stats=clear_stats)
                if deleted > 0:
                    logger.info(f"Cleared {deleted} chat messages and {clear_stats.get('files', 0)} upload file(s) for stream {stream_name}")
    except asyncio.CancelledError:
        logger.info(f"Stream {stream_name} disconnect grace period cancelled (reconnected)")
    except Exception as e:
        logger.error(f"Error in disconnect grace for stream {stream_name}: {e}")
    finally:
        # Only deregister ourselves — a newer grace task may own this slot now.
        if _disconnect_grace_tasks.get(stream_id) is asyncio.current_task():
            _disconnect_grace_tasks.pop(stream_id, None)


def _stream_activity_type(action: str, stream: dict) -> str:
    """The activity type to log a stream event under. stream_live and stream_offline are shown
    to every member; a stream that is not public is logged under a type that is not."""
    return action if stream.get("is_public") else action + "_private"


async def _finalize_stream_offline(stream: dict) -> None:
    """Background task: wait for VOD finalization, then transition stream to offline."""
    stream_id = stream["id"]
    stream_name = stream.get("name", "?")
    try:
        # Wait for ffmpeg to finish the current chunk and upload all chunks
        await stop_vod_recording(stream_id)

        # Now transition to fully offline
        await db.set_stream_live(stream_id, False)
        logger.info(f"Stream {stream_name} VOD finalized, now offline")
        await db.log_activity(stream.get("user_id"), get_display_name(stream), _stream_activity_type("stream_offline", stream), f"Stream '{stream_name}' went offline")
        asyncio.create_task(fire_webhook_event("stream.offline", {
            "stream_id": stream_id, "stream_name": stream_name,
            "owner_username": stream.get("owner_username")
        }, meta={"stream_public": bool(stream.get("is_public"))}))

        # Broadcast offline status to chat channel
        if stream.get("chat_channel_id"):
            channel = await db.get_chat_channel(stream["chat_channel_id"])
            if channel:
                await broadcast_to_channel(channel["name"], {
                    "type": "stream_status",
                    "stream_id": stream_id,
                    "is_live": 0
                })

        # Clear chat history for the stream's channel
        if stream.get("chat_channel_id") and not await _stream_chat_shared(stream["chat_channel_id"]):
            clear_stats = {}
            deleted = await db.clear_channel_messages(stream["chat_channel_id"], stats=clear_stats)
            if deleted > 0:
                logger.info(f"Cleared {deleted} chat messages and {clear_stats.get('files', 0)} upload file(s) for stream {stream_name}")
    except Exception as e:
        logger.error(f"Error finalizing stream {stream_name} offline: {e}")
        # Ensure stream goes offline even if VOD finalization fails
        try:
            await db.set_stream_live(stream_id, False)
        except (OSError, ValueError):
            pass


# =========================================================================
# Multi-Platform Stream Relay
# =========================================================================

async def start_stream_relays(stream: dict, stream_key: str) -> None:
    """Start relay processes for all enabled relay destinations.

    Waits briefly for MediaMTX to register the stream path (auth response
    is sent before the path is fully set up), then spawns ffmpeg per dest
    with retry on transient RTSPS failures.
    """
    stream_id = stream["id"]
    destinations = await db.get_enabled_relay_destinations(stream_id)
    if not destinations:
        return

    mtx_config = await _get_mediamtx_config()
    if not mtx_config:
        logger.warning("MediaMTX not configured, cannot start relays")
        return

    # Stop any existing relay processes first (rapid reconnect race condition).
    # Without this, a quick disconnect/reconnect spawns duplicate ffmpeg processes.
    async with _stream_state_lock:
        existing = active_relays.get(stream_id, {})
    if existing:
        logger.info(f"Stopping {len(existing)} existing relay(s) for stream {stream_id} before restart")
        await stop_stream_relays(stream_id, force=True)

    # Use plain RTSP on localhost for relay source — no TLS overhead
    # for local IPC, and avoids cert hostname mismatch (LE cert is for
    # stream.dddvm.xyz, not 127.0.0.1). RTSP port is localhost-only.
    rtsp_port = 8554
    source_url = f"rtsp://127.0.0.1:{rtsp_port}/live/{stream_key}"

    # Wait for MediaMTX to finish registering the stream path.
    # The auth webhook returns before the path is ready internally.
    await asyncio.sleep(3)

    # Verify stream is still live (may have disconnected during the delay)
    current = await db.get_user_stream(stream_id)
    if not current or current.get("is_live") != 1:
        return

    async with _stream_state_lock:
        if stream_id not in active_relays:
            active_relays[stream_id] = {}

    for dest in destinations:
        relay_id = dest["id"]
        rtmp_url = dest["rtmp_url"].rstrip("/")
        relay_key = dest["stream_key"]
        platform = dest.get("platform", "custom")

        # Retry loop — RTSPS path may take a moment to become available
        max_attempts = 3
        for attempt in range(1, max_attempts + 1):
            try:
                # Outbound host policy, re-applied at every start: the stored
                # name may resolve differently than when it was saved.
                try:
                    out_opts, target = await _checked_relay_target(rtmp_url, relay_key)
                except (HostCheckError, ValueError) as e:
                    logger.warning(f"Relay {platform}/{dest['name']} not started: destination host refused by outbound host policy")
                    asyncio.create_task(db.update_relay_last_error(
                        relay_id, "Host not allowed" if isinstance(e, HostBlockedError) else "Host could not be resolved"))
                    break
                cmd = [
                    "ffmpeg", "-hide_banner", "-loglevel", "warning",
                    "-rtsp_transport", "tcp",
                    "-i", source_url,
                    "-c", "copy", "-f", "flv",
                    *out_opts,
                    target
                ]
                process = await _media_exec(
                    cmd, "idle",
                    stdout=asyncio.subprocess.DEVNULL,
                    stderr=asyncio.subprocess.PIPE
                )
                monitor_task = asyncio.create_task(
                    _monitor_relay_process(stream_id, relay_id, process, dest)
                )
                async with _stream_state_lock:
                    active_relays[stream_id][relay_id] = {
                        "process": process,
                        "dest": dest,
                        "started_at": datetime.now(timezone.utc),
                        "monitor_task": monitor_task,
                    }
                logger.info(f"Relay started: stream {stream_id} -> {platform} ({dest['name']}), pid={process.pid}")

                # Wait briefly and check if ffmpeg exited immediately (e.g. 404)
                await asyncio.sleep(2)
                if process.returncode is not None and process.returncode != 0:
                    stderr_tail = b""
                    try:
                        stderr_tail = await asyncio.wait_for(process.stderr.read(2048), timeout=1)
                    except (asyncio.TimeoutError, Exception):
                        pass
                    err_msg = _sanitize_relay_stderr(stderr_tail.decode(errors="replace").strip()[-500:])
                    if attempt < max_attempts:
                        logger.warning(f"Relay {platform}/{dest['name']} failed on attempt {attempt}/{max_attempts}: {err_msg}")
                        # Clean up before retry
                        async with _stream_state_lock:
                            active_relays.get(stream_id, {}).pop(relay_id, None)
                        monitor_task.cancel()
                        await asyncio.sleep(3)
                        continue
                    else:
                        logger.warning(f"Relay {platform}/{dest['name']} failed after {max_attempts} attempts: {err_msg}")
                        asyncio.create_task(db.update_relay_last_error(relay_id, err_msg or "Process exited immediately"))
                        async with _stream_state_lock:
                            active_relays.get(stream_id, {}).pop(relay_id, None)
                break  # Process is running or final attempt done

            except Exception as e:
                logger.error(f"Failed to start relay for stream {stream_id} -> {platform}: {e}")
                break


def _sanitize_relay_stderr(stderr_text: str) -> str:
    """Redact the stream key from rtmp:// and rtmps:// URLs in ffmpeg relay stderr.

    ffmpeg stderr may contain the full target URL (e.g. rtmp://host/app/<key>),
    and the key belongs to the destination platform. This keeps the URL up to
    its last '/' and replaces the final segment, so the key never reaches the
    database or the log. It is applied before the text is stored or logged;
    the log filter (logger.SENSITIVE_PATTERNS) is a second line of defence for
    the formats it recognises and does not replace this step.
    """
    return re.sub(r'(rtmps?://[^\s/]+(?:/[^\s/]+)*/)([^\s"\']+)', r'\1[KEY_REDACTED]', stderr_text)


async def _restart_single_relay(stream_id: int, relay_id: int, dest: dict) -> None:
    """Auto-restart one relay after an abnormal exit, with exponential backoff."""
    platform = dest.get("platform", "custom")
    name = dest.get("name", "?")
    backoffs = [10, 30, 60]

    for attempt, delay in enumerate(backoffs, start=1):
        await asyncio.sleep(delay)

        # Abort if stream is no longer live
        current = await db.get_user_stream(stream_id)
        if not current or current.get("is_live") != 1:
            logger.info(f"Relay auto-restart aborted ({platform}/{name}): stream offline")
            return

        # Abort if already restarted by health monitor or another path
        async with _stream_state_lock:
            if relay_id in active_relays.get(stream_id, {}):
                logger.info(f"Relay auto-restart skipped ({platform}/{name}): already running")
                return

        # Verify destination is still enabled and get fresh decrypted keys
        dests = await db.get_enabled_relay_destinations(stream_id)
        fresh_dest = next((d for d in dests if d["id"] == relay_id), None)
        if not fresh_dest:
            logger.info(f"Relay auto-restart aborted ({platform}/{name}): destination disabled or removed")
            return

        mtx_config = await _get_mediamtx_config()
        if not mtx_config:
            return

        async with _stream_state_lock:
            active_key = _rtmp_stream_paths.get(stream_id, current["stream_key"])
        source_url = f"rtsp://127.0.0.1:8554/live/{active_key}"

        rtmp_url = fresh_dest["rtmp_url"].rstrip("/")

        try:
            # Outbound host policy, re-applied at every (re)start.
            try:
                out_opts, target = await _checked_relay_target(rtmp_url, fresh_dest["stream_key"])
            except (HostCheckError, ValueError) as e:
                logger.warning(f"Relay auto-restart refused ({platform}/{name}): destination host refused by outbound host policy")
                asyncio.create_task(db.update_relay_last_error(
                    relay_id, "Host not allowed" if isinstance(e, HostBlockedError) else "Host could not be resolved"))
                if isinstance(e, HostBlockedError):
                    return
                continue
            cmd = [
                "ffmpeg", "-hide_banner", "-loglevel", "warning",
                "-rtsp_transport", "tcp",
                "-i", source_url,
                "-c", "copy", "-f", "flv",
                *out_opts,
                target
            ]
            process = await _media_exec(
                cmd, "idle",
                stdout=asyncio.subprocess.DEVNULL,
                stderr=asyncio.subprocess.PIPE
            )
            monitor_task = asyncio.create_task(
                _monitor_relay_process(stream_id, relay_id, process, fresh_dest)
            )
            async with _stream_state_lock:
                if stream_id not in active_relays:
                    active_relays[stream_id] = {}
                active_relays[stream_id][relay_id] = {
                    "process": process,
                    "dest": fresh_dest,
                    "started_at": datetime.now(timezone.utc),
                    "monitor_task": monitor_task,
                }
            logger.info(f"Relay auto-restarted (attempt {attempt}/{len(backoffs)}): "
                        f"stream {stream_id} -> {platform} ({name}), pid={process.pid}")

            # Brief check for immediate failure
            await asyncio.sleep(2)
            if process.returncode is not None and process.returncode != 0:
                async with _stream_state_lock:
                    active_relays.get(stream_id, {}).pop(relay_id, None)
                monitor_task.cancel()
                if attempt < len(backoffs):
                    logger.warning(f"Relay auto-restart failed immediately ({platform}/{name}), "
                                   f"attempt {attempt}/{len(backoffs)}")
                    continue
                logger.warning(f"Relay auto-restart exhausted all attempts ({platform}/{name})")
                asyncio.create_task(db.update_relay_last_error(
                    relay_id, "Auto-restart exhausted after repeated failures"))
            return

        except Exception as e:
            logger.error(f"Relay auto-restart error ({platform}/{name}) attempt {attempt}: {e}")
            if attempt >= len(backoffs):
                return


async def _monitor_relay_process(stream_id: int, relay_id: int,
                                  process: asyncio.subprocess.Process, dest: dict) -> None:
    """Monitor a single relay process and clean up on exit."""
    platform = dest.get("platform", "custom")
    name = dest.get("name", "?")
    try:
        stderr_data = b""
        while True:
            try:
                chunk = await asyncio.wait_for(process.stderr.read(4096), timeout=30)
                if not chunk:
                    break
                stderr_data = (stderr_data + chunk)[-2048:]
            except asyncio.TimeoutError:
                if process.returncode is not None:
                    break
                continue
        await process.wait()
        rc = process.returncode
        if rc != 0:
            stderr_tail = _sanitize_relay_stderr(stderr_data.decode(errors="replace")[-500:])
            logger.warning(f"Relay {platform}/{name} exited with code {rc}: {stderr_tail}")
            asyncio.create_task(db.update_relay_last_error(relay_id, f"Exit code {rc}: {stderr_tail}" if stderr_tail else f"Exit code {rc}"))
            # Only auto-restart if the relay ran for >= 30s — quick-exits are likely
            # in a failure loop (bad credentials, ingest down) and should not cascade.
            async with _stream_state_lock:
                info = active_relays.get(stream_id, {}).get(relay_id, {})
            ran = (datetime.now(timezone.utc) - info["started_at"]).total_seconds() if info else 0
            if ran >= 30:
                asyncio.create_task(_restart_single_relay(stream_id, relay_id, dest))
        else:
            logger.info(f"Relay {platform}/{name} ended normally")
    except asyncio.CancelledError:
        pass
    except Exception as e:
        logger.error(f"Relay monitor error for {platform}/{name}: {e}")
    finally:
        async with _stream_state_lock:
            relays = active_relays.get(stream_id, {})
            relays.pop(relay_id, None)
            if not relays:
                active_relays.pop(stream_id, None)


async def stop_stream_relays(stream_id: int, force: bool = False) -> None:
    """Stop all relay processes for a stream."""
    async with _stream_state_lock:
        relays = active_relays.get(stream_id, {})
        if not relays:
            return
        relay_items = list(relays.items())

    for relay_id, info in relay_items:
        await _stop_relay_process(stream_id, relay_id, info, force)


async def stop_single_relay(stream_id: int, relay_id: int) -> None:
    """Stop a single relay process (e.g., when a destination is deleted while live)."""
    async with _stream_state_lock:
        info = active_relays.get(stream_id, {}).get(relay_id)
        if not info:
            return
    await _stop_relay_process(stream_id, relay_id, info, force=True)


async def _stop_relay_process(stream_id: int, relay_id: int, info: dict,
                               force: bool = False) -> None:
    """Stop a relay ffmpeg process."""
    process = info["process"]
    platform = info["dest"].get("platform", "custom")
    if process.returncode is not None:
        return
    try:
        if force:
            process.terminate()
            try:
                await asyncio.wait_for(process.wait(), timeout=5)
            except asyncio.TimeoutError:
                process.kill()
                await process.wait()
        else:
            # Let ffmpeg exit naturally when source disappears
            try:
                await asyncio.wait_for(process.wait(), timeout=30)
            except asyncio.TimeoutError:
                process.terminate()
                try:
                    await asyncio.wait_for(process.wait(), timeout=5)
                except asyncio.TimeoutError:
                    process.kill()
                    await process.wait()
        logger.info(f"Relay stopped: stream {stream_id} -> {platform}")
    except ProcessLookupError:
        pass
    finally:
        monitor = info.get("monitor_task")
        if monitor and not monitor.done():
            monitor.cancel()
        async with _stream_state_lock:
            relays = active_relays.get(stream_id, {})
            relays.pop(relay_id, None)
            if not relays:
                active_relays.pop(stream_id, None)


# =========================================================================
# Webhook Delivery Engine
# =========================================================================

_webhook_rate_limits: dict[int, list[float]] = {}
_webhook_incoming_rate_limits: dict[str, list[float]] = {}
_WEBHOOK_RATE_LIMIT = 30        # max deliveries per webhook per window
_WEBHOOK_RATE_WINDOW = 60.0     # seconds
_WEBHOOK_MAX_FAILURES = 10      # auto-disable threshold
_WEBHOOK_RETRY_DELAYS = [10, 60, 300]  # backoff: 10s, 60s, 5min
_WEBHOOK_INCOMING_RATE = 10     # max incoming messages per token per window
_WEBHOOK_INCOMING_WINDOW = 60.0


def _stream_event_hook_allowed(webhook: dict, event: str, meta: dict | None) -> bool:
    """A stream event about a stream that is not public goes to system hooks only
    (set up by an administrator), never to a member's own hook: that hook belongs
    to somebody who may not be allowed to know the stream exists. Other events and
    public streams are not affected here."""
    if event in webhook_formats.STREAM_EVENTS and not (meta or {}).get("stream_public"):
        return (webhook.get("kind") or "user") == "system"
    return True


async def _third_party_may_see(event: str, meta: dict | None) -> bool:
    """Whether an event may go to a non-generic (third-party) channel at all.

    Chat events only for a channel an ordinary member can read: _can_read_channel
    with an unrelated member id and the plain user role, so private channels and
    the chat of a stream that is not public never qualify. Stream events only for
    a public stream. Fails closed when the event carries no such information.
    """
    meta = meta or {}
    if event in webhook_formats.CHAT_EVENTS:
        channel_id = meta.get("channel_id")
        if not isinstance(channel_id, int):
            return False
        try:
            channel = await db.get_chat_channel(channel_id)
            return bool(await _can_read_channel(channel, 0, "user"))
        except Exception as e:
            logger.warning(f"Webhook channel visibility check failed: {type(e).__name__}")
            return False
    if event in webhook_formats.STREAM_EVENTS:
        return bool(meta.get("stream_public"))
    if event in webhook_formats.PRESENCE_EVENTS:
        return await _presence_announceable(meta)
    return True


async def _presence_announceable(meta: dict | None) -> bool:
    """Whether a user.connected / user.disconnected event may be sent to any hook: a member
    who chose to appear offline is not announced. Fails closed."""
    uid = (meta or {}).get("user_id")
    if not isinstance(uid, int):
        return False
    try:
        st = await db.get_user_status(uid)
    except Exception as e:
        logger.warning(f"Webhook presence check failed: {type(e).__name__}")
        return False
    return bool(st) and st.get("status_preference") != "offline"


def _message_webhook_payload(message_id: int, channel: str, user_id: int, display_name: str,
                             text: str, created_at: str, *, anonymous: bool) -> dict:
    """Body of message.created for every format: an anonymous post carries no user id (the
    name is already "Anonymous"), as chat masks it for members."""
    return {"message_id": message_id, "channel": channel,
            "user_id": None if anonymous else user_id, "username": display_name,
            "message": text, "created_at": created_at}


def _message_deleted_webhook_payload(message_id: int, channel: str, deleted_by: int, message: dict) -> dict:
    """Body of message.deleted: when the author deleted their own anonymous post, deleted_by
    would name the author, so it is empty."""
    own_anonymous = bool(message.get("anonymous")) and deleted_by == message.get("user_id")
    return {"message_id": message_id, "channel": channel,
            "deleted_by": None if own_anonymous else deleted_by}


async def fire_webhook_event(event: str, payload: dict, *, meta: dict | None = None) -> int:
    """Dispatch event to all subscribed outgoing webhooks (non-blocking). Returns how many
    deliveries were started.

    `meta` is private to the portal: it is never part of the generic body. It
    carries what the non-generic formats need (channel id, anonymous flag,
    whether a stream is public).
    """
    try:
        if event in webhook_formats.PRESENCE_EVENTS and not await _presence_announceable(meta):
            return 0        # appear-offline: no hook of any format is told
        webhooks = await db.get_enabled_outgoing_webhooks_for_event(event)
        visible = None
        if any(w.get("format") != "generic" for w in webhooks):
            visible = await _third_party_may_see(event, meta)
    except Exception as e:
        logger.warning(f"Webhook event dispatch failed for {event}: {e}")
        return 0
    started = 0
    drops: dict = {}        # shared by this event's deliveries: a drop is counted once, not once per hook
    for webhook in webhooks:
        if webhook.get("format") != "generic" and not visible:
            continue
        if not _stream_event_hook_allowed(webhook, event, meta):
            continue
        asyncio.create_task(_deliver_webhook(webhook, event, payload, meta=meta, drops=drops))
        started += 1
    return started


_webhook_paused_until: dict[int, float] = {}
# A delivery refused by policy before anything is sent (a non-generic hook over plain http with
# allow_private off) records its reason on the hook and counts as one failure per hour at most,
# however many events it refuses, so the admin list says why the hook is silent and a silent hook
# is switched off only after many hours, not after ten events.
_webhook_policy_noted: dict[int, float] = {}
_WEBHOOK_POLICY_NOTE_INTERVAL = 3600.0
_WEBHOOK_MAX_429_WAITS = 3
_WEBHOOK_ANSWER_MAX = 4096        # bytes of a receiver's answer that are read at all
_webhook_sleep = asyncio.sleep      # module level so tests can replace it


def _webhook_error_text(e: BaseException) -> str:
    """A failure described without the URL, which aiohttp puts in some messages
    and which is a credential for the non-generic formats."""
    seen = e
    for _ in range(4):
        if isinstance(seen, HostCheckError):
            return "destination refused by the host policy"
        nxt = seen.__cause__ or seen.__context__
        if nxt is None:
            break
        seen = nxt
    if isinstance(e, asyncio.TimeoutError):
        return "timeout"
    return type(e).__name__


def _webhook_note_dropped(event: str, drops: dict | None, retry_in: float) -> None:
    """An alert was dropped for one hook (paused by a 429, or over its rate limit): tell the
    alert module once per event, however many hooks drop it. The "held back" notice is passed on
    for every hook that refuses it; the alert module puts its counts back once."""
    if event != "alerts.suppressed" and drops is not None:
        if drops.get("noted"):
            return
        drops["noted"] = True
    alerts.note_dropped(event, retry_in)


async def _stage_sink_allows(url: str, allow_private: bool) -> bool:
    """A staged instance (PORTAL_STAGE_MODE) sends nothing, except to a local
    receiver a test has set up: a hook with allow_private whose URL is the
    literal 127.0.0.1 and the port in the stage_webhook_sink_port setting."""
    if not allow_private:
        return False
    try:
        port = int(await db.get_setting("stage_webhook_sink_port") or 0)
        parts = urlsplit(url)
        return bool(port) and parts.hostname == "127.0.0.1" and parts.port == port
    except Exception:
        return False


async def _webhook_current_for_event(webhook_id: int, event: str, meta: dict | None) -> dict | None:
    """The stored hook, when it may still receive this event: it exists, is enabled and
    outgoing, subscribed (subscription and event classes) and, for a non-generic
    format, the event is visible to a third party. Otherwise None."""
    w = await db.get_webhook_for_delivery(webhook_id)
    if (w and w.get("enabled") and w["type"] == "outgoing"
            and webhook_formats.event_subscribed(
                w["events"], event, kind=w["kind"], fmt=w["format"])
            and (w["format"] == "generic" or await _third_party_may_see(event, meta))
            and _stream_event_hook_allowed(w, event, meta)):
        return w
    return None


async def _webhook_resend_allowed(sent_to: dict, event: str, meta: dict | None) -> bool:
    """Whether a request already built for `sent_to` may be sent again after a wait:
    the same rules as a fresh delivery, and the destination, format, privilege and
    credentials must be the ones the request was built for."""
    try:
        w = await _webhook_current_for_event(sent_to["id"], event, meta)
    except Exception as e:
        logger.warning(f"Webhook {sent_to.get('id')} re-check failed: {type(e).__name__}")
        return False
    if not w:
        return False
    return all(w.get(k) == sent_to.get(k)
               for k in ("url", "format", "allow_private", "include_details", "secret", "format_config"))


_WEBHOOK_HTTP_REFUSED = "needs an https:// URL unless allow_private is on"     # fixed text, no URL


async def _webhook_note_policy_refusal(webhook_id: int, reason: str) -> None:
    """Set the hook's last failure reason (the admin list shows it) for a delivery refused by
    policy before sending; counts toward auto-disable at most once per hour."""
    now = monotonic()
    last = _webhook_policy_noted.get(webhook_id)
    if last is not None and now - last < _WEBHOOK_POLICY_NOTE_INTERVAL:
        return
    _webhook_policy_noted[webhook_id] = now
    try:
        new_count = await db.increment_webhook_failures(webhook_id, reason)
        if new_count >= _WEBHOOK_MAX_FAILURES:
            await db.disable_webhook(webhook_id)
            logger.warning(f"Webhook {webhook_id} auto-disabled after {new_count} consecutive failures")
    except Exception as e:
        logger.warning(f"Failed to record a webhook policy refusal: {type(e).__name__}")


async def _deliver_webhook(webhook: dict, event: str, payload: dict,
                            attempt: int = 1, *, meta: dict | None = None,
                            single: bool = False, waits_used: int = 0,
                            drops: dict | None = None) -> dict:
    """Deliver payload to a single webhook endpoint with retry.

    Returns {"sent", "status", "success", "error"} for the last request made
    (the Test route reports it). `single` makes one attempt with no retry
    schedule and no Retry-After wait. `waits_used` carries the Retry-After waits
    already spent by earlier attempts of the same delivery, so the cap of
    _WEBHOOK_MAX_429_WAITS covers the whole delivery, backoff retries included. `drops` is
    shared by all deliveries of one event, so an alert dropped for several hooks is counted
    into the "held back" notice once.
    """
    result = {"sent": False, "status": None, "success": False, "error": None}
    webhook_id = webhook["id"]
    fmt = webhook.get("format") or "generic"
    url = webhook.get("url")
    secret = webhook.get("secret")
    allow_private = bool(webhook.get("allow_private"))
    if fmt not in webhook_formats.FORMATS:
        result["error"] = "unknown format"
        return result
    if not url or (fmt == "generic" and not secret):
        result["error"] = "not configured"
        return result
    # A non-generic hook carries a credential or a private topic: over plain http it is
    # only ever sent to a private address (allow_private). Saving refuses the combination,
    # but allow_private can be switched off afterwards without a re-check, so delivery
    # holds the rule too.
    if fmt != "generic" and not allow_private and not url.lower().startswith("https://"):
        result["error"] = _WEBHOOK_HTTP_REFUSED
        if not single:
            await _webhook_note_policy_refusal(webhook_id, _WEBHOOK_HTTP_REFUSED)
        return result
    if Config.STAGE_MODE and not await _stage_sink_allows(url, allow_private):
        result["error"] = "staged instance: nothing is sent outside the host"
        return result      # staged test mode: never send anything outside the host

    # A receiver that answered 429 is left alone until its Retry-After is over
    if not single and monotonic() < _webhook_paused_until.get(webhook_id, 0.0):
        result["error"] = "receiver asked to slow down"
        _webhook_note_dropped(event, drops, _webhook_paused_until.get(webhook_id, 0.0) - monotonic())
        return result

    # Per-webhook rate limit
    now = monotonic()
    window_start = now - _WEBHOOK_RATE_WINDOW
    times = _webhook_rate_limits.setdefault(webhook_id, [])
    _webhook_rate_limits[webhook_id] = [t for t in times if t > window_start]
    if len(_webhook_rate_limits[webhook_id]) >= _WEBHOOK_RATE_LIMIT:
        logger.warning(f"Webhook {webhook_id} rate limited, dropping delivery for {event}")
        result["error"] = "rate limited"
        if not single:
            _webhook_note_dropped(event, drops, _webhook_rate_limits[webhook_id][0] + _WEBHOOK_RATE_WINDOW - now)
        return result
    _webhook_rate_limits[webhook_id].append(now)

    # One formatter layer: generic keeps the signed body, the others are minimal.
    # A redirect is followed only by a generic hook without allow_private: a public
    # receiver must not bounce a signed POST on to an address on the LAN
    try:
        req = webhook_formats.format_payload(
            fmt, event, payload, meta=meta,
            include_details=bool(webhook.get("include_details")),
            portal_name=Config.TOTP_ISSUER, secret=secret,
            secret_config=webhook.get("format_config"))
    except Exception as e:
        logger.warning(f"Webhook {webhook_id} payload could not be built: {type(e).__name__}")
        result["error"] = "payload could not be built"
        return result
    target = url
    if req.path_suffix:
        parts = urlsplit(url)
        path = parts.path.rstrip("/")
        if not path.endswith(req.path_suffix):
            path += req.path_suffix
        target = urlunsplit((parts.scheme, parts.netloc, path, parts.query, ""))

    start_time = monotonic()
    response_status = None
    response_body = None
    success = False
    rate_limited = False
    waits = waits_used

    while True:
        response_status = None
        response_body = None
        success = False
        retry_after = None
        try:
            own = await _own_endpoints_async() if allow_private else None
            connector = _SSRFSafeConnector(
                allow_private=allow_private,
                endpoint_blocked=(lambda a, p, _own=own: _own_endpoint_blocked(a, p, _own)) if allow_private else None,
                private_only=allow_private and urlsplit(target).scheme == "http")
            timeout_cfg = aiohttp.ClientTimeout(total=15)
            async with aiohttp.ClientSession(connector=connector) as session:
                async with session.post(target, data=req.body, headers=req.headers,
                                         timeout=timeout_cfg,
                                         allow_redirects=req.follow_redirects and not allow_private) as resp:
                    response_status = resp.status
                    retry_after = resp.headers.get("Retry-After")
                    raw_answer = await resp.content.read(_WEBHOOK_ANSWER_MAX)      # never the whole body
                    text = raw_answer.decode("utf-8", "replace")
                    # What a third-party receiver answers is not kept for the other formats
                    response_body = text if fmt == "generic" else f"HTTP {resp.status}"
                    success = 200 <= resp.status < 300
            result["sent"] = True
        except Exception as e:
            if fmt == "generic":
                response_body = str(e)[:1024]
                logger.warning(f"Webhook {webhook_id} delivery failed (attempt {attempt}/{len(_WEBHOOK_RETRY_DELAYS)+1}): {e}")
            else:
                response_body = _webhook_error_text(e)
                logger.warning(f"Webhook {webhook_id} delivery failed (attempt {attempt}/{len(_WEBHOOK_RETRY_DELAYS)+1}): {response_body}")

        if response_status == 429:
            delay = webhook_formats.parse_retry_after(retry_after)
            if not single and waits < _WEBHOOK_MAX_429_WAITS:
                waits += 1
                _webhook_paused_until[webhook_id] = monotonic() + delay
                try:
                    await db.create_webhook_log(
                        webhook_id, event, request_payload=None, response_status=429,
                        response_body="HTTP 429, waiting for Retry-After", success=False,
                        attempt=attempt, duration_ms=int((monotonic() - start_time) * 1000))
                except Exception:
                    pass
                await _webhook_sleep(delay)
                # The hook may have been switched off, re-aimed, rotated or deleted, or the
                # event's channel made private, while we waited: do what the backoff retry
                # does and apply the rules again before anything more is sent.
                if not await _webhook_resend_allowed(webhook, event, meta):
                    result["status"] = response_status
                    result["error"] = "webhook changed while waiting"
                    return result
                continue
        break

    # Only the last attempt decides: a 429 followed by a 500 is an ordinary failure
    rate_limited = response_status == 429
    if success:
        _webhook_paused_until.pop(webhook_id, None)
    duration_ms = int((monotonic() - start_time) * 1000)
    result.update({"status": response_status, "success": success,
                   "error": None if success else (response_body if fmt != "generic" else "delivery failed")})

    try:
        await db.create_webhook_log(
            webhook_id, event,
            request_payload=req.body.decode("utf-8", "replace")[:8192] if fmt == "generic" else None,
            response_status=response_status,
            response_body=response_body,
            success=success,
            attempt=attempt,
            duration_ms=duration_ms
        )
    except Exception as e:
        logger.warning(f"Failed to log webhook delivery: {e}")

    if success:
        await db.reset_webhook_failures(webhook_id)
        return result

    if rate_limited:
        # The receiver is busy, not broken: never counts toward auto-disable
        return result

    # Handle failure
    try:
        new_count = await db.increment_webhook_failures(webhook_id, response_body or "Unknown error")
        if new_count >= _WEBHOOK_MAX_FAILURES:
            await db.disable_webhook(webhook_id)
            logger.warning(f"Webhook {webhook_id} auto-disabled after {new_count} consecutive failures")
            return result
    except Exception as e:
        logger.warning(f"Failed to update webhook failure count: {e}")
        return result

    # Retry with exponential backoff
    if not single and attempt <= len(_WEBHOOK_RETRY_DELAYS):
        delay = _WEBHOOK_RETRY_DELAYS[attempt - 1]
        await _webhook_sleep(delay)
        try:
            # The hook may have been edited or switched off while we waited: apply
            # what dispatch applies (subscription, event classes, and for a
            # non-generic format the third-party visibility of the event) again.
            w = await _webhook_current_for_event(webhook_id, event, meta)
            if w:
                await _deliver_webhook(w, event, payload, attempt + 1, meta=meta,
                                       waits_used=waits, drops=drops)
        except Exception:
            pass
    return result


# =========================================================================
# Webhook API Handlers
# =========================================================================

# One definition: webhook_formats.USER_EVENTS is the allow-list for user hooks ("*" also
# allowed); a system hook may in addition list the system-only events.
_USER_WEBHOOK_EVENTS = webhook_formats.USER_EVENTS | {"*"}
_SYSTEM_WEBHOOK_EVENTS = _USER_WEBHOOK_EVENTS | webhook_formats.SYSTEM_ONLY_EVENTS
_FORMAT_CREDENTIAL_KEYS = {
    "generic": (), "discord": (), "slack": (),
    "gotify": ("token",), "ntfy": ("token", "username", "password"),
}
_MAX_SYSTEM_WEBHOOKS = 20


def _bad_request(msg: str) -> web.Response:
    return web.json_response({"error": msg}, status=400)


def _merge_format_config(fmt: str, raw, existing_cfg: dict, same_format: bool):
    """(config dict, error text). Incoming keys are merged over the stored ones
    (an empty string removes a key), so editing a hook without sending its token
    keeps the token. A format change starts from nothing."""
    allowed = _FORMAT_CREDENTIAL_KEYS[fmt]
    cfg = dict(existing_cfg) if same_format else {}
    if raw is None:
        cfg = {}
    elif not isinstance(raw, dict):
        return None, "format_config must be an object"
    else:
        for k, v in raw.items():
            if k not in allowed:
                return None, f"format_config.{k} is not used by the {fmt} format"
            if v is None or v == "":
                cfg.pop(k, None)
                continue
            if not isinstance(v, str) or len(v) > 500 or _has_bad_chars(v) or any(ord(c) < 32 for c in v):
                return None, f"format_config.{k} is invalid"
            cfg[k] = v
    cfg = {k: v for k, v in cfg.items() if k in allowed}
    if fmt == "gotify" and not cfg.get("token"):
        return None, "The gotify format needs an application token (format_config.token)"
    if fmt == "ntfy" and (("username" in cfg) != ("password" in cfg)):
        return None, "ntfy basic auth needs both username and password"
    return cfg, None


_REQ_AUTH_TOKEN = "_webhook_auth_token"     # the token a route authenticated, kept on the request


async def _may_set_allow_private(request: web.Request, token) -> bool:
    """Whether the request may enable allow_private: only a superadmin acting through
    a browser login session.

    `token` is the credential the route authenticated (the actor). The authority is
    derived from that same token: it must be the web-session token carried by the
    cookie, so a request that authenticated by API key, bearer token, stream key or a
    ?token= value can never set it, whatever cookie it also carries.
    """
    if token is None:
        return False
    if (request.headers.get("Authorization") or request.headers.get("X-API-Key")
            or request.headers.get("X-Stream-Key") or request.query.get("token")):
        return False
    cookie = request.cookies.get(Config.SESSION_COOKIE_NAME)
    if not cookie:
        return False
    try:
        ctoken = await validate_token(cookie)
    except AuthError:
        return False
    if (ctoken.token_id != token.token_id or ctoken.user_id != token.user_id
            or not ctoken.has_scope("*")):
        return False
    row = await db.get_token(ctoken.token_id)
    if not row or row.get("name") != "web_session":
        return False
    user = await db.get_user_by_id(token.user_id)
    return bool(user and user.get("role") == "superadmin")


def _webhook_destination(url) -> tuple:
    """(scheme, host, port) of a webhook URL, for telling a new destination from a new path."""
    try:
        parts = urlsplit(str(url or ""))
        scheme = (parts.scheme or "").lower()
        port = parts.port or {"http": 80, "https": 443}.get(scheme)
        return (scheme, (parts.hostname or "").lower(), port)
    except ValueError:
        return ("?", str(url), None)


async def _outgoing_webhook_fields(body: dict, *, kind: str, existing: dict | None,
                                   may_private: bool):
    """Validate the outgoing-webhook fields of a create or update request.

    `existing` is the full stored hook (decrypted) on update, None on create.
    Returns (fields to store, error response). `fields` only holds what changes.
    """
    creating = existing is None
    out: dict = {}

    if creating or "name" in body:
        name = (body.get("name") or "").strip() if isinstance(body.get("name"), (str, type(None))) else ""
        if not name or len(name) > 100:
            return None, _bad_request("Name required (max 100 chars)")
        out["name"] = name

    old_fmt = existing["format"] if existing else "generic"
    fmt = body.get("format", old_fmt)
    if fmt not in webhook_formats.FORMATS:
        return None, _bad_request("format must be one of: " + ", ".join(webhook_formats.FORMATS))
    fmt_changed = fmt != old_fmt
    if "format" in body and fmt_changed:
        out["format"] = fmt

    old_private = bool(existing["allow_private"]) if existing else False
    if "allow_private" in body:
        if not isinstance(body["allow_private"], bool):
            return None, _bad_request("allow_private must be true or false")
        new_private = body["allow_private"]
    else:
        new_private = old_private
    if new_private and not old_private and not may_private:
        return None, web.json_response(
            {"error": "allow_private can only be set by a superadmin in a browser session"}, status=403)
    if "allow_private" in body and new_private != old_private:
        out["allow_private"] = new_private

    if "include_details" in body:
        if not isinstance(body["include_details"], bool):
            return None, _bad_request("include_details must be true or false")
        out["include_details"] = body["include_details"]

    if "enabled" in body and not creating:
        out["enabled"] = 1 if body["enabled"] else 0

    # events
    if creating or "events" in body:
        events = body.get("events")
        valid = _SYSTEM_WEBHOOK_EVENTS if kind == "system" else _USER_WEBHOOK_EVENTS
        if not events or not isinstance(events, list):
            return None, _bad_request("events list required for outgoing webhooks")
        if not all(isinstance(e, str) and e in valid for e in events):
            return None, _bad_request(f"Invalid events. Valid: {', '.join(sorted(valid))}")
        out["events"] = events

    # destination
    url_in_body = "url" in body
    if url_in_body:
        url = body["url"].strip() if isinstance(body["url"], str) else ""
        if not url:
            return None, _bad_request("URL required for outgoing webhooks")
        if len(url) > 2048:
            return None, _bad_request("URL too long (max 2048 chars)")
        if not url.startswith(("http://", "https://")):
            return None, _bad_request("URL must start with http:// or https://")
        out["url"] = url
    elif creating:
        return None, _bad_request("URL required for outgoing webhooks")
    # A generic hook's URL is shown by the API; the stored address of any other format
    # (a Discord or Slack webhook URL, an ntfy topic) is a credential that is never
    # returned. Switching to generic therefore never keeps it, and a format change never reuses
    # the stored address for another service: a new URL is required.
    if not creating and "format" in body and fmt_changed and not url_in_body:
        return None, _bad_request(
            "Changing the format needs a new url: the stored address of the old format is never reused or shown")
    # An existing allow_private hook's destination is the superadmin's decision
    if (not creating and old_private and new_private and not may_private
            and (url_in_body and out.get("url") != existing["url"] or fmt_changed)):
        return None, web.json_response(
            {"error": "This hook reaches a private address: only a superadmin in a browser session can change its URL or format"},
            status=403)
    effective_url = out.get("url") or (existing["url"] if existing else None)
    # The destination is re-checked against the default policy only when it really changes:
    # on create, a different URL, a different format, or allow_private switched on. Anything
    # else (renaming, disabling, changing events, switching allow_private off, or the admin
    # form sending the stored URL and allow_private again with every edit) is not a change
    # of destination. Delivery and the connector enforce the rules at every send: the
    # connector refuses an address the policy forbids, and _deliver_webhook refuses a
    # non-generic hook whose URL is plain http unless allow_private is on.
    url_changed = url_in_body and out.get("url") != (existing["url"] if existing else None)
    recheck = creating or url_changed or fmt_changed or (new_private and not old_private)
    if recheck and effective_url:
        if fmt != "generic" and not new_private and not effective_url.startswith("https://"):
            return None, _bad_request("This format needs an https:// URL (http is only allowed with allow_private)")
        err = await _validate_webhook_url(effective_url, new_private)
        if err:
            return None, _bad_request(err)

    # credentials. Stored credentials belong to the destination they were saved for: when the
    # scheme, host or port changes (a path-only change keeps them), or allow_private is
    # switched off together with a URL change, they are not carried over; the request has to
    # send them again.
    moved = (not creating and url_in_body and (
        _webhook_destination(out["url"]) != _webhook_destination(existing["url"])
        or (old_private and not new_private and out["url"] != existing["url"])))
    if moved and "format_config" not in body and fmt == "gotify" and not fmt_changed:
        return None, _bad_request(
            "The destination changed, so the stored credentials were not kept: "
            "send the gotify application token (format_config.token) again")
    if creating or "format_config" in body or fmt_changed or moved:
        cfg, err = _merge_format_config(
            fmt, body.get("format_config") if "format_config" in body else {},
            existing["format_config"] if existing else {}, fmt == old_fmt and not moved)
        if err:
            return None, _bad_request(err)
        out["format_config"] = cfg or None
    return out, None


async def _webhook_private_changed(request: web.Request, actor: dict, hook: dict, enabled: bool) -> None:
    """Security event and audit entry for allow_private being switched. Neither
    carries a URL or credential."""
    details = {"webhook_id": hook["id"], "kind": hook.get("kind"), "format": hook.get("format")}
    await security_event("webhook_allow_private", request=request, user=actor,
                         result="enabled" if enabled else "disabled", details=details)
    await audit_log("webhook_allow_private", actor["id"], actor["username"],
                    target_id=hook["id"], target_type="webhook", target_name=hook.get("name"),
                    details={**details, "enabled": enabled})


def _is_streamkey(token) -> bool:
    return str(getattr(token, "token_id", "") or "").startswith("streamkey-")


async def _webhook_route_token(request: web.Request, *, write: bool):
    """(token, error) for the user webhook routes. A stream key is refused on all of them
    with 403. Creating, changing or deleting a hook (and a new signing secret) needs a
    credential that carries its user's whole authority (a browser session or an all-scope
    token or key), the same rule as the other routes that change the account."""
    token = await authenticate_request(request)
    if not token:
        return None, unauthorized_response(request)
    if _is_streamkey(token):
        return None, full_scope_required_response()
    if write and not has_full_user_scope(token):
        return None, full_scope_required_response()
    return token, None


def _webhook_may_cross(token, user) -> bool:
    """Whether the caller may act on hooks of other users: the admin role, and a credential
    that itself carries admin power (scope admin or *), so a narrowly scoped key of an
    administrator cannot."""
    return bool(user and (user.get("is_admin") or user.get("role") in ("admin", "superadmin"))
                and (token.has_scope("admin") or token.has_scope("*")))


async def _webhook_show_token(webhook: dict, token) -> dict:
    """Add the URL token of an incoming hook to a read response, only for the hook's own owner
    using a credential that carries the whole authority of the account (a browser session or an
    all-scope token or key). Not for an administrator reading another user's hook, and not for a
    narrowly scoped key: the token is the credential of the hook. Creation returns it once."""
    if (webhook.get("has_token") and webhook.get("user_id") == token.user_id
            and has_full_user_scope(token)):
        webhook["token"] = await db.get_webhook_token(webhook["id"])
    return webhook


async def http_create_webhook(request: web.Request) -> web.Response:
    """Create a new webhook (admin+ only)."""
    token, err = await _webhook_route_token(request, write=True)
    if err:
        return err
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)
    is_admin = user.get("is_admin") or user.get("role") in ("admin", "superadmin")
    if not is_admin:
        return forbidden_response(request)

    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "Invalid JSON"}, status=400)

    name = (body.get("name") or "").strip() if isinstance(body.get("name"), (str, type(None))) else ""
    if not name or len(name) > 100:
        return web.json_response({"error": "Name required (max 100 chars)"}, status=400)

    webhook_type = body.get("type", "outgoing")
    if webhook_type not in ("outgoing", "incoming"):
        return web.json_response({"error": "Type must be 'outgoing' or 'incoming'"}, status=400)

    channel_id = None
    fields = {}
    if webhook_type == "outgoing":
        fields, err = await _outgoing_webhook_fields(
            body, kind="user", existing=None, may_private=await _may_set_allow_private(request, token))
        if err:
            return err

    if webhook_type == "incoming":
        channel_id = body.get("channel_id")
        if not channel_id:
            return web.json_response({"error": "channel_id required for incoming webhooks"}, status=400)
        try:
            channel_id = int(channel_id)
        except (ValueError, TypeError):
            return web.json_response({"error": "Invalid channel_id"}, status=400)
        channel = await db.get_chat_channel(channel_id)
        if not channel:
            return web.json_response({"error": "Channel not found"}, status=404)

    existing = await db.get_webhooks_for_user(token.user_id)
    if len(existing) >= 25:
        return web.json_response({"error": "Maximum 25 webhooks per user"}, status=400)

    webhook = await db.create_webhook(
        token.user_id, name, webhook_type,
        url=fields.get("url"), events=fields.get("events"), channel_id=channel_id,
        fmt=fields.get("format", "generic"), format_config=fields.get("format_config"),
        include_details=fields.get("include_details", False),
        allow_private=fields.get("allow_private", False), created_by=token.user_id)
    if fields.get("allow_private"):
        await _webhook_private_changed(request, user, webhook, True)
    return web.json_response(webhook, status=201)


async def http_list_webhooks(request: web.Request) -> web.Response:
    """List webhooks. Admins see all with owner info."""
    token, err = await _webhook_route_token(request, write=False)
    if err:
        return err
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)
    if _webhook_may_cross(token, user):
        webhooks = await db.get_all_webhooks()
    else:
        webhooks = await db.get_webhooks_for_user(token.user_id)
    webhooks = [await _webhook_show_token(w, token) for w in webhooks]
    return web.json_response({"webhooks": webhooks})


async def http_get_webhook(request: web.Request) -> web.Response:
    """Get a single webhook by ID (owner or admin)."""
    token, err = await _webhook_route_token(request, write=False)
    if err:
        return err
    try:
        webhook_id = int(request.match_info["id"])
    except (ValueError, KeyError):
        return web.json_response({"error": "Invalid webhook ID"}, status=400)

    webhook = await db.get_webhook(webhook_id)
    if not webhook or webhook.get("kind") != "user":      # system hooks have their own routes
        return web.json_response({"error": "Webhook not found"}, status=404)

    user = await db.get_user_by_id(token.user_id)
    is_admin = _webhook_may_cross(token, user)
    if webhook["user_id"] != token.user_id and not is_admin:
        return web.json_response({"error": "Webhook not found"}, status=404)

    return web.json_response(await _webhook_show_token(webhook, token))


async def http_update_webhook(request: web.Request) -> web.Response:
    """Update webhook (owner or admin)."""
    token, err = await _webhook_route_token(request, write=True)
    if err:
        return err
    try:
        webhook_id = int(request.match_info["id"])
    except (ValueError, KeyError):
        return web.json_response({"error": "Invalid webhook ID"}, status=400)

    webhook = await db.get_webhook(webhook_id)
    if not webhook or webhook.get("kind") != "user":      # system hooks have their own routes
        return web.json_response({"error": "Webhook not found"}, status=404)

    user = await db.get_user_by_id(token.user_id)
    is_admin = _webhook_may_cross(token, user)
    if webhook["user_id"] != token.user_id and not is_admin:
        return web.json_response({"error": "Webhook not found"}, status=404)

    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    if not isinstance(body, dict):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    updates = {}
    if webhook["type"] == "outgoing":
        full = await db.get_webhook_for_delivery(webhook_id)
        updates, err = await _outgoing_webhook_fields(
            body, kind="user", existing=full, may_private=await _may_set_allow_private(request, token))
        if err:
            return err
    else:
        if "name" in body:
            name = (body["name"] or "").strip() if isinstance(body["name"], str) else ""
            if not name or len(name) > 100:
                return web.json_response({"error": "Name required (max 100 chars)"}, status=400)
            updates["name"] = name
        if "channel_id" in body:
            try:
                ch_id = int(body["channel_id"])
            except (ValueError, TypeError):
                return web.json_response({"error": "Invalid channel_id"}, status=400)
            ch = await db.get_chat_channel(ch_id)
            if not ch:
                return web.json_response({"error": "Channel not found"}, status=404)
            updates["channel_id"] = ch_id
        if "enabled" in body:
            updates["enabled"] = 1 if body["enabled"] else 0

    if updates:
        await db.update_webhook(webhook_id, **updates)
        if "allow_private" in updates:
            await _webhook_private_changed(request, user, webhook, bool(updates["allow_private"]))

    updated = await db.get_webhook(webhook_id)
    return web.json_response(await _webhook_show_token(updated, token))


async def http_delete_webhook(request: web.Request) -> web.Response:
    """Delete webhook (owner or admin)."""
    token, err = await _webhook_route_token(request, write=True)
    if err:
        return err
    try:
        webhook_id = int(request.match_info["id"])
    except (ValueError, KeyError):
        return web.json_response({"error": "Invalid webhook ID"}, status=400)

    webhook = await db.get_webhook(webhook_id)
    if not webhook or webhook.get("kind") != "user":      # system hooks have their own routes
        return web.json_response({"error": "Webhook not found"}, status=404)

    user = await db.get_user_by_id(token.user_id)
    is_admin = _webhook_may_cross(token, user)
    if webhook["user_id"] != token.user_id and not is_admin:
        return web.json_response({"error": "Webhook not found"}, status=404)

    await db.delete_webhook(webhook_id)
    _webhook_rate_limits.pop(webhook_id, None)
    _webhook_paused_until.pop(webhook_id, None)
    return web.json_response({"message": "Webhook deleted"})


async def http_get_webhook_logs(request: web.Request) -> web.Response:
    """Get delivery logs for a webhook (owner or admin)."""
    token, err = await _webhook_route_token(request, write=False)
    if err:
        return err
    try:
        webhook_id = int(request.match_info["id"])
    except (ValueError, KeyError):
        return web.json_response({"error": "Invalid webhook ID"}, status=400)

    webhook = await db.get_webhook(webhook_id)
    if not webhook or webhook.get("kind") != "user":      # system hooks have their own routes
        return web.json_response({"error": "Webhook not found"}, status=404)

    user = await db.get_user_by_id(token.user_id)
    is_admin = _webhook_may_cross(token, user)
    if webhook["user_id"] != token.user_id and not is_admin:
        return web.json_response({"error": "Webhook not found"}, status=404)

    try:
        limit = min(int(request.query.get("limit", 50)), 200)
        offset = max(int(request.query.get("offset", 0)), 0)
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid limit/offset"}, status=400)
    logs = await db.get_webhook_logs(webhook_id, limit=limit, offset=offset)
    return web.json_response({"logs": logs})


async def http_test_webhook(request: web.Request) -> web.Response:
    """Send a test event to the webhook. Needs a full-scope credential: it triggers a delivery."""
    token, err = await _webhook_route_token(request, write=True)
    if err:
        return err
    try:
        webhook_id = int(request.match_info["id"])
    except (ValueError, KeyError):
        return web.json_response({"error": "Invalid webhook ID"}, status=400)

    webhook = await db.get_webhook(webhook_id)
    if not webhook or webhook.get("kind") != "user":      # system hooks have their own routes
        return web.json_response({"error": "Webhook not found"}, status=404)

    user = await db.get_user_by_id(token.user_id)
    is_admin = _webhook_may_cross(token, user)
    if webhook["user_id"] != token.user_id and not is_admin:
        return web.json_response({"error": "Webhook not found"}, status=404)

    if webhook["type"] != "outgoing":
        return web.json_response({"error": "Can only test outgoing webhooks"}, status=400)
    if not webhook.get("enabled"):
        return web.json_response({"error": "Webhook is disabled"}, status=400)

    full_wh = await db.get_webhook_for_delivery(webhook_id)
    if not full_wh:
        return web.json_response({"error": "Could not load webhook for test"}, status=500)

    return await _run_webhook_test(full_wh, user)


async def _run_webhook_test(full_wh: dict, user: dict) -> web.Response:
    """Send one sample in the hook's format and report the receiver's status code.

    One attempt, no retry schedule and no Retry-After wait (a 429 is reported
    at once). The answer carries the status and a short reason, never the
    receiver's body or the destination.
    """
    try:
        result = await asyncio.wait_for(_deliver_webhook(full_wh, "webhook.test", {
            "test": True,
            "webhook_id": full_wh["id"],
            "triggered_by": user["username"] if user else "unknown"
        }, single=True), timeout=25)
    except asyncio.TimeoutError:
        result = {"sent": False, "status": None, "success": False, "error": "timeout"}
    return web.json_response({
        "message": "Test event delivered" if result["success"] else "Test event was not accepted",
        "format": full_wh.get("format") or "generic",
        "sent": result["sent"],
        "success": result["success"],
        "status": result["status"],
        "error": None if result["success"] else result["error"],
    })


async def http_regenerate_webhook_secret(request: web.Request) -> web.Response:
    """Regenerate the HMAC signing secret. Returns new secret (shown once)."""
    token, err = await _webhook_route_token(request, write=True)
    if err:
        return err
    try:
        webhook_id = int(request.match_info["id"])
    except (ValueError, KeyError):
        return web.json_response({"error": "Invalid webhook ID"}, status=400)

    webhook = await db.get_webhook(webhook_id)
    if not webhook or webhook.get("kind") != "user":      # system hooks have their own routes
        return web.json_response({"error": "Webhook not found"}, status=404)

    user = await db.get_user_by_id(token.user_id)
    is_admin = _webhook_may_cross(token, user)
    if webhook["user_id"] != token.user_id and not is_admin:
        return web.json_response({"error": "Webhook not found"}, status=404)

    if webhook.get("format") != "generic":
        return web.json_response({"error": "Only the generic format is signed"}, status=400)

    new_secret = await db.regenerate_webhook_secret(webhook_id)
    if not new_secret:
        return web.json_response({"error": "Failed to regenerate secret"}, status=500)

    return web.json_response({"secret": new_secret, "message": "Secret regenerated. Store it securely — it will not be shown again."})


# ---- System webhooks: no owner, superadmins only (Admin > Webhooks) ----------

def _webhook_log_view(row: dict) -> dict:
    """A delivery record without payload or response body."""
    return {k: row.get(k) for k in ("id", "event", "response_status", "success", "attempt",
                                    "duration_ms", "created_at")}


async def _system_webhook_or_404(request: web.Request):
    """(user, hook, error). Only a superadmin gets past; the hook must be a system hook."""
    user, err = await _backup_superadmin(request)
    if err:
        return None, None, err
    try:
        webhook_id = int(request.match_info["id"])
    except (ValueError, KeyError):
        return None, None, web.json_response({"error": "Invalid webhook ID"}, status=400)
    hook = await db.get_webhook(webhook_id)
    if not hook or hook.get("kind") != "system":
        return None, None, web.json_response({"error": "Webhook not found"}, status=404)
    return user, hook, None


async def http_admin_webhooks_list(request: web.Request) -> web.Response:
    """List system webhooks, with what the form needs (formats and valid events)."""
    user, err = await _backup_superadmin(request)
    if err:
        return err
    return web.json_response({
        "webhooks": await db.get_system_webhooks(),
        "formats": list(webhook_formats.FORMATS),
        "events": sorted(_SYSTEM_WEBHOOK_EVENTS),
        "system_only_events": sorted(webhook_formats.SYSTEM_ONLY_EVENTS),
        "alert_groups": alerts.catalogue(),
    })


async def http_admin_alerts_get(request: web.Request) -> web.Response:
    """GET /api/admin/alerts - alert event groups and the in-portal notification switches."""
    user, err = await _backup_superadmin(request)
    if err:
        return err
    return web.json_response({"groups": alerts.catalogue(), "notify": await alerts.notify_settings()})


async def http_admin_alerts_notify(request: web.Request) -> web.Response:
    """PUT /api/admin/alerts/notify - {"event": "role.changed", "enabled": true}: whether an alert
    also creates an in-portal notification for every administrator."""
    user, err = await _backup_superadmin(request)
    if err:
        return err
    try:
        body = await request.json()
    except Exception:
        return _bad_request("Invalid JSON")
    if not isinstance(body, dict) or not isinstance(body.get("enabled"), bool) \
            or body.get("event") not in alerts.EVENT_NAMES:
        return _bad_request("event (an alert event name) and enabled (true or false) are required")
    await alerts.set_notify(body["event"], body["enabled"])
    await audit_log("alert_notify_change", user["id"], user["username"], target_name=body["event"],
                    details=json.dumps({"enabled": body["enabled"]}))
    return web.json_response({"event": body["event"], "enabled": body["enabled"]})


async def http_admin_alerts_stage_reset(request: web.Request) -> web.Response:
    """POST /api/admin/alerts/stage-reset - forget every cooldown, the global cap and the
    counters, so a smoke check starts from a known state. A staged instance only: any other
    instance answers 404 as if the route did not exist."""
    if not Config.STAGE_MODE:
        return web.json_response({"error": "Not found"}, status=404)
    user, err = await _backup_superadmin(request)
    if err:
        return err
    alerts.reset_state()
    return web.json_response({"success": True})


async def http_admin_webhooks_create(request: web.Request) -> web.Response:
    user, err = await _backup_superadmin(request)
    if err:
        return err
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if await db.count_system_webhooks() >= _MAX_SYSTEM_WEBHOOKS:
        return _bad_request(f"Maximum {_MAX_SYSTEM_WEBHOOKS} system webhooks")
    fields, err = await _outgoing_webhook_fields(
        body, kind="system", existing=None, may_private=await _may_set_allow_private(request, request.get(_REQ_AUTH_TOKEN)))
    if err:
        return err
    hook = await db.create_webhook(
        None, fields["name"], "outgoing", url=fields["url"], events=fields["events"],
        kind="system", fmt=fields.get("format", "generic"), format_config=fields.get("format_config"),
        include_details=fields.get("include_details", False),
        allow_private=fields.get("allow_private", False), created_by=user["id"])
    await audit_log("webhook_system_create", user["id"], user["username"], target_id=hook["id"],
                    target_type="webhook", target_name=hook["name"],
                    details={"format": hook["format"], "events": hook["events"]})
    if fields.get("allow_private"):
        await _webhook_private_changed(request, user, hook, True)
    return web.json_response(hook, status=201)


async def http_admin_webhooks_get(request: web.Request) -> web.Response:
    user, hook, err = await _system_webhook_or_404(request)
    if err:
        return err
    return web.json_response(hook)


async def http_admin_webhooks_update(request: web.Request) -> web.Response:
    user, hook, err = await _system_webhook_or_404(request)
    if err:
        return err
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(body, dict):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    full = await db.get_webhook_for_delivery(hook["id"])
    updates, err = await _outgoing_webhook_fields(
        body, kind="system", existing=full, may_private=await _may_set_allow_private(request, request.get(_REQ_AUTH_TOKEN)))
    if err:
        return err
    if updates:
        await db.update_webhook(hook["id"], **updates)
        await audit_log("webhook_system_update", user["id"], user["username"], target_id=hook["id"],
                        target_type="webhook", target_name=hook["name"],
                        details={"fields": sorted(k for k in updates if k not in ("url", "format_config"))
                                 + [k for k in ("url", "format_config") if k in updates]})
        if "allow_private" in updates:
            await _webhook_private_changed(request, user, hook, bool(updates["allow_private"]))
    return web.json_response(await db.get_webhook(hook["id"]))


async def http_admin_webhooks_delete(request: web.Request) -> web.Response:
    user, hook, err = await _system_webhook_or_404(request)
    if err:
        return err
    await db.delete_webhook(hook["id"])
    _webhook_rate_limits.pop(hook["id"], None)
    _webhook_paused_until.pop(hook["id"], None)
    await audit_log("webhook_system_delete", user["id"], user["username"], target_id=hook["id"],
                    target_type="webhook", target_name=hook["name"])
    return web.json_response({"message": "Webhook deleted"})


async def http_admin_webhooks_logs(request: web.Request) -> web.Response:
    """Recent deliveries: status, event, time. Never the payload or the receiver's answer."""
    user, hook, err = await _system_webhook_or_404(request)
    if err:
        return err
    try:
        limit = min(max(int(request.query.get("limit", 20)), 1), 100)
    except (ValueError, TypeError):
        return _bad_request("Invalid limit")
    rows = await db.get_webhook_logs(hook["id"], limit=limit, offset=0)
    return web.json_response({"logs": [_webhook_log_view(r) for r in rows]})


async def http_admin_webhooks_test(request: web.Request) -> web.Response:
    user, hook, err = await _system_webhook_or_404(request)
    if err:
        return err
    if not hook.get("enabled"):
        return _bad_request("Webhook is disabled")
    full = await db.get_webhook_for_delivery(hook["id"])
    if not full:
        return web.json_response({"error": "Could not load webhook for test"}, status=500)
    return await _run_webhook_test(full, user)


async def http_admin_webhooks_secret(request: web.Request) -> web.Response:
    user, hook, err = await _system_webhook_or_404(request)
    if err:
        return err
    if hook.get("format") != "generic":
        return _bad_request("Only the generic format is signed")
    new_secret = await db.regenerate_webhook_secret(hook["id"])
    if not new_secret:
        return web.json_response({"error": "Failed to regenerate secret"}, status=500)
    return web.json_response({"secret": new_secret, "message": "Secret regenerated. Store it securely, it will not be shown again."})


async def http_incoming_webhook(request: web.Request) -> web.Response:
    """Receive an incoming webhook and post message to configured channel."""
    client_ip = get_client_ip(request)
    if not check_rate_limit(client_ip):
        return web.json_response({"error": "Rate limit exceeded"}, status=429)

    token_str = request.match_info.get("token", "")
    if not token_str or len(token_str) > 64:
        return web.json_response({"error": "Not found"}, status=404)

    webhook = await db.get_webhook_by_token(token_str)
    if not webhook or webhook["type"] != "incoming" or not webhook.get("enabled"):
        return web.json_response({"error": "Not found"}, status=404)

    # Per-token rate limit
    now = monotonic()
    window_start = now - _WEBHOOK_INCOMING_WINDOW
    times = _webhook_incoming_rate_limits.setdefault(token_str, [])
    _webhook_incoming_rate_limits[token_str] = [t for t in times if t > window_start]
    if len(_webhook_incoming_rate_limits[token_str]) >= _WEBHOOK_INCOMING_RATE:
        return web.json_response({"error": "Rate limit exceeded"}, status=429)
    _webhook_incoming_rate_limits[token_str].append(now)

    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    content = (body.get("content") or body.get("text") or "").strip()
    if not content:
        return web.json_response({"error": "content or text field required"}, status=400)
    if len(content) > 4000:
        return web.json_response({"error": "Message too long (max 4000 chars)"}, status=400)

    display_name = (body.get("username") or webhook["name"] or "Webhook").strip()
    if len(display_name) > 50:
        display_name = display_name[:50]

    channel_id = webhook["channel_id"]
    channel = await db.get_chat_channel(channel_id)
    if not channel:
        return web.json_response({"error": "Target channel not found"}, status=404)

    msg_id = await db.create_chat_message(
        channel_id, webhook["user_id"], f"[hook] {display_name}",
        content, message_type="webhook"
    )

    await broadcast_to_channel(channel["name"], {
        "type": "message",
        "id": msg_id,
        "user_id": webhook["user_id"],
        "username": f"[hook] {display_name}",
        "message": content,
        "webhook": True,
        "created_at": datetime.now(timezone.utc).isoformat()
    })

    asyncio.create_task(fire_webhook_event("message.created", {
        "message_id": msg_id,
        "channel": channel["name"],
        "channel_id": channel_id,
        "username": f"[hook] {display_name}",
        "message": content,
        "source": "incoming_webhook",
        "webhook_id": webhook["id"]
    }, meta={"channel_id": channel_id}))

    return web.json_response({"ok": True, "message_id": msg_id})


async def http_stream_auth(request: web.Request) -> web.Response:
    """MediaMTX stream authentication hook.

    Called by MediaMTX when a client tries to publish or play a stream.
    Validates stream key for publishing, allows viewing of public streams.
    Only accepts requests from local/private IPs (MediaMTX runs on the same machine).
    """
    # Restrict to internal IPs — MediaMTX hooks only, not public API.
    if not _is_internal_request(request):
        return web.json_response({"error": "Forbidden"}, status=403)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    action = data.get("action", "publish")  # publish, read, playback
    path = data.get("path", "")
    query = data.get("query", "")
    user = data.get("user", "")
    password = data.get("password", "")
    ip = data.get("ip", "")

    logger.debug(f"Stream auth request: action={action}, path={path}, user={user}, ip={ip}")

    # For publishing, the stream key is passed as the password or in the path
    # OBS typically sends: rtmp://server/live/stream_key or uses username/password
    stream_key = password or (path.split("/")[-1] if path else "")

    if action == "publish":
        # Resolve stream from key — supports live_ (permanent) and rtmp_ (temporary token)
        real_stream_key = None  # The live_ key for VOD recording
        stream = None

        if stream_key and stream_key.startswith("rtmp_"):
            # Validate temporary RTMP publish token
            if not Config.RTMP_PLAIN_ENABLED:
                logger.warning(f"RTMP token rejected (plain RTMP disabled globally) from {ip}")
                return web.json_response({"error": "Plain RTMP is disabled"}, status=401)

            token_hash = hashlib.sha256(stream_key.encode()).hexdigest()
            token_record = await db.get_rtmp_token(token_hash)
            if not token_record:
                logger.warning(f"Unknown RTMP token from {ip}")
                return web.json_response({"error": "Invalid token"}, status=401)
            if token_record["revoked"]:
                logger.warning(f"Revoked RTMP token from {ip}")
                return web.json_response({"error": "Token revoked"}, status=401)
            if token_record["used"]:
                # IP-bound reconnect: verify IP matches
                bound_ip = token_record.get("bound_ip")
                if bound_ip and bound_ip != ip:
                    logger.warning(f"RTMP token IP mismatch: bound={bound_ip}, got {ip}")
                    return web.json_response({"error": "Token bound to different IP"}, status=401)
                # Rolling grace window from last activity
                last_active_str = token_record.get("last_active_at") or token_record.get("used_at")
                last_active = datetime.fromisoformat(last_active_str)
                if last_active.tzinfo is None:
                    last_active = last_active.replace(tzinfo=timezone.utc)
                grace = timedelta(seconds=Config.RTMP_TOKEN_GRACE_SECONDS)
                if datetime.now(timezone.utc) - last_active > grace:
                    logger.warning(f"RTMP token grace period expired from {ip} (last active {last_active_str})")
                    return web.json_response({"error": "Token expired (reconnect grace period)"}, status=401)
                # Refresh activity timestamp for rolling window
                await db.refresh_rtmp_token_activity(token_record["id"])
                # Bind IP on reconnect if not yet bound (pre-migration tokens)
                if not bound_ip:
                    await db.mark_rtmp_token_used(token_record["id"], ip)
                logger.info(f"RTMP token reconnect from bound IP {ip}")
            else:
                # First use: check creation expiry window
                expires = datetime.fromisoformat(token_record["expires_at"])
                if expires.tzinfo is None:
                    expires = expires.replace(tzinfo=timezone.utc)
                if expires < datetime.now(timezone.utc):
                    logger.warning(f"Expired RTMP token from {ip}")
                    return web.json_response({"error": "Token expired"}, status=401)
                # Bind to IP and mark as used
                await db.mark_rtmp_token_used(token_record["id"], ip)
                logger.info(f"RTMP token bound to IP {ip}")
            # Verify stream has rtmp_enabled
            if not token_record.get("rtmp_enabled"):
                logger.warning(f"RTMP token for stream with RTMP disabled from {ip}")
                return web.json_response({"error": "RTMP disabled on this stream"}, status=401)

            # Build a stream-like dict from JOIN result for downstream compatibility
            real_stream_key = token_record.get("stream_key", "")
            stream = {
                "id": token_record["stream_id"],
                "user_id": token_record.get("stream_user_id", token_record.get("user_id")),
                "name": token_record.get("stream_name", ""),
                "is_public": token_record.get("is_public"),
                "is_live": token_record.get("is_live"),
                "chat_channel_id": token_record.get("chat_channel_id"),
                "allow_unauthenticated": token_record.get("allow_unauthenticated"),
                "viewer_count": token_record.get("viewer_count", 0),
                "started_at": token_record.get("started_at"),
                "ended_at": token_record.get("ended_at"),
                "thumbnail_url": token_record.get("thumbnail_url"),
                "owner_username": token_record.get("owner_username"),
                "owner_nickname": token_record.get("owner_nickname"),
                "public_key": token_record.get("public_key"),
            }
            logger.info(f"RTMP token auth successful for stream {stream['name']} from {ip}")
            # Store path mapping so HLS/thumbnail/VOD can find the MediaMTX path
            async with _stream_state_lock:
                _rtmp_stream_paths[token_record["stream_id"]] = stream_key

        elif stream_key and stream_key.startswith("live_"):
            stream = await db.get_stream_by_key(stream_key)
            if not stream:
                logger.warning(f"Unknown stream key from {ip}")
                return web.json_response({"error": "Invalid stream key"}, status=401)
            real_stream_key = stream_key
        else:
            logger.warning(f"Invalid stream key attempt from {ip}")
            return web.json_response({"error": "Invalid stream key"}, status=401)

        # Cancel any pending disconnect grace task (stream reconnected)
        stream_id = stream["id"]
        async with _stream_state_lock:
            grace_task = _disconnect_grace_tasks.pop(stream_id, None)
        if grace_task and not grace_task.done():
            grace_task.cancel()
            logger.info(f"Stream {stream['name']} reconnected, cancelled disconnect grace period")

        # Mark stream as live (only log activity on state change)
        was_live = stream.get("is_live") == 1
        await db.set_stream_live(stream_id, True)
        if not was_live:
            logger.info(f"Stream {stream['name']} started by user {stream.get('owner_username', '?')} from {ip}")
            await db.log_activity(stream.get("user_id"), get_display_name(stream), _stream_activity_type("stream_live", stream), f"Stream '{stream['name']}' went live", ip)
            # Notify chat channel that stream went live
            if stream.get("chat_channel_id"):
                channel = await db.get_chat_channel(stream["chat_channel_id"])
                if channel:
                    await broadcast_to_channel(channel["name"], {
                        "type": "stream_status",
                        "stream_id": stream_id,
                        "is_live": 1
                    })
            # Announce it (notification and webhook), once per cooldown. The check and
            # the set are one conditional UPDATE, taken under the stream state lock, so
            # a retried hook or an encoder that restarts quickly announces only once.
            # The announcement carries no key; the watch page resolves access itself.
            try:
                async with _stream_state_lock:
                    announce = await db.claim_golive(
                        stream_id, int(_golive_now()), _GOLIVE_COOLDOWN_SECONDS)
            except Exception as e:
                # A database fault must not stop a stream; nothing is announced
                logger.warning(f"Go-live claim for stream {stream_id} failed: {type(e).__name__}: {e}")
                announce = False
            if announce:
                _spawn_go_live(stream_id)          # fan-out in the background: the hook answers at once
            else:
                logger.info(f"Stream {stream['name']}: go-live not announced again (cooldown)")

        # Start VOD recording on every publish (guards against duplicates internally)
        # Use the actual MediaMTX path key (rtmp_ token or live_ key)
        vod_stream_key = stream_key if stream_key.startswith("rtmp_") else (real_stream_key or stream_key)
        asyncio.create_task(start_vod_recording(stream, vod_stream_key))

        # Start multi-platform relays
        asyncio.create_task(start_stream_relays(stream, vod_stream_key))

        return web.json_response({"allowed": True})

    elif action in ("read", "playback"):
        # The one read decision (_stream_read_allowed) also holds here. MediaMTX is
        # configured to skip this hook for reads (authHTTPExclude), and every reader
        # of its HLS/RTSP/WebRTC ports is on this machine: the portal's own HLS
        # proxy, the thumbnail ffmpeg, the recorder and the relays. A loopback
        # reader is therefore the portal's own and is let through; viewers are
        # judged in the portal's playback routes.
        if not path:
            return web.json_response({"error": "Path required"}, status=400)
        if _is_loopback_ip(ip):
            return web.json_response({"allowed": True})

        # Anybody else (a reader of the externally reachable RTMPS port) is judged
        # as a viewer: the stream is named by its live_ path, and the credential is
        # a full-access API key sent as the password. A key in the path is never
        # a way to watch.
        stream_key_from_path = path.split("/")[-1] if "/" in path else path
        stream = None
        if stream_key_from_path.startswith("live_"):
            stream = await db.get_stream_by_key(stream_key_from_path)
        user_id, role = None, "user"
        if stream and password:
            token = await authenticate_api_key(password)
            if token is not None and has_full_user_scope(token):
                user_id = token.user_id
                role = await get_user_role_from_token(token)
        if stream and user_id is not None and _stream_read_allowed(stream, user_id, role, False):
            return web.json_response({"allowed": True})

        # Default deny for unrecognized streams or unauthorized access
        return web.json_response({"error": "Access denied"}, status=403)

    return web.json_response({"error": "Unknown action"}, status=400)


async def http_stream_event(request: web.Request) -> web.Response:
    """MediaMTX stream event hook.

    Called when streams start/stop for updating live status.
    Only accepts requests from local/private IPs (MediaMTX runs on the same machine).
    """
    # Restrict to internal IPs — MediaMTX hooks only, not public API.
    if not _is_internal_request(request):
        return web.json_response({"error": "Forbidden"}, status=403)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    event = data.get("event", "")
    path = data.get("path", "")

    logger.debug(f"Stream event: event={event}, path={path}")

    if event == "disconnect" and path:
        # Find stream and mark as offline (after grace period)
        stream_key = path.split("/")[-1] if "/" in path else path
        # Handle rtmp_ token paths — map back to parent stream
        if stream_key.startswith("rtmp_"):
            token_hash = hashlib.sha256(stream_key.encode()).hexdigest()
            token_record = await db.get_rtmp_token(token_hash)
            if token_record:
                # Refresh activity so reconnect grace starts from disconnect moment
                await db.refresh_rtmp_token_activity(token_record["id"])
                if token_record.get("stream_key"):
                    stream = await db.get_stream_by_key(token_record["stream_key"])
                else:
                    stream = None
            else:
                stream = None
        else:
            stream = await db.get_stream_by_key(stream_key)
        if stream:
            stream_id = stream["id"]

            async with _stream_state_lock:
                # Clean up rtmp_ path mapping
                _rtmp_stream_paths.pop(stream_id, None)

                # Cancel any existing grace task for this stream (shouldn't happen, but be safe)
                existing_task = _disconnect_grace_tasks.pop(stream_id, None)
                if existing_task and not existing_task.done():
                    existing_task.cancel()

                # Spawn grace period task — waits before triggering encoding/offline
                logger.info(f"Stream {stream['name']} disconnected, starting 7s grace period...")
                task = asyncio.create_task(_handle_disconnect_grace(stream))
                _disconnect_grace_tasks[stream_id] = task

    return web.json_response({"ok": True})


# =============================================================================
# Stream Proxy API (routes MediaMTX traffic through port 443)
# =============================================================================


async def _get_mediamtx_config() -> dict:
    """Get MediaMTX service configuration."""
    if not _service_manager:
        return {}

    # Find MediaMTX service
    for svc in _service_manager.get_all_services():
        if svc.get_info().name == "mediamtx":
            return svc.get_merged_config()
    return {}


_STREAM_NOT_FOUND = "Stream not found"

# Playback authorisation cache. One entry per (credential, key in the URL):
# (fingerprint of the credentials the request carried or "anon", sha256 of the
# key) -> (expires, user_id or None, stream_id, stream record, allowed).
# It sits in front of everything a playback request would read from the
# database (the key lookup, the credential check, the user), so the many
# segment requests of one viewer cost no database reads. An entry lives at most
# _PLAYBACK_AUTH_TTL seconds; it is dropped at once when the stream's
# visibility, open-link flag or keys change, when the stream is deleted and
# when the credential's owner is signed out (close_user_websockets).
_PLAYBACK_AUTH_TTL = 5.0
_PLAYBACK_AUTH_MAX = 2048
_playback_auth_cache: dict[tuple[str, str], tuple] = {}
_playback_auth_generation = 0


def _playback_now() -> float:
    return monotonic()


def _stream_is_open(stream: dict) -> bool:
    """A public stream whose share link is open to people who are not logged in."""
    return bool(stream.get("is_public")) and bool(stream.get("allow_unauthenticated"))


def _stream_read_allowed(stream: dict, user_id: Optional[int], role: str, via_pub_key: bool) -> bool:
    """The one decision on whether somebody may watch a stream (HLS, thumbnail,
    WHEP, the info route and the MediaMTX hook's read action).

    The owner and admins always. Any other logged-in member only when the stream
    is public. Nobody logged in only when the stream is public with the open
    link on and the request carries that stream's current pub_ key.
    """
    if user_id is not None:
        if stream.get("user_id") == user_id or role in ("admin", "superadmin"):
            return True
        return bool(stream.get("is_public"))
    return via_pub_key and _stream_is_open(stream)


def _playback_cache_forget(stream_id: Optional[int] = None, user_id: Optional[int] = None,
                           everything: bool = False) -> int:
    """Drop cached playback decisions: those about one stream, those made for one
    user, or all. Returns the number dropped."""
    global _playback_auth_generation
    _playback_auth_generation += 1
    if everything:
        n = len(_playback_auth_cache)
        _playback_auth_cache.clear()
        return n
    doomed = [k for k, v in _playback_auth_cache.items()
              if (stream_id is not None and v[2] == stream_id)
              or (user_id is not None and v[1] == user_id)]
    for k in doomed:
        del _playback_auth_cache[k]
    return len(doomed)


def _webrtc_forget_playback(stream_id: int) -> int:
    """Forget the WHEP sessions opened for a stream: their PATCH and DELETE calls
    through the portal stop working. (Media already flowing goes straight to
    MediaMTX and is not touched by this.)"""
    doomed = [k for k, v in _webrtc_sessions.items() if v[0] == "whep" and v[1] == stream_id]
    for k in doomed:
        del _webrtc_sessions[k]
    return len(doomed)


def _stream_access_changed(stream_id: int, drop_sessions: bool = True) -> None:
    """Call when a stream's visibility, open-link flag, share key or publish key
    changed, or the stream was deleted: viewers are asked again at once. A change
    that cannot take anybody's right away (a rename) passes drop_sessions=False
    and keeps the viewers' WHEP session records."""
    _playback_cache_forget(stream_id=stream_id)
    if drop_sessions:
        _webrtc_forget_playback(stream_id)


def _playback_fingerprint(request: web.Request) -> str:
    """A fingerprint of the credentials a request carries ("anon" for none).
    Stream keys do not count: they are not a way to watch. It is taken without any
    database read so a cached decision can be found before authenticating."""
    parts = []
    auth_header = request.headers.get("Authorization", "")
    if auth_header.startswith(("Bearer ", "Api-Key ")):
        parts.append("a:" + auth_header)
    api_key = request.headers.get("X-API-Key")
    if api_key:
        parts.append("x:" + api_key)
    qtoken = request.query.get("token")
    if qtoken:
        parts.append("q:" + qtoken)
    cookie = request.cookies.get(Config.SESSION_COOKIE_NAME)
    if cookie:
        parts.append("c:" + cookie)
    if not parts:
        return "anon"
    return hashlib.sha256("\0".join(parts).encode("utf-8", "surrogatepass")).hexdigest()[:32]


async def _resolve_stream_by_any_key(key: str) -> tuple[Optional[dict], bool]:
    """(stream, via_pub_key). A live_ (or bare) key only names the stream here: it
    gives no right to watch it."""
    if key.startswith("pub_"):
        return await db.get_stream_by_public_key(key), True
    if not key.startswith("live_"):
        key = f"live_{key}"
    return await db.get_stream_by_key(key), False


async def _stream_read_access(request: web.Request, key: str) -> tuple[Optional[dict], str]:
    """Authorise a request to watch the stream named by `key` in its URL.

    Returns (stream, "") or (None, "Stream not found"). A key that matches nothing,
    a rotated key and a stream the requester may not see all give the same
    answer, so a private stream's existence and live state are not revealed.
    The credential is the session cookie or a full-access token or API key; a
    stream key (live_) is never one.
    """
    if not key or request is None:
        return None, _STREAM_NOT_FOUND
    ckey = (_playback_fingerprint(request), hashlib.sha256(key.encode("utf-8", "surrogatepass")).hexdigest())
    now = _playback_now()
    hit = _playback_auth_cache.get(ckey)
    if hit is not None and hit[0] > now:
        return (hit[3], "") if hit[4] else (None, _STREAM_NOT_FOUND)
    generation = _playback_auth_generation

    stream, via_pub_key = await _resolve_stream_by_any_key(key)
    if not stream:
        return None, _STREAM_NOT_FOUND
    user_id, role = None, "user"
    token = await authenticate_request(request, allow_stream_key=False)
    if token is not None and has_full_user_scope(token):
        user_id = token.user_id
        role = await get_user_role_from_token(token)
    allowed = _stream_read_allowed(stream, user_id, role, via_pub_key)

    if generation == _playback_auth_generation:
        if len(_playback_auth_cache) >= _PLAYBACK_AUTH_MAX:
            for k in [k for k, v in _playback_auth_cache.items() if v[0] <= now]:
                del _playback_auth_cache[k]
            if len(_playback_auth_cache) >= _PLAYBACK_AUTH_MAX:
                # Still full: drop the oldest decisions (a batch, so a flood does not
                # pay for a sort on every request), never everybody's at once.
                batch = max(1, _PLAYBACK_AUTH_MAX // 8)
                oldest = heapq.nsmallest(batch, _playback_auth_cache.items(), key=lambda kv: kv[1][0])
                for k, _v in oldest:
                    del _playback_auth_cache[k]
        _playback_auth_cache[ckey] = (now + _PLAYBACK_AUTH_TTL, user_id, stream["id"], stream, allowed)
    return (stream, "") if allowed else (None, _STREAM_NOT_FOUND)


async def _validate_stream_access(key: str, require_publish: bool = False,
                                  request: Optional[web.Request] = None) -> tuple[dict | None, str]:
    """Validate a stream access key and return (stream_info, error_message).

    Publishing (require_publish=True): only the private key (live_xxx) counts.

    Reading: the request must be passed; the decision is _stream_read_access
    (owner, admin, member for a public stream, or the open share link). Without a
    request there is nothing to judge and the answer is "not found".

    Args:
        key: The stream key (private or public) from the URL
        require_publish: If True, requires private stream key for publishing
        request: The request, for the read decision

    Returns:
        Tuple of (stream_dict or None, error_message or empty string)
    """
    if not key:
        return None, "Stream key required"

    if not require_publish:
        return await _stream_read_access(request, key)

    # Publishing needs the private key (live_xxx)
    if key.startswith("pub_"):
        return None, "Public key cannot be used for publishing"
    if not key.startswith("live_"):
        key = f"live_{key}"

    stream = await db.get_stream_by_key(key)
    if not stream:
        return None, "Invalid stream key"

    return stream, ""


def _stream_not_found() -> web.Response:
    """The one answer for every playback request that is refused or names nothing."""
    return web.json_response({"error": _STREAM_NOT_FOUND}, status=404,
                             headers={"Cache-Control": "no-store"})


def _playback_headers(stream: dict, cache_control: str = "no-cache", extra: Optional[dict] = None) -> dict:
    """Headers of a playback answer. Only an open share link (public stream with
    allow_unauthenticated) may be read from other sites, so only it carries
    Access-Control-Allow-Origin and may be kept by a shared cache; anything else
    is same-origin and private to the viewer."""
    headers = dict(extra or {})
    if _stream_is_open(stream):
        headers["Access-Control-Allow-Origin"] = "*"
        headers["Cache-Control"] = cache_control if cache_control == "no-cache" else "public, " + cache_control
    else:
        headers["Cache-Control"] = "private, " + cache_control
    return headers


# What MediaMTX's HLS muxer serves under a path: playlists, init and media segments, parts.
_HLS_FILE_RE = re.compile(r"[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}\.(?:m3u8|mp4|m4s|ts|aac|m4a)\Z")


async def http_stream_hls_proxy(request: web.Request) -> web.Response:
    """Proxy HLS requests to MediaMTX through port 443.

    Route: /api/stream/{key}/hls/{path:.*}

    Accepts either:
    - Public key (pub_xxx): Read-only access for viewers
    - Private key (live_xxx): Full access for stream owner

    Allows viewing streams via HLS through the portal, keeping MediaMTX
    bound to localhost.
    """
    key = request.match_info.get("stream_key", "")
    hls_path = request.match_info.get("path", "index.m3u8")

    # Authorise first: nothing about the stream (not even that MediaMTX is
    # missing) is revealed to somebody who may not watch it.
    stream, error = await _validate_stream_access(key, request=request)
    if error:
        return _stream_not_found()
    # Only a plain file name of the stream's own HLS output is forwarded: no folders, no
    # dot segments, no encoded forms (the router decoded the path once already, so a
    # leftover % was encoded twice). Anything else answers like a refusal.
    if not _HLS_FILE_RE.match(hls_path) or ".." in hls_path:
        return _stream_not_found()

    # Get MediaMTX configuration
    mtx_config = await _get_mediamtx_config()
    if not mtx_config:
        return web.json_response({"error": "MediaMTX not configured"}, status=503)

    hls_port = mtx_config.get("hls_port", 8888)

    # MediaMTX uses the private stream_key for paths (not public_key)
    # When publishing via rtmp_ token, MediaMTX path is the token, not the live_ key
    async with _stream_state_lock:
        private_key = _rtmp_stream_paths.get(stream["id"], stream["stream_key"])
    # MediaMTX path includes the RTMP app name "live"
    mtx_path = f"live/{private_key}"
    url = f"https://127.0.0.1:{hls_port}/{mtx_path}/{hls_path}"
    # Forward the query string: MediaMTX (v1.1x+) tags every variant playlist and
    # segment URL with ?session=<secret> and answers 401 without it.
    # A ?token= is the viewer's own credential, not MediaMTX's: it is not passed on.
    upstream_query = request.query_string
    if "token" in request.query:
        upstream_query = urlencode([(k, v) for k, v in parse_qsl(upstream_query, keep_blank_values=True)
                                    if k != "token"])
    if upstream_query:
        url += f"?{upstream_query}"

    try:
        # Create SSL context that allows self-signed certs (internal communication)
        import ssl
        ssl_ctx = ssl.create_default_context()
        ssl_ctx.check_hostname = False
        ssl_ctx.verify_mode = ssl.CERT_NONE

        connector = aiohttp.TCPConnector(ssl=ssl_ctx)
        async with aiohttp.ClientSession(connector=connector) as session:
            async with session.get(url, timeout=aiohttp.ClientTimeout(total=10)) as resp:
                content = await resp.read()

                # Rewrite URLs in m3u8 files to go through our proxy
                content_type = resp.content_type or "application/octet-stream"
                if content_type.startswith("application/vnd.apple.mpegurl") or hls_path.endswith(".m3u8"):
                    text = content.decode("utf-8")
                    # Rewrite segment URLs to go through our proxy
                    # Use the same key type that was used to access (preserves public/private key)
                    text = text.replace(f"/{mtx_path}/", f"/api/stream/{key}/hls/")
                    content = text.encode("utf-8")

                return web.Response(
                    body=content,
                    status=resp.status,
                    content_type=content_type,
                    headers=_playback_headers(stream)
                )
    except asyncio.TimeoutError:
        return web.json_response({"error": "Stream timeout"}, status=504)
    except Exception as e:
        logger.error(f"HLS proxy error: {e}")
        return web.json_response({"error": "Stream unavailable"}, status=502)


# Cache for stream thumbnails (key -> (timestamp, image_bytes))
_thumbnail_cache: dict[str, tuple[float, bytes]] = {}
_THUMBNAIL_CACHE_TTL = 15  # seconds
_THUMBNAIL_STALE_MAX = 300  # seconds; an older last frame is never served in place of a fresh one
_THUMBNAIL_TIMEOUT = 10  # seconds a capture may take before ffmpeg is killed
_THUMBNAIL_MAX_CAPTURES = 2  # ffmpeg thumbnail processes running at once
_THUMBNAIL_RETRY_AFTER = 3  # seconds, sent with the 503 when all slots are busy
_thumbnail_sem = asyncio.Semaphore(_THUMBNAIL_MAX_CAPTURES)
# One capture per stream at a time: cache_key -> task whose result every waiting
# request shares (single-flight).
_thumbnail_inflight: dict[str, "asyncio.Task"] = {}


_OPEN_THUMBNAIL_MAX_AGE = 5      # seconds a shared cache may keep an open-link thumbnail


def _thumbnail_response(body: bytes, max_age: int, stream: dict) -> web.Response:
    if _stream_is_open(stream):
        max_age = min(max_age, _OPEN_THUMBNAIL_MAX_AGE)
    return web.Response(
        body=body,
        content_type="image/jpeg",
        headers=_playback_headers(stream, f"max-age={max_age}")
    )


def _stale_thumbnail_response(cache_key: str, stream: dict) -> Optional[web.Response]:
    """The last good frame for a stream if it is at most _THUMBNAIL_STALE_MAX seconds old
    (served when a fresh one cannot be made). An older frame is dropped, not served."""
    cached = _thumbnail_cache.get(cache_key)
    if cached is None:
        return None
    if time() - cached[0] > _THUMBNAIL_STALE_MAX:
        _thumbnail_cache.pop(cache_key, None)
        return None
    return _thumbnail_response(cached[1], 5, stream)


async def _run_thumbnail_ffmpeg(hls_url: str) -> tuple[Optional[int], bytes, bytes]:
    """Run one ffmpeg frame grab. On timeout, error or cancellation the process is
    killed and reaped before this returns, so none is left running or as a zombie."""
    # -i: input URL; -vframes 1: one frame; -f image2 / -vcodec mjpeg: JPEG;
    # -q:v 3: quality (2-5 is good, lower is better); scale to 640px wide;
    # pipe:1: output to stdout
    proc = await _media_exec(
        ["ffmpeg",
         "-y",  # Overwrite without asking
         "-i", hls_url,
         "-vframes", "1",
         "-f", "image2",
         "-vcodec", "mjpeg",
         "-q:v", "3",
         "-vf", "scale=640:-1",  # Scale to 640px width, maintain aspect ratio
         "pipe:1"],
        "idle",
        stdout=asyncio.subprocess.PIPE,
        stderr=asyncio.subprocess.PIPE,
        env={**os.environ, "AV_LOG_FORCE_NOCOLOR": "1"}
    )
    try:
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=_THUMBNAIL_TIMEOUT)
        return proc.returncode, stdout, stderr
    finally:
        if proc.returncode is None:
            try:
                proc.kill()
            except ProcessLookupError:
                pass
            try:
                await asyncio.wait_for(proc.wait(), timeout=5)
            except Exception as e:
                logger.warning(f"ffmpeg thumbnail process did not exit after kill: {e}")


async def _capture_thumbnail(cache_key: str, stream_id: int, stream_key: str) -> tuple[str, Optional[bytes]]:
    """Capture one thumbnail and cache it. Runs as the shared task of the single-flight
    registry and owns one slot of _thumbnail_sem (taken by the caller). Never raises;
    returns (outcome, jpeg): outcome is "ok", "noconfig", "timeout" or "failed"."""
    try:
        mtx_config = await _get_mediamtx_config()
        if not mtx_config:
            return "noconfig", None
        hls_port = mtx_config.get("hls_port", 8888)
        # When publishing via rtmp_ token, MediaMTX path is the token, not the live_ key
        async with _stream_state_lock:
            private_key = _rtmp_stream_paths.get(stream_id, stream_key)
        hls_url = f"https://127.0.0.1:{hls_port}/live/{private_key}/index.m3u8"
        returncode, stdout, stderr = await _run_thumbnail_ffmpeg(hls_url)
        if returncode != 0 or not stdout:
            logger.warning(f"ffmpeg thumbnail capture failed for {cache_key}: {stderr.decode(errors='replace')[:200]}")
            return "failed", None
        now = time()
        _thumbnail_cache[cache_key] = (now, stdout)
        # Drop frames too old to serve even as the stale fallback (pruning at the
        # fresh-frame TTL would leave the fallback nothing to serve)
        for k in list(_thumbnail_cache.keys()):
            if now - _thumbnail_cache[k][0] > _THUMBNAIL_STALE_MAX:
                del _thumbnail_cache[k]
        return "ok", stdout
    except asyncio.TimeoutError:
        logger.warning(f"ffmpeg thumbnail capture timed out for {cache_key}")
        return "timeout", None
    except Exception as e:
        logger.error(f"Thumbnail capture error: {e}")
        return "failed", None
    finally:
        _thumbnail_inflight.pop(cache_key, None)
        _thumbnail_sem.release()


async def http_stream_thumbnail(request: web.Request) -> web.Response:
    """Generate a live thumbnail from an active stream.

    Route: GET /api/stream/{key}/thumbnail

    Captures a frame from the HLS stream using ffmpeg.
    Thumbnails are cached for 15 seconds to reduce load; a frame up to 5 minutes old
    is still served when a fresh one cannot be made. Requests for a stream
    whose frame is being captured wait for that one capture instead of starting
    another. At most two captures run at once; beyond that the last good frame is
    served, or 503 with Retry-After if there is none. A capture that failed or
    timed out answers the same way (503 with Retry-After, never 500 or 504).
    """
    key = request.match_info.get("stream_key", "")

    # Authorise before anything else, so an offline answer cannot reveal a
    # private stream either
    stream, error = await _validate_stream_access(key, request=request)
    if error:
        return _stream_not_found()

    # Check if stream is live (only generate dynamic thumbnail for active broadcast)
    if stream.get("is_live") != 1:
        # Return static thumbnail if available, or 404
        if stream.get("thumbnail_url"):
            raise web.HTTPFound(stream["thumbnail_url"])
        return web.json_response({"error": "Stream is offline"}, status=404)

    # Check cache
    cache_key = stream["stream_key"]
    cached = _thumbnail_cache.get(cache_key)
    if cached and time() - cached[0] < _THUMBNAIL_CACHE_TTL:
        return _thumbnail_response(cached[1], _THUMBNAIL_CACHE_TTL, stream)

    # Single-flight. Nothing below may await between the in-flight lookup and the
    # registration of the new task, or concurrent requests would each start one.
    task = _thumbnail_inflight.get(cache_key)
    if task is None:
        if _thumbnail_sem.locked():
            stale = _stale_thumbnail_response(cache_key, stream)
            if stale is not None:
                return stale
            return web.json_response(
                {"error": "Thumbnail capacity reached, try again shortly"},
                status=503, headers={"Retry-After": str(_THUMBNAIL_RETRY_AFTER)})
        # Not locked, so this takes a slot without suspending; the task releases it.
        await _thumbnail_sem.acquire()
        task = asyncio.ensure_future(_capture_thumbnail(cache_key, stream["id"], stream["stream_key"]))
        _thumbnail_inflight[cache_key] = task

    # shield: a client that goes away must not cancel the capture others wait for
    outcome, data = await asyncio.shield(task)
    if outcome == "ok":
        return _thumbnail_response(data, _THUMBNAIL_CACHE_TTL, stream)
    if outcome == "noconfig":
        return web.json_response({"error": "MediaMTX not configured"}, status=503,
                                 headers={"Retry-After": str(_THUMBNAIL_RETRY_AFTER)})
    # Serve last known good frame rather than an error during transient HLS hiccups
    stale = _stale_thumbnail_response(cache_key, stream)
    if stale is not None:
        return stale
    # No frame can be made now (failed or timed out): a temporary condition, so
    # 503 with Retry-After in every case, never 500 or 504.
    error = "Thumbnail capture timeout" if outcome == "timeout" else "Failed to capture thumbnail"
    return web.json_response({"error": error}, status=503,
                             headers={"Retry-After": str(_THUMBNAIL_RETRY_AFTER)})


# Server-side record of WebRTC sessions opened through the WHIP/WHEP proxies:
# session_id -> (kind "whip"|"whep", stream_id, MediaMTX path, created time).
# The session proxy decides how to route and what to authorise from this record,
# never from anything the client puts in the URL. In-memory only: after a portal
# restart, sessions opened earlier are unknown and are refused (MediaMTX expires
# them on its own).
_webrtc_sessions: dict[str, tuple[str, int, str, float]] = {}
_WEBRTC_SESSION_MAX = 4096
_WEBRTC_SESSION_TTL = 7 * 24 * 3600
# Per stream and kind. Playback sessions need only a playback key and no login,
# so a viewer must not be able to push a publisher's record out of the table:
# viewers are capped per stream, and under global pressure playback records go
# before publishing records.
_WEBRTC_SESSION_MAX_PER_STREAM = {"whep": 64, "whip": 16}


def _webrtc_session_remember(session_id: str, kind: str, stream_id: int, mtx_path: str) -> None:
    """Record a session opened via the proxy; prune expired and excess entries."""
    if not session_id:
        return
    now = monotonic()
    for sid in [k for k, v in _webrtc_sessions.items() if now - v[3] > _WEBRTC_SESSION_TTL]:
        del _webrtc_sessions[sid]
    # Per-stream cap: drop that stream's oldest records of the same kind
    same = [k for k, v in _webrtc_sessions.items() if v[0] == kind and v[1] == stream_id and k != session_id]
    for sid in same[:max(0, len(same) - _WEBRTC_SESSION_MAX_PER_STREAM.get(kind, 16) + 1)]:
        del _webrtc_sessions[sid]
    # Global cap: oldest playback record first, a publishing record only if none is left
    while len(_webrtc_sessions) >= _WEBRTC_SESSION_MAX and session_id not in _webrtc_sessions:
        victim = next((k for k, v in _webrtc_sessions.items() if v[0] == "whep"), None)
        if victim is None:
            victim = next(iter(_webrtc_sessions))
        del _webrtc_sessions[victim]
    _webrtc_sessions[session_id] = (kind, stream_id, mtx_path, now)


async def _authorize_webrtc_session(request: web.Request, key: str, session_id: str
                                    ) -> tuple[tuple | None, str, int, Optional[dict]]:
    """Authorise a PATCH/DELETE on a WebRTC session.

    Returns (record, error, http_status, stream). A playback (WHEP) session needs
    the same permission as starting one (_stream_read_access); a publishing
    (WHIP) session needs the publish key, so a playback key cannot alter or end a
    publisher's session. Every refusal is the same 404.
    """
    rec = _webrtc_sessions.get(session_id)
    if rec and rec[0] == "whip":
        # Same answer as for an unknown session: a playback key must not be
        # able to tell which session id is the publisher's.
        stream, perr = await _validate_stream_access(key, require_publish=True)
        if perr or stream["id"] != rec[1]:
            return None, _STREAM_NOT_FOUND, 404, None
        return rec, "", 200, stream
    stream, error = await _validate_stream_access(key, request=request)
    if error or not rec or rec[1] != stream["id"]:
        return None, _STREAM_NOT_FOUND, 404, None
    return rec, "", 200, stream


def _whep_headers(stream: dict, location: str) -> dict:
    headers = _playback_headers(stream)
    headers["Location"] = location
    if "Access-Control-Allow-Origin" in headers:
        headers["Access-Control-Expose-Headers"] = "Location"
    return headers


async def http_stream_webrtc_whep(request: web.Request) -> web.Response:
    """WebRTC WHEP endpoint for playback through port 443.

    Route: POST /api/stream/{key}/webrtc/whep

    The key in the URL names the stream (pub_xxx, or live_xxx for its owner's
    own pages); who may watch is decided by _stream_read_access. Proxies WebRTC offers to MediaMTX and returns the answer.
    """
    key = request.match_info.get("stream_key", "")

    # Authorise first (see _stream_read_access)
    stream, error = await _validate_stream_access(key, request=request)
    if error:
        return _stream_not_found()

    # Get MediaMTX configuration
    mtx_config = await _get_mediamtx_config()
    if not mtx_config:
        return web.json_response({"error": "MediaMTX not configured"}, status=503)

    webrtc_port = mtx_config.get("webrtc_port", 8889)

    # Get SDP offer from request
    sdp_offer = await request.text()
    if not sdp_offer:
        return web.json_response({"error": "SDP offer required"}, status=400)

    # MediaMTX uses private stream_key for paths
    private_key = stream["stream_key"]
    # WebRTC uses plain HTTP internally (localhost only) - DTLS-SRTP handles media encryption
    url = f"http://127.0.0.1:{webrtc_port}/{private_key}/whep"

    try:
        async with aiohttp.ClientSession() as session:
            async with session.post(
                url,
                data=sdp_offer,
                headers={"Content-Type": "application/sdp"},
                timeout=aiohttp.ClientTimeout(total=10)
            ) as resp:
                sdp_answer = await resp.text()

                if resp.status == 201:
                    # Rewrite Location header to go through our proxy
                    location = resp.headers.get("Location", "")
                    if location:
                        # Extract session ID from location
                        session_id = location.split("/")[-1]
                        _webrtc_session_remember(session_id, "whep", stream["id"], private_key)
                        # Use the same key type that was used to access
                        location = f"/api/stream/{key}/webrtc/session/{session_id}"

                    return web.Response(
                        text=sdp_answer,
                        status=201,
                        content_type="application/sdp",
                        headers=_whep_headers(stream, location)
                    )
                else:
                    return web.Response(
                        text=sdp_answer,
                        status=resp.status,
                        content_type=resp.content_type
                    )
    except asyncio.TimeoutError:
        return web.json_response({"error": "Connection timeout"}, status=504)
    except Exception as e:
        logger.error(f"WHEP proxy error: {e}")
        return web.json_response({"error": "WebRTC unavailable"}, status=502)


async def http_stream_webrtc_whip(request: web.Request) -> web.Response:
    """WebRTC WHIP endpoint for publishing through port 443.

    Route: POST /api/stream/{stream_key}/webrtc/whip

    Allows OBS and other tools to publish streams via WebRTC through the portal.
    """
    stream_key = request.match_info.get("stream_key", "")

    # Validate stream key for publishing
    stream, error = await _validate_stream_access(stream_key, require_publish=True)
    if error:
        return web.json_response({"error": error}, status=403)

    # Get MediaMTX configuration
    mtx_config = await _get_mediamtx_config()
    if not mtx_config:
        return web.json_response({"error": "MediaMTX not configured"}, status=503)

    webrtc_port = mtx_config.get("webrtc_port", 8889)

    # Get SDP offer from request
    sdp_offer = await request.text()
    if not sdp_offer:
        return web.json_response({"error": "SDP offer required"}, status=400)

    # The stream path in MediaMTX is the stream key
    full_stream_key = stream_key if stream_key.startswith("live_") else f"live_{stream_key}"
    # WebRTC uses plain HTTP internally (localhost only) - DTLS-SRTP handles media encryption
    url = f"http://127.0.0.1:{webrtc_port}/{full_stream_key}/whip"

    try:
        async with aiohttp.ClientSession() as session:
            async with session.post(
                url,
                data=sdp_offer,
                headers={"Content-Type": "application/sdp"},
                timeout=aiohttp.ClientTimeout(total=10)
            ) as resp:
                sdp_answer = await resp.text()

                if resp.status == 201:
                    # Mark stream as live
                    await db.set_stream_live(stream["id"], True)
                    logger.info(f"Stream {stream['name']} started via WHIP")

                    # Rewrite Location header
                    location = resp.headers.get("Location", "")
                    if location:
                        session_id = location.split("/")[-1]
                        _webrtc_session_remember(session_id, "whip", stream["id"], full_stream_key)
                        location = f"/api/stream/{stream_key}/webrtc/session/{session_id}"

                    return web.Response(
                        text=sdp_answer,
                        status=201,
                        content_type="application/sdp",
                        headers={
                            "Location": location,
                            "Access-Control-Allow-Origin": "*",
                            "Access-Control-Expose-Headers": "Location",
                        }
                    )
                else:
                    return web.Response(
                        text=sdp_answer,
                        status=resp.status,
                        content_type=resp.content_type
                    )
    except asyncio.TimeoutError:
        return web.json_response({"error": "Connection timeout"}, status=504)
    except Exception as e:
        logger.error(f"WHIP proxy error: {e}")
        return web.json_response({"error": "WebRTC unavailable"}, status=502)


async def http_stream_webrtc_session(request: web.Request) -> web.Response:
    """Proxy WebRTC session management (ICE candidates, etc.).

    Route: PATCH/DELETE /api/stream/{stream_key}/webrtc/session/{session_id}

    The session is routed to MediaMTX's whip or whep endpoint according to how
    it was opened, and a publishing session requires the publish key.
    """
    stream_key = request.match_info.get("stream_key", "")
    session_id = request.match_info.get("session_id", "")

    # Authorise against the session's recorded type before anything else
    rec, error, status, stream = await _authorize_webrtc_session(request, stream_key, session_id)
    if error:
        return _stream_not_found() if status == 404 else web.json_response({"error": error}, status=status)
    kind, _stream_id, mtx_path, _created = rec

    # Get MediaMTX configuration
    mtx_config = await _get_mediamtx_config()
    if not mtx_config:
        return web.json_response({"error": "MediaMTX not configured"}, status=503)

    webrtc_port = mtx_config.get("webrtc_port", 8889)

    method = request.method
    # WebRTC uses plain HTTP internally (localhost only)
    url = f"http://127.0.0.1:{webrtc_port}/{mtx_path}/{kind}/{session_id}"

    try:
        body = await request.read()
        headers = {"Content-Type": request.content_type} if request.content_type else {}

        async with aiohttp.ClientSession() as session:
            async with session.request(
                method,
                url,
                data=body,
                headers=headers,
                timeout=aiohttp.ClientTimeout(total=10)
            ) as resp:
                content = await resp.read()
                if method == "DELETE" and resp.status < 300:
                    _webrtc_sessions.pop(session_id, None)
                return web.Response(
                    body=content,
                    status=resp.status,
                    content_type=resp.content_type,
                    # A publishing session keeps its open header (its credential is the
                    # publish key); a playback one only on an open share link.
                    headers={"Access-Control-Allow-Origin": "*"} if kind == "whip"
                    else _playback_headers(stream)
                )
    except Exception as e:
        logger.error(f"WebRTC session proxy error: {e}")
        return web.json_response({"error": "Session error"}, status=502)


async def http_stream_info(request: web.Request) -> web.Response:
    """Get stream information and playback URLs.

    Route: GET /api/stream/{stream_key}/info
    """
    stream_key = request.match_info.get("stream_key", "")

    # Authorise first (see _stream_read_access)
    stream, error = await _validate_stream_access(stream_key, request=request)
    if error:
        return _stream_not_found()

    # Base URL for the portal
    host = request.headers.get("Host", Config.HOSTNAME)
    base_url = f"https://{host}"

    # Use public key for playback URLs, never expose the private stream_key
    public_key = stream.get("public_key", "")
    if public_key and public_key.startswith("pub_"):
        public_key = public_key[4:]

    # webrtc_whep is signaling only: WebRTC media does not pass through this
    # proxy, so it works only where the client can reach MediaMTX's WebRTC
    # port directly. HLS is the playback URL that works everywhere.
    return web.json_response({
        "public_key": public_key,
        "name": stream.get("name", ""),
        "is_live": stream.get("is_live", 0),
        "is_public": stream.get("is_public", False),
        "playback": {
            "hls": f"{base_url}/api/stream/{public_key}/hls/index.m3u8",
            "webrtc_whep": f"{base_url}/api/stream/{public_key}/webrtc/whep"
        }
    }, headers=_playback_headers(stream))


