async def http_shodan_lookup(request: web.Request) -> web.Response:
    """Look up an IP address in Shodan (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    ip = request.match_info.get("ip")
    if not ip:
        return web.json_response({"error": "IP address required"}, status=400)

    # Validate IP format
    import ipaddress as _ipaddress
    try:
        _ipaddress.ip_address(ip)
    except ValueError:
        return web.json_response({"error": "Invalid IP address format"}, status=400)

    if not Config.SHODAN_API_KEY and not shodan_client.api_key:
        return web.json_response({"error": "Shodan API key not configured"}, status=503)

    result = await shodan_client.lookup_host(ip)
    if result:
        return web.json_response(result.to_dict())
    else:
        return web.json_response({"error": "No data found for IP", "ip": ip}, status=404)


async def http_shodan_search(request: web.Request) -> web.Response:
    """Search Shodan (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    if not Config.SHODAN_API_KEY and not shodan_client.api_key:
        return web.json_response({"error": "Shodan API key not configured"}, status=503)

    query = request.query.get("query")
    if not query:
        return web.json_response({"error": "Query parameter required"}, status=400)

    try:
        limit = int(request.query.get("limit", "10"))
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid limit parameter"}, status=400)
    limit = min(max(limit, 1), 100)

    results = await shodan_client.search(query, limit)
    return web.json_response({"results": results})


async def http_shodan_api_info(request: web.Request) -> web.Response:
    """Get Shodan API info (credits remaining, etc.) - admin only."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    # Check both Config and the client (client may have been set at runtime)
    if not Config.SHODAN_API_KEY and not shodan_client.api_key:
        return web.json_response({
            "configured": False,
            "message": "Shodan API key not configured"
        })

    info = await shodan_client.get_api_info()
    if info:
        return web.json_response({
            "configured": True,
            "plan": info.get("plan", "unknown"),
            "query_credits": info.get("query_credits", 0),
            "scan_credits": info.get("scan_credits", 0)
        })
    else:
        return web.json_response({
            "configured": bool(Config.SHODAN_API_KEY or shodan_client.api_key),
            "error": "Failed to get API info"
        }, status=500)


async def http_shodan_set_api_key(request: web.Request) -> web.Response:
    """Set Shodan API key (admin only) - persists to database."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)

    api_key = data.get("api_key", "").strip()
    if not api_key:
        return web.json_response({"error": "API key required"}, status=400)

    # Set the API key in both the client and Config
    shodan_client.set_api_key(api_key)
    Config.SHODAN_API_KEY = api_key

    # Verify the key works before persisting
    info = await shodan_client.get_api_info()
    if info:
        # Persist to database (encrypted at rest) for survival across restarts
        await db.set_setting("shodan_api_key", encrypt_config(api_key))
        logger.info(f"Shodan API key updated and persisted by user {token.user_id}")
        return web.json_response({
            "status": "success",
            "plan": info.get("plan", "unknown"),
            "query_credits": info.get("query_credits", 0)
        })
    else:
        return web.json_response({"error": "Invalid API key"}, status=400)


# =============================================================================
# VOD Manager API
# =============================================================================


_vod_pin_lock = asyncio.Lock()


async def _vod_note_host_key(user_id: int, storage: dict, *, pin: Optional[str] = None,
                             refused: Optional[str] = None) -> bool:
    """Record a VOD storage host-key event in its config: pin a key (first use
    after an upgrade, only while no pin exists) or note the key that was refused.
    Returns True when something was written."""
    async with _vod_pin_lock:
        current = await db.get_vod_storage(user_id)
        if (not current or current["host"] != storage["host"]
                or (current["port"] or 22) != (storage["port"] or 22)):
            return False
        config = dict(current.get("config") or {})
        if pin:
            if hostkeys.normalize_fingerprint(config.get(hostkeys.FINGERPRINT_KEY)):
                return False        # someone pinned meanwhile; never overwrite here
            config[hostkeys.FINGERPRINT_KEY] = pin
            config.pop(hostkeys.REFUSED_KEY, None)
        elif refused:
            config[hostkeys.REFUSED_KEY] = {
                "fingerprint": refused, "at": datetime.now(timezone.utc).isoformat()}
        else:
            return False
        return await db.update_vod_storage_config(
            user_id, config, current["host"], current["port"])


async def _vod_activity(user_id: int, action: str, detail: str) -> None:
    user = await db.get_user_by_id(user_id)
    await db.log_activity(user_id, get_display_name(user) if user else "unknown", action, detail)


_VOD_HOST_KEY_ERROR = "Host key changed; review it in VOD storage settings"


async def _vod_dial(user_id: int, storage: dict, addrs: list):
    """Dial VOD storage on already policy-checked addresses and verify its host
    key. There is nobody to ask at upload time, so a first key is pinned
    automatically (and logged); a different key later is refused and logged.
    Returns (conn, sftp, None) or (None, None, error)."""
    config = storage.get("config") or {}
    connect_opts = {
        "host": addrs[0],   # replaced per attempt by connect_verified
        "port": storage["port"] or 22,
        "username": storage["username"],
    }

    if storage["auth_method"] == "key":
        key_content = config.get("private_key")
        if key_content:
            connect_opts["client_keys"] = [asyncssh.import_private_key(key_content)]
        else:
            return None, None, "No private key configured"
    elif storage["auth_method"] == "password":
        connect_opts["password"] = config.get("password", "")

    pinned, ignore = hostkeys.policy_for(config)
    try:
        conn, seen = await hostkeys.connect_verified(
            addrs, connect_opts, pinned=pinned, ignore=ignore, trust_unpinned=True, timeout=10)
    except hostkeys.HostKeyRefused as refused:
        logger.warning(
            f"VOD SFTP host key changed for user {user_id}: expected {refused.expected}, "
            f"server presented {refused.fingerprint}; upload/download refused")
        await _vod_note_host_key(user_id, storage, refused=refused.fingerprint)
        await _vod_activity(user_id, "vod_host_key_refused",
                            f"VOD storage host key changed (now {refused.fingerprint}); connection refused")
        return None, None, _VOD_HOST_KEY_ERROR
    except asyncio.TimeoutError:
        return None, None, "Connection timed out"
    except asyncssh.Error as e:
        logger.warning(f"VOD SFTP SSH error for user {user_id}: {e}")
        return None, None, "Connection failed"
    except OSError as e:
        logger.warning(f"VOD SFTP connection error for user {user_id}: {e}")
        return None, None, "Connection failed"

    if seen and not pinned and not ignore:
        if await _vod_note_host_key(user_id, storage, pin=seen):
            logger.info(f"VOD SFTP host key pinned on first use for user {user_id}: {seen}")
            await _vod_activity(user_id, "vod_host_key_pinned",
                                f"VOD storage host key pinned on first use ({seen})")
    try:
        sftp = await conn.start_sftp_client()
    except (asyncssh.Error, OSError) as e:
        conn.close()
        logger.warning(f"VOD SFTP session error for user {user_id}: {e}")
        return None, None, "Connection failed"
    return conn, sftp, None


async def _connect_vod_sftp(user_id: int):
    """Connect to user's VOD SFTP storage. Returns (conn, sftp, None) or (None, None, error)."""
    storage = await db.get_vod_storage(user_id)
    if not storage:
        return None, None, "No VOD storage configured"

    try:
        # Dial the checked addresses so a later DNS answer cannot differ.
        _addrs = await resolve_checked_host(storage["host"], storage["port"] or 22)
    except HostCheckError:
        logger.warning(f"VOD SFTP host refused by outbound host policy for user {user_id}")
        return None, None, "Host not allowed"
    return await _vod_dial(user_id, storage, _addrs)


async def http_get_vod_storage(request: web.Request) -> web.Response:
    """Get current user's VOD storage config (password/key redacted)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"storage": None})

    # Redact sensitive fields - strip config entirely, expose only flags
    config = storage.get("config") or {}
    redacted = dict(storage)
    del redacted["config"]
    redacted["has_password"] = bool(config.get("password"))
    redacted["has_key"] = bool(config.get("private_key"))
    # Host key: what is pinned, whether the check is off, and the last key refused
    pinned, ignore = hostkeys.policy_for(config)
    refused = config.get(hostkeys.REFUSED_KEY)
    redacted["host_key_fingerprint"] = pinned
    redacted["host_key_ignore"] = ignore
    redacted["host_key_refused"] = (
        {"fingerprint": refused.get("fingerprint"), "at": refused.get("at")}
        if isinstance(refused, dict) and hostkeys.valid_fingerprint(refused.get("fingerprint")) else None)

    return web.json_response({"storage": redacted})


async def http_save_vod_storage(request: web.Request) -> web.Response:
    """Create or update VOD storage config."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    host = data.get("host", "").strip()
    username = data.get("username", "").strip()
    remote_path = data.get("remote_path", "").strip()
    auth_method = data.get("auth_method", "password")

    if not host:
        return web.json_response({"error": "Host is required"}, status=400)
    if not username:
        return web.json_response({"error": "Username is required"}, status=400)
    if not remote_path:
        return web.json_response({"error": "Remote path is required"}, status=400)
    if auth_method not in ("password", "key"):
        return web.json_response({"error": "Invalid auth method"}, status=400)

    port = data.get("port", 22)
    try:
        port = int(port)
        if port < 1 or port > 65535:
            raise ValueError
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid port"}, status=400)

    # Refuse local/internal targets (a name that does not resolve yet may be
    # saved; connecting re-checks and fails closed)
    if not await _user_targets_allowed(host, None, port):
        return web.json_response({"error": "Host not allowed"}, status=403)

    # Build config JSON with sensitive data
    config = {}
    if auth_method == "password":
        password = data.get("password", "")
        # If password is "***", keep existing password
        if password == "***":
            existing = await db.get_vod_storage(token.user_id)
            if existing:
                # get_vod_storage already returns the decrypted config as a dict
                existing_config = existing.get("config") or {}
                password = existing_config.get("password", "")
        config["password"] = password
    elif auth_method == "key":
        private_key = data.get("private_key", "")
        # If key is "***", keep existing key
        if private_key == "***":
            existing = await db.get_vod_storage(token.user_id)
            if existing:
                # get_vod_storage already returns the decrypted config as a dict
                existing_config = existing.get("config") or {}
                private_key = existing_config.get("private_key", "")
        config["private_key"] = private_key

    # Host key: the pin survives an edit only while the target is unchanged
    # (a new host or port starts again); the opt-out is the owner's own setting.
    previous = await db.get_vod_storage(token.user_id)
    prev_config = (previous.get("config") or {}) if previous else {}
    if "host_key_ignore" in data and not isinstance(data["host_key_ignore"], bool):
        return web.json_response({"error": "Invalid host key setting"}, status=400)
    if previous and previous["host"] == host and (previous["port"] or 22) == port:
        kept = hostkeys.normalize_fingerprint(prev_config.get(hostkeys.FINGERPRINT_KEY))
        if kept:
            config[hostkeys.FINGERPRINT_KEY] = kept
        if isinstance(prev_config.get(hostkeys.REFUSED_KEY), dict):
            config[hostkeys.REFUSED_KEY] = prev_config[hostkeys.REFUSED_KEY]
    config[hostkeys.IGNORE_KEY] = data.get(
        "host_key_ignore", hostkeys.policy_for(prev_config)[1]) is True

    storage_id = await db.save_vod_storage(
        token.user_id,
        name=data.get("name", "My VOD Storage"),
        host=host,
        port=port,
        username=username,
        auth_method=auth_method,
        remote_path=remote_path,
        config=json.dumps(config),
    )

    return web.json_response({"id": storage_id, "message": "Storage config saved"})


async def http_delete_vod_storage(request: web.Request) -> web.Response:
    """Delete VOD storage config."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    deleted = await db.delete_vod_storage(token.user_id)
    if not deleted:
        return web.json_response({"error": "No storage config found"}, status=404)
    return web.json_response({"message": "Storage config deleted"})


async def _accepted_fingerprint(request: web.Request):
    """Read and validate the fingerprint an accept request names.
    Returns (fingerprint, None) or (None, error response)."""
    body, fp, err = await _read_accept_request(request)
    return fp, err


async def _read_accept_request(request: web.Request):
    """Read an accept request body. Returns (body, fingerprint, None) or
    (None, None, error response)."""
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return None, None, web.json_response({"error": "Invalid JSON"}, status=400)
    data = data if isinstance(data, dict) else {}
    fp = hostkeys.normalize_fingerprint(data.get("fingerprint"))
    if not fp:
        return None, None, web.json_response({"error": "A SHA256 host key fingerprint is required"}, status=400)
    return data, fp, None


def _stale_host_key(message: str) -> web.Response:
    return web.json_response({"error": message, "type": "host_key_stale"}, status=409)


def _user_connection_ssh_target(connection: dict) -> tuple:
    """(host, port) the SSH/SFTP code dials for a user connection."""
    return connection.get("host") or "", connection.get("port") or 22


def _service_ssh_target(service: dict) -> tuple:
    """(host, port) the ssh plugin dials for an admin-defined service (the
    config can override the service's own host and port, as in the plugin)."""
    config = service.get("config") if isinstance(service.get("config"), dict) else {}
    return (config.get("host", service.get("host")) or "",
            _coerce_port(config.get("port"), _coerce_port(service.get("port"), 22)))


def _service_target_changed(service: dict, updates: dict, new_config=None) -> bool:
    """True when an edit changes the host or port the ssh plugin dials: the
    columns in `updates` or the host/port inside the incoming `new_config`."""
    after = dict(service)
    for column in ("host", "port"):
        if column in updates:
            after[column] = updates[column]
    if isinstance(new_config, dict):
        after["config"] = new_config
    return _service_ssh_target(service) != _service_ssh_target(after)


def _coerce_port(value, default: int) -> int:
    """A TCP port as an int; `default` when the value is missing or not a valid port
    (a config saved through the form can hold the port as text or null)."""
    if isinstance(value, bool):
        return default
    try:
        port = int(str(value).strip()) if isinstance(value, (str, float)) else int(value)
    except (TypeError, ValueError):
        return default
    return port if 0 < port < 65536 else default


def _present_host_key(payload: dict, scope: str, ident, user_id: int, target: tuple) -> dict:
    """Add the target and a signed token to a host-key prompt for someone who
    may accept it, so the accept request can prove what was shown."""
    host, port = target
    payload["host"], payload["port"] = host, port
    payload["accept_token"] = hostkeys.HostKeyAcceptToken.issue(
        Config.JWT_SECRET, scope, ident, user_id, host, port, payload["fingerprint"])
    return payload


def _check_accepted_prompt(body: dict, fp: str, scope: str, ident, user_id: int, target: tuple):
    """Refuse (409) an accept for a prompt that no longer matches. Returns an
    error response, or None when the host, port and fingerprint the user saw are
    still the connection's and were presented by this portal to this user."""
    host, port = body.get("host"), body.get("port")
    if not isinstance(host, str) or isinstance(port, bool) or not isinstance(port, int):
        return web.json_response({"error": "host, port and fingerprint of the prompt are required"}, status=400)
    try:
        target_port = int(target[1])
    except (TypeError, ValueError):
        target_port = None
    if (host, port) != (target[0], target_port):
        return _stale_host_key("This connection now points at a different host or port; connect again to review its key")
    if not hostkeys.HostKeyAcceptToken.check(
            Config.JWT_SECRET, body.get("token"), scope, ident, user_id, host, port, fp):
        return _stale_host_key("The fingerprint does not match the one presented, or the prompt expired; connect again")
    return None


async def http_accept_vod_host_key(request: web.Request) -> web.Response:
    """POST /api/vods/storage/host-key/accept - pin (or replace) the VOD storage
    host key. The storage belongs to the signed-in user alone. The fingerprint
    must be the refused one the settings page showed; anything else is a 409."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not has_full_user_scope(token):
        return full_scope_required_response()
    fp, err = await _accepted_fingerprint(request)
    if err:
        return err
    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"error": "No VOD storage configured"}, status=404)
    async with _vod_pin_lock:
        storage = await db.get_vod_storage(token.user_id) or storage   # a transfer may have refused a key meanwhile
        config = dict(storage.get("config") or {})
        # Only the key the owner was shown (the last one a transfer refused).
        refused = config.get(hostkeys.REFUSED_KEY)
        shown = hostkeys.normalize_fingerprint(refused.get("fingerprint")) if isinstance(refused, dict) else None
        if not shown or shown != fp:
            return _stale_host_key("That is not the key the storage last presented; reload the VOD storage settings")
        config[hostkeys.FINGERPRINT_KEY] = fp
        config.pop(hostkeys.REFUSED_KEY, None)
        if not await db.update_vod_storage_config(token.user_id, config, storage["host"], storage["port"]):
            return web.json_response({"error": "Storage changed; try again"}, status=409)
    logger.info(f"VOD storage host key accepted by user {token.user_id}: {fp}")
    await _vod_activity(token.user_id, "vod_host_key_accepted", f"VOD storage host key accepted ({fp})")
    await security_event("host_key_accepted", request=request, user_id=token.user_id,
                         username=await _username_of(token.user_id),
                         details={"kind": "vod_storage", "fingerprint": fp})
    return web.json_response({"status": "accepted", "fingerprint": fp})


async def http_test_vod_storage(request: web.Request) -> web.Response:
    """Test SFTP connection with provided or saved credentials."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    host = data.get("host", "").strip()
    username = data.get("username", "").strip()
    remote_path = data.get("remote_path", "").strip()
    auth_method = data.get("auth_method", "password")
    try:
        port = int(data.get("port", 22))
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid port"}, status=400)

    if not host or not username:
        return web.json_response({"error": "Host and username are required"}, status=400)

    try:
        _addrs = await resolve_checked_host(host, port)
    except HostBlockedError:
        return web.json_response({"success": False, "error": "Host not allowed"})
    except HostResolveError:
        return web.json_response({"success": False, "error": "Connection failed"})

    connect_opts = {
        # Dial the checked address so a later DNS answer cannot differ.
        "host": _addrs[0],   # replaced per attempt by connect_verified below
        "port": port,
        "username": username,
    }

    # Host key: the saved pin applies while the target is unchanged; otherwise
    # this is a first look at the host (nothing is pinned by a test).
    saved = await db.get_vod_storage(token.user_id)
    pinned = None
    if saved and saved["host"] == host and (saved["port"] or 22) == port:
        pinned = hostkeys.policy_for(saved.get("config"))[0]
    ignore = data.get("host_key_ignore") is True

    # Resolve credentials (may need to fetch existing if "***")
    if auth_method == "key":
        private_key = data.get("private_key", "")
        if private_key == "***":
            existing = await db.get_vod_storage(token.user_id)
            if existing:
                # get_vod_storage already returns the decrypted config as a dict
                existing_config = existing.get("config") or {}
                private_key = existing_config.get("private_key", "")
        if private_key:
            try:
                connect_opts["client_keys"] = [asyncssh.import_private_key(private_key)]
            except asyncssh.KeyImportError as e:
                logger.warning(f"VOD storage private key import error: {e}")
                return web.json_response({"success": False, "error": "Invalid private key format"})
    else:
        password = data.get("password", "")
        if password == "***":
            existing = await db.get_vod_storage(token.user_id)
            if existing:
                # get_vod_storage already returns the decrypted config as a dict
                existing_config = existing.get("config") or {}
                password = existing_config.get("password", "")
        connect_opts["password"] = password

    conn = None
    try:
        conn, seen = await hostkeys.connect_verified(
            _addrs, connect_opts, pinned=pinned, ignore=ignore, trust_unpinned=True, timeout=10)
        sftp = await conn.start_sftp_client()
        key_note = ""
        if seen and not pinned:
            key_note = f" Host key {seen} will be pinned on first upload."

        # Try to list the remote path
        if remote_path:
            files = await sftp.listdir(remote_path)
            mkv_count = sum(1 for f in files if f.lower().endswith(".mkv"))
            return web.json_response({
                "success": True,
                "message": f"Connected successfully. Found {mkv_count} MKV file(s) in {remote_path}.{key_note}"
            })
        else:
            return web.json_response({"success": True, "message": f"Connected successfully.{key_note}"})

    except hostkeys.HostKeyRefused as refused:
        return web.json_response({
            "success": False,
            "error": f"Host key changed: the server now presents {refused.fingerprint}, "
                     f"but {refused.expected} is pinned.",
        })
    except asyncio.TimeoutError:
        return web.json_response({"success": False, "error": "Connection timed out"})
    except asyncssh.Error as e:
        logger.warning(f"VOD storage test SSH error for user {token.user_id}: {e}")
        return web.json_response({"success": False, "error": "SSH connection failed"})
    except OSError as e:
        logger.warning(f"VOD storage test connection error for user {token.user_id}: {e}")
        return web.json_response({"success": False, "error": "Connection failed"})
    finally:
        if conn:
            conn.close()


async def http_list_vods(request: web.Request) -> web.Response:
    """List MKV files on user's remote SFTP storage (recursive).

    Returns files with paths relative to the VOD root, e.g.
    "StreamName/2026-02-08_12-00-00/chunk_000.mkv" or "old_recording.mkv".
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"error": "No VOD storage configured"}, status=404)

    conn, sftp, error = await _connect_vod_sftp(token.user_id)
    if error:
        return web.json_response({"error": error}, status=502)

    try:
        remote_root = storage["remote_path"].rstrip("/")
        files = []

        async def scan_dir(dir_path: str, rel_prefix: str):
            try:
                entries = await sftp.listdir(dir_path)
            except (asyncssh.SFTPError, OSError):
                return
            for name in entries:
                if name.startswith("."):
                    continue
                full_path = f"{dir_path}/{name}"
                rel_path = f"{rel_prefix}/{name}" if rel_prefix else name
                try:
                    attrs = await sftp.stat(full_path)
                except (asyncssh.SFTPError, OSError):
                    continue
                if attrs.permissions is not None and (attrs.permissions & 0o40000):
                    # Directory — recurse
                    await scan_dir(full_path, rel_path)
                elif name.lower().endswith(".mkv"):
                    files.append({
                        "name": rel_path,
                        "size": attrs.size or 0,
                        "modified": attrs.mtime or 0,
                    })

        await scan_dir(remote_root, "")

        # Sort
        sort_by = request.query.get("sort", "modified")
        reverse = request.query.get("order", "desc") == "desc"
        if sort_by == "name":
            files.sort(key=lambda f: f["name"].lower(), reverse=reverse)
        elif sort_by == "size":
            files.sort(key=lambda f: f["size"], reverse=reverse)
        else:
            files.sort(key=lambda f: f["modified"], reverse=reverse)

        return web.json_response({"files": files, "path": remote_root})
    except asyncssh.SFTPError as e:
        logger.error(f"VOD list SFTP error for user {token.user_id}: {e}")
        return web.json_response({"error": "SFTP operation failed"}, status=502)
    except OSError as e:
        logger.error(f"VOD list connection error for user {token.user_id}: {e}")
        return web.json_response({"error": "Connection failed"}, status=502)
    finally:
        conn.close()


async def http_download_vod(request: web.Request) -> web.Response:
    """Stream-download a VOD file from remote SFTP storage.

    Supports subdirectory paths like "StreamName/session/chunk_000.mkv".
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    filename = request.match_info.get("filename", "")

    # Security: prevent path traversal
    if not filename or ".." in filename or filename.startswith("/"):
        return web.json_response({"error": "Invalid filename"}, status=400)
    if not filename.lower().endswith(".mkv"):
        return web.json_response({"error": "Only MKV files can be downloaded"}, status=400)

    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"error": "No VOD storage configured"}, status=404)

    conn, sftp, error = await _connect_vod_sftp(token.user_id)
    if error:
        return web.json_response({"error": error}, status=502)

    response_started = False
    try:
        remote_path = f"{storage['remote_path'].rstrip('/')}/{filename}"
        attrs = await sftp.stat(remote_path)

        response = web.StreamResponse()
        response.content_type = "video/x-matroska"
        response.content_length = attrs.size
        safe_name = filename.split("/")[-1].replace('"', '\\"')
        response.headers["Content-Disposition"] = f'attachment; filename="{safe_name}"'
        await response.prepare(request)
        response_started = True

        CHUNK_SIZE = 262144  # 256 KB
        async with sftp.open(remote_path, "rb") as f:
            while True:
                chunk = await f.read(CHUNK_SIZE)
                if not chunk:
                    break
                await response.write(chunk)

        await response.write_eof()
        return response
    except asyncssh.SFTPError as e:
        logger.error(f"VOD download SFTP error for user {token.user_id}: {e}")
        if response_started:
            return response  # Headers already sent, can't send error JSON
        return web.json_response({"error": "SFTP operation failed"}, status=502)
    except OSError as e:
        logger.error(f"VOD download error for user {token.user_id}: {e}")
        if response_started:
            return response
        return web.json_response({"error": "Download failed"}, status=502)
    finally:
        conn.close()


async def http_download_vod_archive(request: web.Request) -> web.Response:
    """Download multiple VOD files as a zip archive streamed from SFTP.

    POST body: {"files": ["StreamName/session/chunk_000.mkv", ...]}
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    files = data.get("files", [])
    if not files or not isinstance(files, list):
        return web.json_response({"error": "No files specified"}, status=400)
    if len(files) > 500:
        return web.json_response({"error": "Too many files (max 500)"}, status=400)

    # Validate all paths
    for f in files:
        if ".." in f or f.startswith("/"):
            return web.json_response({"error": f"Invalid path: {f}"}, status=400)
        if not f.lower().endswith(".mkv"):
            return web.json_response({"error": f"Not an MKV file: {f}"}, status=400)

    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"error": "No VOD storage configured"}, status=404)

    conn, sftp, error = await _connect_vod_sftp(token.user_id)
    if error:
        return web.json_response({"error": error}, status=502)

    # Derive archive name from common prefix
    parts_list = [f.split("/") for f in files]
    if len(parts_list) > 1 and len(parts_list[0]) > 1 and all(p[0] == parts_list[0][0] for p in parts_list):
        archive_name = parts_list[0][0]
        if len(parts_list[0]) > 2 and all(len(p) > 1 and p[1] == parts_list[0][1] for p in parts_list):
            archive_name += f"_{parts_list[0][1]}"
    elif len(files) == 1:
        archive_name = files[0].rsplit("/", 1)[-1].replace(".mkv", "")
    else:
        archive_name = "vods"
    archive_name = re.sub(r'[^\w\s-]', '_', archive_name)

    response = web.StreamResponse()
    response.content_type = "application/zip"
    response.headers["Content-Disposition"] = f'attachment; filename="{archive_name}.zip"'
    await response.prepare(request)

    remote_root = storage["remote_path"].rstrip("/")

    import struct
    import binascii

    # Track entries for central directory (written after all file data)
    entries = []  # list of (fname_bytes, crc32, size, local_header_offset)
    offset = 0    # running byte offset in the stream

    for filepath in files:
        remote_path = f"{remote_root}/{filepath}"
        try:
            fname_bytes = filepath.encode("utf-8")
            local_header_offset = offset

            # Local file header (no compression, data descriptor flag set)
            header = struct.pack(
                '<4sHHHHHIIIHH',
                b'PK\x03\x04',     # signature
                20,                 # version needed (2.0)
                0x08,               # flags: bit 3 = data descriptor follows
                0,                  # compression: stored
                0,                  # mod time
                0,                  # mod date
                0,                  # crc32 (deferred to data descriptor)
                0,                  # compressed size (deferred)
                0,                  # uncompressed size (deferred)
                len(fname_bytes),   # filename length
                0,                  # extra field length
            ) + fname_bytes
            await response.write(header)
            offset += len(header)

            # Stream file data from SFTP, computing CRC as we go
            crc = 0
            total_size = 0
            CHUNK_SIZE = 262144
            async with sftp.open(remote_path, "rb") as f:
                while True:
                    chunk = await f.read(CHUNK_SIZE)
                    if not chunk:
                        break
                    crc = binascii.crc32(chunk, crc) & 0xFFFFFFFF
                    total_size += len(chunk)
                    await response.write(chunk)
            offset += total_size

            # Data descriptor (with signature)
            desc = struct.pack('<4sIII',
                b'PK\x07\x08',   # signature
                crc,              # crc32
                total_size,       # compressed size (same as uncompressed for stored)
                total_size,       # uncompressed size
            )
            await response.write(desc)
            offset += len(desc)

            entries.append((fname_bytes, crc, total_size, local_header_offset))

        except (asyncssh.SFTPError, OSError) as e:
            logger.warning(f"Skipping VOD file in archive {filepath}: {e}")
            continue

    # Central directory
    cd_offset = offset
    cd_size = 0
    for fname_bytes, crc, size, local_offset in entries:
        cd_entry = struct.pack(
            '<4sHHHHHHIIIHHHHHII',
            b'PK\x01\x02',     # central directory signature
            20,                 # version made by (2.0)
            20,                 # version needed (2.0)
            0x08,               # flags: data descriptor
            0,                  # compression: stored
            0,                  # mod time
            0,                  # mod date
            crc,                # crc32
            size,               # compressed size
            size,               # uncompressed size
            len(fname_bytes),   # filename length
            0,                  # extra field length
            0,                  # file comment length
            0,                  # disk number start
            0,                  # internal file attributes
            0,                  # external file attributes
            local_offset,       # relative offset of local header
        ) + fname_bytes
        await response.write(cd_entry)
        cd_size += len(cd_entry)

    # End of central directory record
    entry_count = len(entries)
    eocd = struct.pack(
        '<4sHHHHIIH',
        b'PK\x05\x06',     # EOCD signature
        0,                  # disk number
        0,                  # disk with central dir
        entry_count,        # entries on this disk
        entry_count,        # total entries
        cd_size,            # size of central directory
        cd_offset,          # offset of central directory
        0,                  # comment length
    )
    await response.write(eocd)

    await response.write_eof()
    conn.close()
    return response


async def http_delete_vod(request: web.Request) -> web.Response:
    """Delete a VOD file from remote SFTP storage."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    filename = request.match_info.get("filename", "")

    # Security: prevent path traversal
    if not filename or ".." in filename or filename.startswith("/"):
        return web.json_response({"error": "Invalid filename"}, status=400)
    if not filename.lower().endswith(".mkv"):
        return web.json_response({"error": "Only MKV files can be deleted"}, status=400)

    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"error": "No VOD storage configured"}, status=404)

    conn, sftp, error = await _connect_vod_sftp(token.user_id)
    if error:
        return web.json_response({"error": error}, status=502)

    try:
        remote_path = f"{storage['remote_path'].rstrip('/')}/{filename}"
        await sftp.remove(remote_path)
        return web.json_response({"message": f"Deleted {filename}"})
    except asyncssh.SFTPError as e:
        logger.error(f"VOD delete SFTP error for user {token.user_id}: {e}")
        return web.json_response({"error": "SFTP operation failed"}, status=502)
    except OSError as e:
        logger.error(f"VOD delete error for user {token.user_id}: {e}")
        return web.json_response({"error": "Delete operation failed"}, status=502)
    finally:
        conn.close()


# =============================================================================
# Vulnerability Scanner API
# =============================================================================


async def http_vuln_scan_host(request: web.Request) -> web.Response:
    """Scan a host for vulnerabilities (admin only).

    Query parameters:
    - ports: Comma-separated list of ports to scan (optional)
    - scan_type: Type of scan - "basic", "version", "vuln", "full" (default: "version")
    - use_nmap: Whether to use nmap if available (default: true)
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    host = request.match_info.get("host")
    if not host:
        return web.json_response({"error": "Host required"}, status=400)

    # Validate host format (IP or hostname)
    ip_pattern = r'^(\d{1,3}\.){3}\d{1,3}$'
    hostname_pattern = r'^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$'

    if not (re.match(ip_pattern, host) or re.match(hostname_pattern, host)):
        return web.json_response({"error": "Invalid host format"}, status=400)

    # Parse optional ports parameter
    ports_param = request.query.get("ports", "")
    ports = None
    if ports_param:
        try:
            ports = [int(p.strip()) for p in ports_param.split(",") if p.strip()]
            if any(p < 1 or p > 65535 for p in ports):
                return web.json_response({"error": "Invalid port number"}, status=400)
        except ValueError:
            return web.json_response({"error": "Invalid ports format"}, status=400)

    # Parse scan type - basic, version, vuln, full
    scan_type = request.query.get("scan_type", "version")
    if scan_type not in ("basic", "version", "vuln", "full"):
        return web.json_response({"error": "Invalid scan_type. Use: basic, version, vuln, or full"}, status=400)

    # Parse use_nmap flag
    use_nmap = request.query.get("use_nmap", "true").lower() != "false"

    try:
        result = await vulnerability_scanner.scan_host(
            host, ports,
            scan_type=scan_type,
            use_nmap=use_nmap
        )
        logger.info(f"Vulnerability scan ({scan_type}) completed for {host} by user {token.user_id}")
        return web.json_response(result.to_dict())
    except RuntimeError as e:
        logger.warning(f"Vulnerability scan warning for {host}: {e}")
        return web.json_response({"error": str(e)}, status=400)
    except Exception as e:
        logger.error(f"Vulnerability scan failed for {host}: {e}")
        return web.json_response({"error": "Scan failed"}, status=500)


async def http_vuln_scan_service(request: web.Request) -> web.Response:
    """Scan a Portal service for vulnerabilities (admin only).

    Query parameters:
    - scan_type: Type of scan - "basic", "version", "vuln", "full" (default: "version")
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    service_id = request.match_info.get("service_id")
    if not service_id or not service_id.isdigit():
        return web.json_response({"error": "Invalid service ID"}, status=400)

    service = await db.get_service_by_id(int(service_id))
    if not service:
        return web.json_response({"error": "Service not found"}, status=404)

    host = service.get("host", "localhost")
    port = service.get("port")

    if not port:
        return web.json_response({"error": "Service has no port configured"}, status=400)

    # Parse scan type
    scan_type = request.query.get("scan_type", "version")
    if scan_type not in ("basic", "version", "vuln", "full"):
        scan_type = "version"

    try:
        result = await vulnerability_scanner.scan_host(host, [port], scan_type=scan_type)
        logger.info(f"Vulnerability scan ({scan_type}) completed for service {service_id} by user {token.user_id}")
        return web.json_response({
            "service": {
                "id": service["id"],
                "name": service["name"],
                "host": host,
                "port": port
            },
            "scan": result.to_dict()
        })
    except RuntimeError as e:
        logger.warning(f"Vulnerability scan warning for service {service_id}: {e}")
        return web.json_response({"error": str(e)}, status=400)
    except Exception as e:
        logger.error(f"Vulnerability scan failed for service {service_id}: {e}")
        return web.json_response({"error": "Scan failed"}, status=500)


async def http_vuln_search_cves(request: web.Request) -> web.Response:
    """Search CVEs by keyword (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    keyword = request.query.get("q", "").strip()
    if not keyword or len(keyword) < 2:
        return web.json_response({"error": "Search query must be at least 2 characters"}, status=400)

    try:
        limit = min(int(request.query.get("limit", "20")), 50)
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid limit parameter"}, status=400)

    try:
        results = await vulnerability_scanner.search_cves(keyword, limit)
        logger.info(f"CVE search for '{keyword}' by user {token.user_id}: {len(results)} results")
        return web.json_response({
            "query": keyword,
            "count": len(results),
            "cves": results
        })
    except Exception as e:
        logger.error(f"CVE search failed: {e}")
        return web.json_response({"error": "Search failed"}, status=500)


async def http_vuln_scanner_status(request: web.Request) -> web.Response:
    """Get vulnerability scanner status (admin only)."""
    token = await authenticate_request(request)
