async def http_update_server_hostname(request: web.Request) -> web.Response:
    """PUT /api/settings/hostname - Update server hostname."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)

    hostname = data.get("hostname", "").strip()
    if not hostname:
        return web.json_response({"error": "Hostname is required"}, status=400)

    # Basic validation: no spaces, no special chars except dots and hyphens
    if not re.match(r'^[a-zA-Z0-9][a-zA-Z0-9._-]*[a-zA-Z0-9]$', hostname) and hostname != "localhost":
        return web.json_response({"error": "Invalid hostname format"}, status=400)

    env_path = str(Path(__file__).parent / ".env")
    cert_manager.update_env_value(env_path, "HOSTNAME", hostname)
    Config.HOSTNAME = hostname

    # Update stream hostname if provided
    stream_hostname = data.get("stream_hostname", "").strip()
    if stream_hostname:
        if not re.match(r'^[a-zA-Z0-9][a-zA-Z0-9._-]*[a-zA-Z0-9]$', stream_hostname) and stream_hostname != "localhost":
            return web.json_response({"error": "Invalid stream hostname format"}, status=400)
        cert_manager.update_env_value(env_path, "STREAM_HOSTNAME", stream_hostname)
        Config.STREAM_HOSTNAME = stream_hostname

    logger.info(f"Hostname updated to {hostname} (stream: {Config.STREAM_HOSTNAME}) by user {token.user_id}")

    return web.json_response({
        "status": "success",
        "hostname": hostname,
        "stream_hostname": Config.STREAM_HOSTNAME,
        "message": "Hostname updated. Restart the server for full effect.",
    })


async def http_get_feature_permissions(request: web.Request) -> web.Response:
    """GET /api/settings/permissions - Get feature permission toggles (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    allow_connections = await db.get_setting("allow_user_connections")
    allow_streams = await db.get_setting("allow_user_streams")
    announce = await db.get_setting("stream_announce_channel_id")
    return web.json_response({
        "allow_user_connections": allow_connections != "false",
        "allow_user_streams": allow_streams != "false",
        "stream_announce_channel_id": int(announce) if announce and announce.isdigit() else None,
    })


async def http_update_feature_permissions(request: web.Request) -> web.Response:
    """PUT /api/settings/permissions - Update feature permission toggles (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)

    # Everything is checked before anything is saved: a refused request changes nothing.
    announce_value = None
    announce_set = False
    if "stream_announce_channel_id" in data:
        value = data["stream_announce_channel_id"]
        if value is None or value == "":
            announce_value, announce_set = "", True
        else:
            if type(value) is not int or value < 1 or value > _SQLITE_INT_MAX:
                return web.json_response({"error": "stream_announce_channel_id must be a channel id or null"}, status=400)
            channel = await db.get_chat_channel(value)
            if not channel:
                return web.json_response({"error": "Channel not found"}, status=404)
            if await db.get_stream_by_chat_channel(value):
                return web.json_response({"error": "A stream's own chat cannot be the announce channel"}, status=400)
            if not await _channel_open_to_members(channel):
                return web.json_response({"error": "The announce channel must be readable by every member (not private)"}, status=400)
            announce_value, announce_set = str(value), True

    if "allow_user_connections" in data:
        await db.set_setting("allow_user_connections", "true" if data["allow_user_connections"] else "false")
    if "allow_user_streams" in data:
        await db.set_setting("allow_user_streams", "true" if data["allow_user_streams"] else "false")
    if announce_set:
        await db.set_setting("stream_announce_channel_id", announce_value)

    logger.info(f"Feature permissions updated by user {token.user_id}: {data}")
    return web.json_response({"success": True})


