# Stream Relay Destination API
# =========================================================================

async def http_list_relay_destinations(request: web.Request) -> web.Response:
    """List relay destinations for a stream (owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    try:
        stream_id = _row_id(request.match_info["id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid stream ID"}, status=400)
    stream = await db.get_user_stream(stream_id)
    if not stream or stream["user_id"] != token.user_id:
        return web.json_response({"error": "Stream not found"}, status=404)
    destinations = await db.get_relay_destinations(stream_id)
    return web.json_response({"relays": destinations})


async def http_create_relay_destination(request: web.Request) -> web.Response:
    """Add a relay destination to a stream (owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    try:
        stream_id = _row_id(request.match_info["id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid stream ID"}, status=400)
    stream = await db.get_user_stream(stream_id)
    if not stream or stream["user_id"] != token.user_id:
        return web.json_response({"error": "Stream not found"}, status=404)

    # Check relay limit
    existing = await db.get_relay_destinations(stream_id)
    if len(existing) >= MAX_RELAYS_PER_STREAM:
        return web.json_response({"error": f"Maximum {MAX_RELAYS_PER_STREAM} relay destinations per stream"}, status=400)

    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    platform = body.get("platform", "custom")
    if platform not in RELAY_PLATFORMS:
        return web.json_response({"error": f"Invalid platform. Options: {', '.join(RELAY_PLATFORMS.keys())}"}, status=400)

    name = (body.get("name") or "").strip()
    if not name or len(name) > 100:
        return web.json_response({"error": "Name required (max 100 chars)"}, status=400)

    rtmp_url = (body.get("rtmp_url") or "").strip()
    if not rtmp_url:
        # Fall back to platform default if available
        rtmp_url = RELAY_PLATFORMS.get(platform, {}).get("default_url", "")
    if not rtmp_url:
        return web.json_response({"error": "RTMP URL required"}, status=400)
    if not rtmp_url.startswith(("rtmp://", "rtmps://")):
        return web.json_response({"error": "URL must start with rtmp:// or rtmps://"}, status=400)
    if len(rtmp_url) > 2048:
        return web.json_response({"error": "RTMP URL too long (max 2048 chars)"}, status=400)
    err = await _validate_relay_url(rtmp_url)
    if err:
        return web.json_response({"error": err}, status=400)

    stream_key = (body.get("stream_key") or "").strip()
    if not stream_key:
        return web.json_response({"error": "Stream key required"}, status=400)
    if len(stream_key) > 512:
        return web.json_response({"error": "Stream key too long (max 512 chars)"}, status=400)
    if _has_bad_chars(stream_key):
        return web.json_response({"error": "Stream key contains invalid characters"}, status=400)

    dest = await db.create_relay_destination(stream_id, platform, name, rtmp_url, stream_key)
    return web.json_response(dest, status=201)


async def http_update_relay_destination(request: web.Request) -> web.Response:
    """Update a relay destination (owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    try:
        stream_id = _row_id(request.match_info["id"])
        relay_id = _row_id(request.match_info["relay_id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid ID"}, status=400)
    stream = await db.get_user_stream(stream_id)
    if not stream or stream["user_id"] != token.user_id:
        return web.json_response({"error": "Stream not found"}, status=404)

    dest = await db.get_relay_destination(relay_id)
    if not dest or dest["stream_id"] != stream_id:
        return web.json_response({"error": "Relay destination not found"}, status=404)

    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    updates = {}
    if "platform" in body:
        if body["platform"] not in RELAY_PLATFORMS:
            return web.json_response({"error": f"Invalid platform"}, status=400)
        updates["platform"] = body["platform"]

    if "name" in body:
        name = (body["name"] or "").strip()
        if not name or len(name) > 100:
            return web.json_response({"error": "Name required (max 100 chars)"}, status=400)
        updates["name"] = name

    if "rtmp_url" in body:
        rtmp_url = (body["rtmp_url"] or "").strip()
        if rtmp_url and not rtmp_url.startswith(("rtmp://", "rtmps://")):
            return web.json_response({"error": "URL must start with rtmp:// or rtmps://"}, status=400)
        if rtmp_url and len(rtmp_url) > 2048:
            return web.json_response({"error": "RTMP URL too long (max 2048 chars)"}, status=400)
        if rtmp_url:
            err = await _validate_relay_url(rtmp_url)
            if err:
                return web.json_response({"error": err}, status=400)
            updates["rtmp_url"] = rtmp_url

    if "stream_key" in body:
        sk = (body["stream_key"] or "").strip()
        if sk and len(sk) > 512:
            return web.json_response({"error": "Stream key too long (max 512 chars)"}, status=400)
        if sk:
            if _has_bad_chars(sk):
                return web.json_response({"error": "Stream key contains invalid characters"}, status=400)
            updates["stream_key"] = sk

    if "enabled" in body:
        updates["enabled"] = 1 if body["enabled"] else 0

    if not updates:
        return web.json_response({"error": "No fields to update"}, status=400)

    updated = await db.update_relay_destination(relay_id, **updates)
    if not updated:
        return web.json_response({"error": "Relay destination not found"}, status=404)

    # If disabling while live, stop just that relay
    if updates.get("enabled") == 0:
        await stop_single_relay(stream_id, relay_id)

    return web.json_response({"ok": True})


async def http_delete_relay_destination(request: web.Request) -> web.Response:
    """Delete a relay destination (owner only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    try:
        stream_id = _row_id(request.match_info["id"])
        relay_id = _row_id(request.match_info["relay_id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid ID"}, status=400)
    stream = await db.get_user_stream(stream_id)
    if not stream or stream["user_id"] != token.user_id:
        return web.json_response({"error": "Stream not found"}, status=404)

    dest = await db.get_relay_destination(relay_id)
    if not dest or dest["stream_id"] != stream_id:
        return web.json_response({"error": "Relay destination not found"}, status=404)

    # Stop relay if active
    await stop_single_relay(stream_id, relay_id)

    deleted = await db.delete_relay_destination(relay_id)
    if not deleted:
        return web.json_response({"error": "Relay destination not found"}, status=404)
    return web.json_response({"ok": True})


async def http_get_relay_logs(request: web.Request) -> web.Response:
    """Get last error log for a relay destination (stream owner or admin)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    try:
        stream_id = _row_id(request.match_info["id"])
        relay_id = _row_id(request.match_info["relay_id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid ID"}, status=400)
    stream = await db.get_user_stream(stream_id)
    if not stream:
        return web.json_response({"error": "Stream not found"}, status=404)
    is_admin = token.has_scope("admin") or token.has_scope("*")
    if stream["user_id"] != token.user_id and not is_admin:
        return web.json_response({"error": "Stream not found"}, status=404)
    dest = await db.get_relay_destination(relay_id)
    if not dest or dest["stream_id"] != stream_id:
        return web.json_response({"error": "Relay destination not found"}, status=404)
    # get_relay_destination returns raw encrypted value — decrypt here
    last_error = dest.get("last_error")
    if last_error:
        last_error = decrypt_config(last_error)
    return web.json_response({
        "relay_id": relay_id,
        "last_error": last_error,
        "last_error_at": dest.get("last_error_at"),
    })


async def http_get_relay_platforms(request: web.Request) -> web.Response:
    """Get available relay platforms (any authenticated user)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    platforms = {k: {"name": v["name"], "default_url": v.get("default_url", "")} for k, v in RELAY_PLATFORMS.items()}
    return web.json_response({"platforms": platforms})


# _SSRFSafeResolver / _SSRFSafeConnector now live in host_check.py (imported at the top).


# Link preview cache: url -> (preview_data, timestamp) — bounded to 256 entries
_LINK_PREVIEW_CACHE_MAX = 256
_link_preview_cache: dict[str, tuple[dict, float]] = {}
_LINK_PREVIEW_TTL = 3600  # 1 hour


def _parse_opengraph(html: str, url: str) -> dict:
    """Extract OpenGraph metadata from HTML."""
    import urllib.parse as _urlparse

    def get_meta(prop):
        m = re.search(rf'<meta[^>]+(?:property|name)=["\']og:{prop}["\'][^>]+content=["\']([^"\']*)["\']', html, re.I)
        if not m:
            m = re.search(rf'<meta[^>]+content=["\']([^"\']*)["\'][^>]+(?:property|name)=["\']og:{prop}["\']', html, re.I)
        return m.group(1) if m else None

    title = get_meta("title")
    if not title:
        m = re.search(r'<title[^>]*>([^<]+)</title>', html, re.I)
        title = m.group(1).strip() if m else None

    description = get_meta("description")
    if not description:
        m = re.search(r'<meta[^>]+name=["\']description["\'][^>]+content=["\']([^"\']*)["\']', html, re.I)
        if not m:
            m = re.search(r'<meta[^>]+content=["\']([^"\']*)["\'][^>]+name=["\']description["\']', html, re.I)
        description = m.group(1) if m else None

    image = get_meta("image")
    site_name = get_meta("site_name")
    parsed = _urlparse.urlparse(url)
    domain = parsed.hostname

    return {
        "url": url,
        "title": title,
        "description": description[:300] if description else None,
        "image": image,
        "site_name": site_name or domain,
        "domain": domain
    }


async def http_link_preview(request: web.Request) -> web.Response:
    """Fetch link preview (OpenGraph metadata) for a URL."""
    import urllib.parse as _urlparse
    import ipaddress

    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    url = request.query.get("url", "").strip()
    if not url:
        return web.json_response({"error": "url parameter required"}, status=400)

    parsed = _urlparse.urlparse(url)
    if parsed.scheme not in ("http", "https"):
        return web.json_response({"error": "Only http/https URLs allowed"}, status=400)

    hostname = parsed.hostname
    if not hostname:
        return web.json_response({"error": "Invalid URL"}, status=400)

    # SSRF protection
    if is_blocked_host(hostname):
        return web.json_response({"error": "Blocked host"}, status=403)
    try:
        ip = ipaddress.ip_address(hostname)
        if ip.is_private or ip.is_loopback or ip.is_reserved or ip.is_link_local:
            return web.json_response({"error": "Blocked host"}, status=403)
    except ValueError:
        pass
    # DNS resolution check: validate resolved IPs are not private/internal
    import socket
    try:
        resolved = socket.getaddrinfo(hostname, None)
        for family, stype, proto, canonname, sockaddr in resolved:
            ip_str = sockaddr[0]
            if is_blocked_host(ip_str):
                return web.json_response({"error": "URL resolves to blocked address"}, status=403)
    except socket.gaierror:
        return web.json_response({"error": "Could not resolve hostname"}, status=400)

    # Check cache
    now = time()
    if url in _link_preview_cache:
        cached, ts = _link_preview_cache[url]
        if now - ts < _LINK_PREVIEW_TTL:
            return web.json_response(cached)

    try:
        # Use SSRF-safe connector that validates IPs at connection time,
        # preventing DNS rebinding between the check above and the fetch
        connector = _SSRFSafeConnector()
        timeout = aiohttp.ClientTimeout(total=5)
        async with aiohttp.ClientSession(timeout=timeout, connector=connector) as session:
            async with session.get(url, headers={"User-Agent": "PortalBot/1.0"}, allow_redirects=True, max_redirects=3) as resp:
                if resp.status != 200:
                    return web.json_response({"error": "Failed to fetch URL"}, status=502)
                content_type = resp.content_type or ""
                if "html" not in content_type:
                    return web.json_response({"error": "Not an HTML page"}, status=400)
                body = await resp.content.read(1_048_576)  # 1MB max
                html = body.decode("utf-8", errors="replace")

        preview = _parse_opengraph(html, url)
        _link_preview_cache[url] = (preview, now)

        # Evict expired + oldest entries when cache exceeds max
        if len(_link_preview_cache) > _LINK_PREVIEW_CACHE_MAX:
            # First pass: remove expired entries
            expired = [k for k, (_, ts) in _link_preview_cache.items() if now - ts >= _LINK_PREVIEW_TTL]
            for k in expired:
                _link_preview_cache.pop(k, None)
            # Second pass: if still over limit, drop oldest half
            if len(_link_preview_cache) > _LINK_PREVIEW_CACHE_MAX:
                sorted_keys = sorted(_link_preview_cache, key=lambda k: _link_preview_cache[k][1])
                for k in sorted_keys[:len(sorted_keys) // 2]:
                    _link_preview_cache.pop(k, None)

        return web.json_response(preview)
    except asyncio.TimeoutError:
        return web.json_response({"error": "Timeout"}, status=504)
    except Exception as e:
        logger.debug(f"Link preview error for {url}: {e}")
        return web.json_response({"error": "Failed to fetch preview"}, status=502)


# Chat roles that may see who wrote an anonymous message (moderation needs it).
_CHAT_STAFF_ROLES = frozenset(("moderator", "admin", "superadmin"))

# Per-process key for the opaque handle that lets a client tell anonymous
# participants apart in presence events without learning their account id.
_ANON_REF_KEY = secrets.token_bytes(16)


def _anon_ref(channel, user_id) -> str:
    """Opaque, per-process handle for an anonymous participant in one channel.
    The channel is part of the input so the same person cannot be matched
    across channels by comparing handles."""
    data = ("%s:%s" % (channel, user_id)).encode()
    return hmac.new(_ANON_REF_KEY, data, hashlib.sha256).hexdigest()[:12]


def _viewer_sees_identity(viewer_id, viewer_role, subject_id) -> bool:
    """True if this viewer may receive the real account id of an anonymous
    participant: the participant themself, moderators and admins. Nobody else
    does, including the owner of a stream whose chat this is."""
    return viewer_id == subject_id or (viewer_role or "") in _CHAT_STAFF_ROLES


def _mask_anonymous_author(m: dict, viewer_id, viewer_role=None) -> None:
    """Strip the author's identity from an anonymous chat message payload.

    Policy: ordinary members never receive the real user id or role of an
    anonymous message's author (the id maps back to a username through other
    APIs; a role such as admin narrows the author down). The author and staff
    (moderator, admin, superadmin) keep the id and role so edit, delete and
    moderation actions still work; they still see the display name
    "Anonymous". The nickname is never sent for an anonymous message.
    """
    if not m.get("anonymous"):
        return
    m["nickname"] = None
    m.pop("author_nickname", None)
    if _viewer_sees_identity(viewer_id, viewer_role, m.get("user_id")):
        return
    m["user_id"] = None
    m["role"] = None
    m.pop("author_role", None)
    poll = m.get("poll")
    if isinstance(poll, dict):
        m["poll"] = {**poll, "user_id": None}


def _mask_ban_rows(bans, viewer_id, viewer_role=None) -> list:
    """Copy of a stream ban list for one viewer. A ban recorded from an
    anonymous post names no one unless the viewer is entitled to the author's
    identity (staff, or the banned account itself); other viewers get
    user_id None and the name "Anonymous" and lift it by the ban id."""
    out = []
    for b in bans:
        b = dict(b)
        if b.get("anonymous") and not _viewer_sees_identity(viewer_id, viewer_role, b.get("user_id")):
            b["user_id"] = None
            b["banned_username"] = "Anonymous"
        out.append(b)
    return out


# Only presence events carry the handle, so it can be matched with an entry of
# the online list. Moderation notices (ban, timeout, ...) never do: they can
# be provoked by a caller who names an account id, and the handle would then
# map that account to its entry in the list.
_ANON_REF_EVENT_TYPES = frozenset({"user_joined", "user_left", "user_status_changed",
                                   "user_anonymous_changed"})


def _hide_subject(payload: dict, subject_id, channel=None) -> dict:
    """Copy of a live payload about an anonymous participant with the real id,
    role, nickname, status text and last-seen time removed and a fine-grained
    status reduced to "online". Presence events get an opaque handle instead
    so several anonymous participants stay distinguishable."""
    p = dict(payload)
    if "status" in p:
        p["status"] = "online"
    for key in ("user_id", "role", "nickname", "deleted_by", "status_message", "last_seen_at"):
        if key in p:
            p[key] = None
    poll = p.get("poll")
    if isinstance(poll, dict):
        p["poll"] = {**poll, "user_id": None}
    if p.get("type") in _ANON_REF_EVENT_TYPES:
        p["anon_ref"] = _anon_ref(channel, subject_id)
    return p


async def _mask_reactor_ids(reactions_by_message: dict, viewer_id, viewer_role) -> None:
    """Drop the id of every reactor who is currently in anonymous mode from the
    reactions[].user_ids lists of one viewer's history payload. Counts are not
    touched; the viewer's own id and staff viewers' lists are left as they are."""
    if (viewer_role or "") in _CHAT_STAFF_ROLES:
        return
    ids = {uid for reactions in reactions_by_message.values()
           for r in reactions for uid in r.get("user_ids", [])}
    ids.discard(viewer_id)
    if not ids:
        return
    anonymous = {u["id"] for u in await db.get_users_status(list(ids)) if u.get("chat_anonymous")}
    if not anonymous:
        return
    for reactions in reactions_by_message.values():
        for r in reactions:
            r["user_ids"] = [uid for uid in r.get("user_ids", []) if uid not in anonymous]


def _user_has_other_socket(channel: str, user_id, ws) -> bool:
    """True if the user has another open socket in the room besides ws.

    A member can hold more than one chat socket in a room (the main watch page
    and the pop-out chat window), so join and leave announcements are made only
    by the first socket to arrive and the last one to go. Callers run this right
    after changing the room set, with no await in between. Only room membership
    counts, not the socket's closed flag: a socket whose close frame was handled
    but whose cleanup has not run yet is still in the room and will announce the
    leave itself, so two sockets closing together announce it exactly once.
    """
    for entry in chat_rooms.get(channel, ()):
        if entry[1] == user_id and entry[0] is not ws:
            return True
    return False


def _chat_users_list(users_info: list, channel: str, viewer_id, viewer_role) -> list:
    """Online-user entries for one viewer. Anonymous participants appear under
    the name "Anonymous" with no nickname or avatar; ordinary members get an
    opaque handle instead of their id and role, and no status text, last-seen
    time or fine-grained status (those are visible under the real name in
    other places and would link the entry to an account)."""
    out = []
    for u in users_info:
        avatar = {}
        if u.get("avatar"):
            try:
                avatar = json.loads(u["avatar"])
            except (json.JSONDecodeError, TypeError):
                pass
        voice_info = voice_state.get(channel, {}).get(u["id"], {})
        anon = bool(u.get("chat_anonymous"))
        entry = {
            "user_id": u["id"],
            "username": "Anonymous" if anon else (u.get("nickname") or u["username"]),
            "nickname": None if anon else u.get("nickname"),
            "status": u.get("status", "online"),
            "status_message": u.get("status_message"),
            "last_seen_at": u.get("last_seen_at"),
            "role": u.get("role", "user"),
            "anonymous": anon,
            "avatar": {} if anon else avatar,
            "in_voice": bool(voice_info),
            "voice_muted": voice_info.get("muted", False),
            "voice_deafened": voice_info.get("deafened", False),
            "voice_speaking": voice_info.get("speaking", False),
            "voice_reconnecting": bool(voice_info.get("reconnecting", False)),
            "screen_sharing": voice_info.get("screen_sharing", False)
        }
        if anon and not _viewer_sees_identity(viewer_id, viewer_role, u["id"]):
            entry["user_id"] = None
            entry["role"] = None
            entry["status"] = "online"
            entry["status_message"] = None
            entry["last_seen_at"] = None
            entry["anon_ref"] = _anon_ref(channel, u["id"])
        out.append(entry)
    # Masked entries go last, ordered by their opaque handle, so the position
    # of an anonymous entry says nothing about the account id.
    out.sort(key=lambda e: (1, e["anon_ref"]) if e.get("anon_ref") else (0, ""))
    return out


# =============================================================================
# Reading channel history: join, WebSocket history_page, GET .../messages
#
# Every way of reading messages of a channel goes through the two helpers
# below, so access rules (stream ban, private membership, removed member) and
# anonymous masking cannot differ between them.
# =============================================================================

HISTORY_PAGE_DEFAULT = 50
HISTORY_PAGE_MAX = 100
HISTORY_NO_STORE = {"Cache-Control": "private, no-store"}   # message text must not sit in a shared or browser cache
HISTORY_ID_MAX = 2**63 - 1      # largest id SQLite can hold; anything above is refused before it reaches the database
# Page requests per user and window, over all sockets and the HTTP route.
HISTORY_RATE_LIMIT = 30
HISTORY_RATE_WINDOW = 60.0
_history_hits: dict[int, list[float]] = {}

_STREAM_UNSET = object()


async def _stream_chat_shared(channel_id) -> bool:
    """True when the stream's powers do not apply to this channel: it is a default
    channel or more than one stream uses it (see get_stream_by_chat_channel). A
    stream clears the history of, and bans members from, only a chat that is its
    own. A lookup failure counts as shared (nothing is deleted)."""
    try:
        bound = await db.get_stream_by_chat_channel(channel_id)
    except Exception as e:
        logger.warning(f"[Chat] Could not tell whether channel {channel_id} is shared: {e}")
        return True
    return bool(bound and bound.get("chat_channel_shared"))


class _ReadAccess:
    """Result of _can_read_channel: true when the viewer may read the channel,
    otherwise `reason` says why ("missing", "hidden", "banned" or "private") and
    `message` is the text the join path has always sent for it."""
    __slots__ = ("allowed", "reason", "message")

    def __init__(self, allowed: bool, reason: str = None, message: str = None):
        self.allowed = allowed
        self.reason = reason
        self.message = message

    def __bool__(self) -> bool:
        return self.allowed


def _stream_chat_hidden(stream, user_id: int, user_role: str) -> bool:
    """True when the chat of this stream is closed to this member: the stream is
    not public and the member is neither its owner nor an admin (the rule of the
    stream detail route). A channel without a stream is never hidden by this.

    A default channel is never hidden by a stream binding. A channel bound to
    several streams fails closed: it is hidden unless every bound stream is
    public, and its owners are the owners of any of them (plus admins)."""
    if not stream:
        return False
    if stream.get("chat_channel_default"):
        return False
    if "chat_channel_all_public" in stream:
        if stream["chat_channel_all_public"]:
            return False
        owners = stream.get("chat_channel_owner_ids") or [stream.get("user_id")]
    else:
        if stream.get("is_public"):
            return False
        owners = [stream.get("user_id")]
    return user_id not in owners and user_role not in ("admin", "superadmin")


async def _can_read_channel(channel, user_id: int, user_role: str, stream=_STREAM_UNSET) -> _ReadAccess:
    """The one decision on whether a member may read a channel's messages.

    False for a missing channel, for the chat of a stream that is not public
    (only its owner and admins read it; everyone else gets the answer for a
    missing channel), for a member banned from the chat of the stream the
    channel belongs to, and for a private channel the member does not belong
    to (admins and superadmins read every channel, moderators do not). The
    stream is the one whose chat_channel_id is this channel. Callers pass
    `stream` when they already have it (None means the channel has no stream).
    The answer is looked up each time: a member removed from a private channel
    loses access on the next request, even on a socket that joined while still
    a member.
    """
    if not channel:
        return _ReadAccess(False, "missing", "Channel not found")
    if stream is _STREAM_UNSET:
        stream = await db.get_stream_by_chat_channel(channel["id"])
    if _stream_chat_hidden(stream, user_id, user_role):
        return _ReadAccess(False, "hidden", "Channel not found")
    if stream and await db.is_user_banned_from_stream(stream["id"], user_id):
        return _ReadAccess(False, "banned", "You are banned from this stream's chat")
    if channel.get("visibility", "public") == "private" and user_role not in ("admin", "superadmin"):
        if not await db.is_channel_member(channel["id"], user_id):
            return _ReadAccess(False, "private", "This channel is private")
    return _ReadAccess(True)


async def _socket_may_act_in(ws, channel, user_id: int, user_role: str, notify: bool = True) -> bool:
    """The read check for an action a joined socket takes in its current channel.

    A socket that joined while it could read the channel keeps `current_channel`
    after that stops (stream made private, stream ban, removed from a private
    channel), so every per-socket action asks again. False after sending the
    refusal to ws (unless notify is off, for the high-volume typing signal).
    """
    access = await _can_read_channel(channel, user_id, user_role)
    if access:
        return True
    if notify:
        await ws.send_json({"type": "error", "message": access.message})
    return False


async def _evict_unreadable_sockets(channel) -> int:
    """After access to a channel was lost (stream made not public, member removed
    from a private channel, stream ban, channel made private): put every socket in
    its room that can no longer read it out.

    _can_read_channel is run again for each socket in chat_rooms[channel name].
    One that fails is removed from the room (so it receives nothing more from it;
    the handler clears its current channel when its next frame arrives, and
    every per-socket action checks access itself in the meantime), is sent one
    error frame with the answer for a missing channel, and the member's voice
    entry in that room ends through the usual leave path. Members that are in
    the voice room without a socket in the text room are checked too. The rest
    of the room is told who left. Returns the number of sockets put out; never
    raises (a failure is logged and the next socket is still checked).
    """
    if not channel:
        return 0
    name = channel["name"]
    evicted = []
    try:
        stream = await db.get_stream_by_chat_channel(channel["id"])
        verdicts: dict = {}
        for entry in list(chat_rooms.get(name, ())):
            key = (entry[1], entry[3] if len(entry) > 3 else None)
            if key not in verdicts:
                verdicts[key] = bool(await _can_read_channel(channel, key[0], key[1], stream))
            if verdicts[key]:
                continue
            # No await between the check of this socket's verdict and its removal
            chat_rooms[name].discard(entry)
            evicted.append(entry)
    except Exception as e:
        logger.warning(f"[Chat] Could not re-check access to #{name}: {e}")
    for entry in evicted:
        try:
            await asyncio.wait_for(entry[0].send_json(
                {"type": "error", "message": "Channel not found", "channel": name}), 2)
        except Exception:
            pass
    # Voice: whoever is in this channel's voice room and may no longer read it
    for voice_user_id in list((voice_state.get(name) or {}).keys()):
        await _voice_eject_if_not_allowed(voice_user_id)
    if evicted:
        if name in chat_rooms and not chat_rooms[name]:
            del chat_rooms[name]
        try:
            for entry in evicted:
                if _user_has_other_socket(name, entry[1], entry[0]):
                    continue
                state = chat_user_state.get(entry[1], {})
                anon = bool(state.get("anonymous"))
                await broadcast_to_channel(name, {
                    "type": "user_left",
                    "user_id": entry[1],
                    "username": "Anonymous" if anon else (state.get("nickname") or entry[2])
                }, anon_subject=entry[1] if anon else None)
            await broadcast_users_list(name)
        except Exception as e:
            logger.warning(f"[Chat] Could not announce the removal from #{name}: {e}")
        logger.info(f"[Chat] {len(evicted)} socket(s) removed from #{name} after access was lost")
    return len(evicted)


async def _evict_unreadable_by_id(channel_id) -> int:
    """_evict_unreadable_sockets for a channel known by id. Never raises."""
    try:
        return await _evict_unreadable_sockets(await db.get_chat_channel(channel_id))
    except Exception as e:
        logger.warning(f"[Chat] Could not re-check access to channel {channel_id}: {e}")
        return 0


async def _enrich_channel_messages(messages: list, viewer_id, viewer_role, channel_id) -> list:
    """Add display data to channel messages (in place) for one viewer.

    Author name, nickname, avatar and role; anonymous authors are masked for
    this viewer (see _mask_anonymous_author); reply previews (one query for
    all targets, restricted to this channel; a deleted original falls back to
    the preview stored with the reply); reactions with anonymous reactors
    dropped from the id lists; polls with an anonymous creator's id removed.
    Join, history_page and the HTTP route all use this and nothing else.
    """
    if not messages:
        return messages
    reply_ids = {m["reply_to"] for m in messages if m.get("reply_to")}
    targets = {t["id"]: t for t in await db.get_chat_messages_by_ids(reply_ids, channel_id)}
    # Authors of the messages and of the messages they answer, so a preview
    # shows the same name whichever page it is on.
    author_ids = {m["user_id"] for m in messages if m.get("user_id")}
    author_ids |= {t["user_id"] for t in targets.values() if t.get("user_id")}
    users_map = {}
    for u in await db.get_users_status(list(author_ids)):
        u_avatar = {}
        if u.get("avatar"):
            try:
                u_avatar = json.loads(u["avatar"])
            except (json.JSONDecodeError, TypeError):
                pass
        users_map[u["id"]] = {
            "nickname": u.get("nickname"),
            "avatar": u_avatar,
            "role": u.get("role", "user"),
            "anonymous": bool(u.get("chat_anonymous"))
        }
    # Display priority: Anon > Nickname > Username, from the per-message flag
    for m in messages:
        ui = users_map.get(m.get("user_id"), {})
        was_anonymous = bool(m.get("anonymous"))
        m["nickname"] = ui.get("nickname") if not was_anonymous else None
        m["avatar"] = ui.get("avatar", {}) if not was_anonymous else {}
        m["role"] = ui.get("role", "user")
        m["anonymous"] = was_anonymous
        if was_anonymous:
            m["username"] = "Anonymous"
        elif ui.get("nickname"):
            m["username"] = ui["nickname"]
        _mask_anonymous_author(m, viewer_id, viewer_role)
        if m.get("reply_to"):
            rmsg = targets.get(m["reply_to"])
            if rmsg:
                r_ui = users_map.get(rmsg.get("user_id"), {})
                r_username = "Anonymous" if rmsg.get("anonymous") else (r_ui.get("nickname") or rmsg["username"])
                r_text = rmsg["message"]
                if len(r_text) > 100:
                    r_text = r_text[:100] + "..."
                m["reply_preview"] = {"id": m["reply_to"], "username": r_username, "message": r_text}
            elif m.get("reply_preview_username"):
                # Original message was deleted: use the stored preview
                m["reply_preview"] = {
                    "id": m["reply_to"],
                    "username": m["reply_preview_username"],
                    "message": m.get("reply_preview_text") or "",
                    "deleted": True
                }
    msg_ids = [m["id"] for m in messages]
    card_ids = [m["id"] for m in messages if m.get("message_type") == "stream_card"]
    if card_ids:
        cards = await db.get_stream_cards(card_ids)
        for m in messages:
            c = cards.get(m["id"])
            if c:
                m["card"] = {"stream_id": c["stream_id"], "streamer": c["streamer"], "title": c["title"]}
    all_reactions = await db.get_bulk_reactions(msg_ids)
    await _mask_reactor_ids(all_reactions, viewer_id, viewer_role)
    all_polls = await db.get_polls_by_message_ids(msg_ids)
    for m in messages:
        m["reactions"] = all_reactions.get(m["id"], [])
        if m["id"] in all_polls:
            m["poll"] = _format_poll_for_client(all_polls[m["id"]], viewer_id)
            if m.get("anonymous") and not _viewer_sees_identity(
                    viewer_id, viewer_role, all_polls[m["id"]].get("user_id")):
                m["poll"]["user_id"] = None
    return messages


def _parse_history_request(before_id, around_id, limit) -> tuple:
    """Validate the cursor and page size of a history request. Returns
    (before_id, around_id, limit); raises ValueError with a message for the
    caller to send back. The size defaults to 50 and is capped at 100."""
    def as_id(value, name):
        if value is None or value == "":
            return None
        if isinstance(value, bool):
            raise ValueError(f"{name} must be a message id")
        try:
            number = int(value)
        except (ValueError, TypeError, OverflowError):
            raise ValueError(f"{name} must be a message id")
        # SQLite integers are 64 bit; a larger id would raise inside the driver
        if number < 1 or number > HISTORY_ID_MAX:
            raise ValueError(f"{name} must be a message id")
        return number
    before_id = as_id(before_id, "before_id")
    around_id = as_id(around_id, "around_id")
    if before_id is not None and around_id is not None:
        raise ValueError("Give before_id or around_id, not both")
    if limit is None or limit == "":
        limit = HISTORY_PAGE_DEFAULT
    else:
        if isinstance(limit, bool):
            raise ValueError("limit must be a number")
        try:
            limit = int(limit)
        except (ValueError, TypeError, OverflowError):
            raise ValueError("limit must be a number")
        if limit < 1:
            raise ValueError("limit must be at least 1")
        limit = min(limit, HISTORY_PAGE_MAX)
    return before_id, around_id, limit


def _history_rate_wait(user_id: int) -> int:
    """Count one history request for this user (all sockets and the HTTP route
    share the budget). Returns 0 if it is allowed, else the seconds to wait."""
    now = monotonic()
    hits = [t for t in _history_hits.get(user_id, ()) if now - t < HISTORY_RATE_WINDOW]
    if len(hits) >= HISTORY_RATE_LIMIT:
        _history_hits[user_id] = hits
        return max(1, int(HISTORY_RATE_WINDOW - (now - hits[0])) + 1)
    hits.append(now)
    _history_hits[user_id] = hits
    if len(_history_hits) > 2000:
        for uid in [u for u, h in _history_hits.items() if not h or now - h[-1] >= HISTORY_RATE_WINDOW]:
            _history_hits.pop(uid, None)
    return 0


async def _channel_history(channel: dict, viewer_id, viewer_role, *, before_id=None,
                           around_id=None, limit=HISTORY_PAGE_DEFAULT) -> dict:
    """One page of a channel's messages for one viewer, already enriched and
    masked. The caller has checked _can_read_channel.

    No cursor: the newest page. before_id: the page of older messages.
    around_id: a window centred on that message; `found` is False when it is
    not a message of this channel (the list is then empty). `has_more` says
    whether older messages exist, `has_newer` whether newer ones do. Nothing
    here marks anything as read."""
    found = True
    has_newer = False
    if around_id is not None:
        window = await db.get_chat_messages_around(channel["id"], around_id, limit)
        if window is None:
            messages, has_more, found = [], False, False
        else:
            messages, has_more, has_newer = window
    else:
        messages, has_more = await db.get_chat_messages_page(channel["id"], limit, before_id)
    await _enrich_channel_messages(messages, viewer_id, viewer_role, channel["id"])
    return {"channel_id": channel["id"], "messages": messages, "has_more": has_more,
            "has_newer": has_newer, "found": found}


async def http_get_channel_messages(request: web.Request) -> web.Response:
    """GET /api/chat/channels/{id}/messages?before_id=|around_id=&limit=

    Older messages of a channel, or a window around one message (for links to
    a message). Same authentication as the other chat routes; a channel the
    caller cannot read answers 404, the same as one that does not exist."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    try:
        channel_id = int(request.match_info["id"])
        if channel_id < 1 or channel_id > HISTORY_ID_MAX:
            raise ValueError("out of range")
    except (ValueError, TypeError):
        return web.json_response({"error": "Channel not found"}, status=404)
    q = request.query
    try:
        before_id, around_id, limit = _parse_history_request(
            q.get("before_id"), q.get("around_id"), q.get("limit"))
    except ValueError as e:
        return web.json_response({"error": str(e)}, status=400)
    wait = _history_rate_wait(token.user_id)
    if wait:
        return web.json_response({"error": "Too many history requests"}, status=429,
                                 headers={"Retry-After": str(wait)})
    user = await db.get_user_by_id(token.user_id)
    user_role = (user.get("role") or ("superadmin" if user.get("is_admin") else "user")) if user else "user"
    channel = await db.get_chat_channel(channel_id)
    if not await _can_read_channel(channel, token.user_id, user_role):
        return web.json_response({"error": "Channel not found"}, status=404, headers=HISTORY_NO_STORE)
    return web.json_response(await _channel_history(
        channel, token.user_id, user_role, before_id=before_id, around_id=around_id, limit=limit),
        headers=HISTORY_NO_STORE)


async def http_get_chat_thread(request: web.Request) -> web.Response:
    """Get reply chain for a message (thread view).

    Readable under the same rule as the channel's history (_can_read_channel:
    stream ban, removed member, closed stream chat, private channel); a message
    the caller may not read answers 404, the same as one that does not exist."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        message_id = int(request.match_info["id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid message ID"}, status=400)

    def not_found():
        return web.json_response({"error": "Message not found"}, status=404, headers=HISTORY_NO_STORE)

    if message_id < 1 or message_id > HISTORY_ID_MAX:
        return not_found()
    root_msg = await db.get_chat_message(message_id)
    if not root_msg:
        return not_found()

    user = await db.get_user_by_id(token.user_id)
    user_role = (user.get("role") or ("superadmin" if user.get("is_admin") else "user")) if user else "user"
    ch_id = root_msg.get("channel_id")
    if ch_id:
        channel = await db.get_chat_channel(ch_id)
        if not await _can_read_channel(channel, token.user_id, user_role):
            return not_found()

    chain = await db.get_reply_chain(message_id)
    if not chain:
        return not_found()

    # A reply chain stays in one channel; drop anything that sits in a channel
    # the caller may not read, then enrich one channel at a time.
    by_channel: dict = {}
    for m in chain:
        m_ch_id = m.get("channel_id")
        if m_ch_id not in by_channel:
            if m_ch_id == ch_id:
                allowed = True
            else:
                allowed = bool(await _can_read_channel(
                    await db.get_chat_channel(m_ch_id) if m_ch_id else None, token.user_id, user_role))
            by_channel[m_ch_id] = allowed
    chain = [m for m in chain if by_channel.get(m.get("channel_id"))]
    for m_ch_id in {m.get("channel_id") for m in chain}:
        await _enrich_channel_messages([m for m in chain if m.get("channel_id") == m_ch_id],
                                       token.user_id, user_role, m_ch_id)

    return web.json_response({"thread": chain}, headers=HISTORY_NO_STORE)


