# Audit entries about system webhooks and alert routing: the audit log is open to moderators, and
# these name destinations and settings only a superadmin manages, so everyone else never sees them.
SUPERADMIN_ONLY_AUDIT_ACTIONS = ("webhook_system_create", "webhook_system_update", "webhook_system_delete",
                                 "webhook_allow_private", "alert_notify_change")


async def http_get_audit_log(request: web.Request) -> web.Response:
    """Get audit log entries (moderator+ only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)
    role = user.get("role") or ("superadmin" if user.get("is_admin") else "user")
    if role not in ("admin", "superadmin", "moderator"):
        return web.json_response({"error": "Moderator access required"}, status=403)

    try:
        limit = int(request.query.get("limit", 50))
        offset = int(request.query.get("offset", 0))
    except (ValueError, TypeError):
        limit, offset = 50, 0
    limit = min(limit, 200)

    filters = {}
    if request.query.get("action"):
        filters["action"] = request.query["action"]
    if request.query.get("actor_id"):
        try:
            filters["actor_id"] = int(request.query["actor_id"])
        except (ValueError, TypeError):
            pass
    if request.query.get("channel_id"):
        try:
            filters["channel_id"] = int(request.query["channel_id"])
        except (ValueError, TypeError):
            pass
    if request.query.get("since"):
        filters["since"] = request.query["since"]

    if role != "superadmin":
        filters["exclude_actions"] = SUPERADMIN_ONLY_AUDIT_ACTIONS
    entries = await db.get_audit_log(limit=limit, offset=offset, **filters)
    total = await db.get_audit_log_count(**filters)
    return web.json_response({"entries": entries, "total": total})


# =============================================================================
# Security events API (superadmin only)
# =============================================================================

async def _security_log_caller(request: web.Request):
    """(token, user, error response). Reading the log needs the superadmin role
    on a credential that carries admin scope, so a narrow key cannot read it."""
    token = await authenticate_request(request)
    if not token:
        return None, None, unauthorized_response(request)
    if not token.has_scope("admin") and not token.has_scope("*"):
        return None, None, forbidden_response(request)
    user = await db.get_user_by_id(token.user_id)
    if not user or user.get("role") != "superadmin":
        return None, None, web.json_response({"error": "Superadmin access required"}, status=403)
    return token, user, None


def _security_log_filters(request: web.Request):
    """Filters from the query string: (filters dict, error response)."""
    q = request.query
    filters = {}
    category = q.get("category", "")
    if category and category != "all":
        if category not in secevents.CATEGORIES:
            return None, web.json_response({"error": "category must be auth, security or all"}, status=400)
        filters["category"] = category
    if q.get("event"):
        filters["event"] = q["event"][:40]
    if q.get("ip"):
        filters["ip"] = q["ip"][:64]
    if q.get("username"):
        filters["username"] = q["username"][:secevents.USERNAME_MAX]
    if q.get("user_id"):
        try:
            filters["user_id"] = int(q["user_id"])
        except (ValueError, TypeError):
            return None, web.json_response({"error": "Invalid user_id"}, status=400)
    for name, end in (("since", False), ("until", True)):
        if q.get(name):
            try:
                filters[name] = secevents.parse_bound(q[name], end=end)
            except (ValueError, TypeError):
                return None, web.json_response({"error": f"Invalid {name}"}, status=400)
    return filters, None


async def http_get_security_events(request: web.Request) -> web.Response:
    """GET /api/admin/security-events - page through the security event log."""
    token, user, err = await _security_log_caller(request)
    if err:
        return err
    filters, err = _security_log_filters(request)
    if err:
        return err
    try:
        limit = max(1, min(int(request.query.get("limit", 50)), 200))
        offset = max(0, int(request.query.get("offset", 0)))
    except (ValueError, TypeError):
        limit, offset = 50, 0
    events = await db.get_security_events(limit=limit, offset=offset, **filters)
    total = await db.count_security_events(**filters)
    return web.json_response({"events": events, "total": total})


async def http_export_security_events(request: web.Request) -> web.StreamResponse:
    """GET /api/admin/security-events/export?format=csv|json - stream the filtered rows.

    Capped at secevents.EXPORT_MAX_ROWS (newest first; the X-Export-Truncated
    header says when rows were left out). Each export is itself recorded.
    """
    token, user, err = await _security_log_caller(request)
    if err:
        return err
    fmt = request.query.get("format", "csv").lower()
    if fmt not in ("csv", "json"):
        return web.json_response({"error": "format must be csv or json"}, status=400)
    filters, err = _security_log_filters(request)
    if err:
        return err
    total = await db.count_security_events(**filters)
    cap = secevents.EXPORT_MAX_ROWS
    truncated = total > cap

    await security_event(
        "security_log_export", request=request, user=user, result=fmt,
        details={"format": fmt, "rows": min(total, cap), "truncated": truncated,
                 **{k: v for k, v in filters.items()}})

    stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
    resp = web.StreamResponse(headers={
        "Content-Type": "text/csv; charset=utf-8" if fmt == "csv" else "application/json",
        "Content-Disposition": f'attachment; filename="security-events-{stamp}.{fmt}"',
        "Cache-Control": "no-store",
        "X-Export-Rows": str(min(total, cap)),
        "X-Export-Truncated": "true" if truncated else "false",
    })
    await resp.prepare(request)
    if fmt == "csv":
        await resp.write(secevents.csv_line(secevents.CSV_COLUMNS).encode("utf-8"))
    else:
        await resp.write(b'{"events":[')
    sent = 0
    before_id = None
    first = True
    while sent < cap:
        want = min(secevents.EXPORT_PAGE, cap - sent)
        page = await db.get_security_events(limit=want, offset=0, before_id=before_id, **filters)
        if not page:
            break
        chunk = []
        for row in page:
            if fmt == "csv":
                chunk.append(secevents.csv_line(secevents.row_values(row)))
            else:
                chunk.append(("" if first else ",") + json.dumps(row, separators=(",", ":")))
                first = False
        await resp.write("".join(chunk).encode("utf-8"))
        sent += len(page)
        before_id = page[-1]["id"]
        if len(page) < want:
            break
    if fmt == "json":
        await resp.write(f'],"count":{sent},"truncated":{"true" if truncated else "false"}}}'.encode("utf-8"))
    await resp.write_eof()
    return resp


# =============================================================================
# Auto-Moderation API (admin only)
# =============================================================================

_AUTOMOD_RULE_TYPES = {"word_filter", "spam_filter", "link_filter", "caps_filter", "mention_spam"}
_AUTOMOD_ACTIONS = {"warn", "delete", "timeout", "mute"}


async def http_get_automod_rules(request: web.Request) -> web.Response:
    """Get all automod rules (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not token.has_scope("admin") and not token.has_scope("*"):
        user = await db.get_user_by_id(token.user_id)
        role = (user.get("role") or "user") if user else "user"
        if role not in ("admin", "superadmin"):
            return web.json_response({"error": "Admin access required"}, status=403)
    rules = await db.get_automod_rules()
    for rule in rules:
        try:
            cfg = json.loads(rule["config"]) if isinstance(rule["config"], str) else rule["config"]
        except (json.JSONDecodeError, TypeError):
            cfg = None
        # The flag is for enabled rules that fail validation; a disabled rule is
        # off on purpose and is not reported as "not enforced".
        rule["not_enforced_reason"] = (
            automod.unenforced_reason(rule["type"], cfg) if rule.get("enabled") else None)
        # Budget overruns of the rule's regex patterns in the last hour: each one rejected a message.
        rule["slow_pattern_timeouts"] = automod.slow_pattern_timeouts(_automod_regex, rule["type"], cfg)
        # Checks of the last hour that failed because the regex worker could not run.
        rule["regex_worker_failures"] = automod.regex_worker_failures(_automod_regex, rule["type"], cfg)
    return web.json_response({"rules": rules})


async def http_create_automod_rule(request: web.Request) -> web.Response:
    """Create an automod rule (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)
    role = user.get("role") or ("superadmin" if user.get("is_admin") else "user")
    if role not in ("admin", "superadmin"):
        return web.json_response({"error": "Admin access required"}, status=403)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    rule_type = data.get("type", "").strip()
    name = data.get("name", "").strip()
    action = data.get("action", "delete").strip()
    config = data.get("config", {})

    if rule_type not in _AUTOMOD_RULE_TYPES:
        return web.json_response({"error": f"Invalid rule type. Must be one of: {', '.join(_AUTOMOD_RULE_TYPES)}"}, status=400)
    if not name or len(name) > 100:
        return web.json_response({"error": "Name required (max 100 chars)"}, status=400)
    if action not in _AUTOMOD_ACTIONS:
        return web.json_response({"error": f"Invalid action. Must be one of: {', '.join(_AUTOMOD_ACTIONS)}"}, status=400)

    config_error = automod.validate_automod_config(rule_type, config)
    if config_error:
        return web.json_response({"error": config_error}, status=400)

    rule_id = await db.create_automod_rule(
        type=rule_type,
        name=name,
        config=config,
        action=action,
        action_duration=data.get("action_duration"),
        created_by=token.user_id
    )

    # Invalidate cache
    global _automod_cache_time
    _automod_cache_time = 0

    await audit_log("automod_rule_create", token.user_id, user["username"],
                    target_id=rule_id, target_type="automod_rule", target_name=name)

    return web.json_response({"id": rule_id, "success": True}, status=201)


async def http_update_automod_rule(request: web.Request) -> web.Response:
    """Update an automod rule (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)
    role = user.get("role") or ("superadmin" if user.get("is_admin") else "user")
    if role not in ("admin", "superadmin"):
        return web.json_response({"error": "Admin access required"}, status=403)

    try:
        rule_id = int(request.match_info["id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid rule ID"}, status=400)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    if "type" in data and data["type"] not in _AUTOMOD_RULE_TYPES:
        return web.json_response({"error": "Invalid rule type"}, status=400)
    if "action" in data and data["action"] not in _AUTOMOD_ACTIONS:
        return web.json_response({"error": "Invalid action"}, status=400)

    # Validate the rule as it will be stored: a changed type keeps the old config and
    # a changed config keeps the old type, so check the merged result.
    if "type" in data or "config" in data:
        existing = next((r for r in await db.get_automod_rules() if r["id"] == rule_id), None)
        if not existing:
            return web.json_response({"error": "Rule not found or no changes"}, status=404)
        if "config" in data:
            new_config = data["config"]
        else:
            try:
                new_config = json.loads(existing["config"]) if isinstance(existing["config"], str) else existing["config"]
            except (json.JSONDecodeError, TypeError):
                new_config = {}
        config_error = automod.validate_automod_config(data.get("type", existing["type"]), new_config)
        if config_error:
            return web.json_response({"error": config_error}, status=400)
        if "config" in data:
            data["config"] = json.dumps(data["config"])

    success = await db.update_automod_rule(rule_id, **{k: v for k, v in data.items() if k in ("type", "name", "config", "enabled", "action", "action_duration")})
    if not success:
        return web.json_response({"error": "Rule not found or no changes"}, status=404)

    global _automod_cache_time
    _automod_cache_time = 0

    await audit_log("automod_rule_update", token.user_id, user["username"],
                    target_id=rule_id, target_type="automod_rule")

    return web.json_response({"success": True})


async def http_delete_automod_rule(request: web.Request) -> web.Response:
    """Delete an automod rule (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)
    role = user.get("role") or ("superadmin" if user.get("is_admin") else "user")
