# Rate limiting for search: user_id -> list of timestamps
_search_rate_limits: dict[int, list[float]] = {}

async def _search_readable_channels(user_id: int, user_role: str, scope: str = "all") -> set:
    """Ids of the channels this member may read: the channels visible to the
    role, each put through _can_read_channel (the check that join and history
    use, which also applies stream bans). Nothing outside this set is searched.
    A scope that searches no channels (dms) needs none of that work."""
    out = set()
    if scope == "dms":
        return out
    for ch in await db.get_accessible_channels(user_id, user_role):
        if await _can_read_channel(ch, user_id, user_role):
            out.add(ch["id"])
    return out


async def _finish_search_results(results: list, viewer_id, viewer_role) -> list:
    """Turn channel hits (ids and flags) into messages for one viewer. The rows
    are built and masked by _enrich_channel_messages, as for history, so an
    anonymous author is never named, whatever the query. Hits whose message is
    gone are dropped. DM hits are complete already."""
    by_channel: dict = {}
    for r in results:
        if r["source"] == "channel":
            by_channel.setdefault(r["source_id"], []).append(r["id"])
    built: dict = {}
    for channel_id, ids in by_channel.items():
        rows = await db.get_chat_messages_by_ids(ids, channel_id)
        real_names = {m["id"]: m.get("username") for m in rows}
        await _enrich_channel_messages(rows, viewer_id, viewer_role, channel_id)
        for m in rows:
            anon = bool(m.get("anonymous"))
            built[m["id"]] = {
                "message": m.get("message", ""),
                # the account name as before (never for an anonymous post); display_name is what chat shows
                "username": "Anonymous" if anon else real_names.get(m["id"]),
                "display_name": m.get("username"),
                "nickname": m.get("nickname"),
                "avatar": m.get("avatar") or {},
                "user_id": m.get("user_id"),
                "role": m.get("role"),
                "anonymous": anon,
                "edited_at": m.get("edited_at"),
                "image_url": m.get("image_url"),
                "attachment_url": m.get("attachment_url"),
                "attachment_name": m.get("attachment_name"),
                "attachment_type": m.get("attachment_type"),
                "attachment_size": m.get("attachment_size"),
            }
    out = []
    seen = set()
    for r in results:
        # a message is listed once, whatever the index returned for it
        key = (r["source"], r["id"])
        if key in seen:
            continue
        seen.add(key)
        if r["source"] == "channel":
            extra = built.get(r["id"])
            if extra is None:
                continue
            r = {**r, **extra}
        out.append(r)
    return out


SEARCH_OFFSET_MAX = 2000        # a search reads offset + limit rows per source; deeper paging is refused with 400


async def http_search_messages(request: web.Request) -> web.Response:
    """Search messages across channels and DMs.

    q holds the words and the operators (from:, in:, has:, is:, before:, after:;
    see chat_search.py); the separate from, has, before and after parameters of
    the older API still work and go through the same checks."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    query = request.query.get("q", "").strip()
    if len(query) < 2:
        return web.json_response({"error": "Query must be at least 2 characters"}, status=400)
    if len(query) > chat_search.MAX_QUERY_LENGTH:
        return web.json_response({"error": f"Query too long (max {chat_search.MAX_QUERY_LENGTH} chars)"}, status=400)
    try:
        parsed = chat_search.parse_search_query(
            query, from_=request.query.get("from"), has=request.query.get("has"),
            before=request.query.get("before"), after=request.query.get("after"))
    except chat_search.SearchQueryError as e:
        return web.json_response({"error": str(e)}, status=400)

    scope = request.query.get("scope", "all")
    if scope not in ("all", "channels", "dms"):
        scope = "all"

    try:
        channel_id = int(request.query["channel_id"]) if "channel_id" in request.query else None
        conversation_id = int(request.query["conversation_id"]) if "conversation_id" in request.query else None
        # ids are checked like the history routes do: a value outside 1..HISTORY_ID_MAX
        # would otherwise reach the database (or, for 0, silently mean "no filter")
        for value in (channel_id, conversation_id):
            if value is not None and not 1 <= value <= HISTORY_ID_MAX:
                raise ValueError("id out of range")
        limit = max(1, min(int(request.query.get("limit", "25")), 50))
        offset = max(int(request.query.get("offset", "0")), 0)
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid parameters"}, status=400)
    # a deep offset never reaches the database (each source is read to offset +
    # limit rows, and a value past the SQLite integer range fails in the driver)
    if offset > SEARCH_OFFSET_MAX:
        return web.json_response({"error": f"offset must not exceed {SEARCH_OFFSET_MAX}"}, status=400)

    # Rate limit: 10 searches per minute
    now = monotonic()
    user_times = _search_rate_limits.setdefault(token.user_id, [])
    user_times[:] = [t for t in user_times if now - t < 60]
    if len(user_times) >= 10:
        return web.json_response({"error": "Rate limit exceeded (10 searches/min)"}, status=429)
    user_times.append(now)
    # Prune stale entries for users who haven't searched recently
    for uid in [k for k, v in _search_rate_limits.items() if not v]:
        del _search_rate_limits[uid]

    # Resolve user role for channel access filtering
    user = await db.get_user_by_id(token.user_id)
    user_role = (user.get("role") or ("superadmin" if user.get("is_admin") else "user")) if user else "user"

    # Fail closed: if the channels this member may read cannot be worked out, there
    # is no search at all (never one over every channel)
    try:
        readable = await _search_readable_channels(token.user_id, user_role, scope)
    except Exception as e:
        logger.error(f"Search: the readable channels could not be looked up: {e}")
        return web.json_response({"error": "Search is unavailable right now"}, status=503)
    results = await db.search_messages(
        query=query, user_id=token.user_id, scope=scope,
        channel_id=channel_id, conversation_id=conversation_id,
        limit=limit, offset=offset, user_role=user_role, parsed=parsed,
        channel_ids=readable,
        include_anonymous_authors=user_role in _CHAT_STAFF_ROLES
    )
    results["results"] = await _finish_search_results(results["results"], token.user_id, user_role)
    # the page after this one starts at offset + len(results); past the cap it would be refused,
    # so a client that follows has_more must not be invited to ask for it
    if offset + len(results["results"]) > SEARCH_OFFSET_MAX:
        results["has_more"] = False
    results["query"] = query
    results["terms"] = parsed.words
    results["operator_only"] = parsed.operator_only
    results["index_complete"] = await db.search_backfill_complete()
    return web.json_response(results)


async def http_rebuild_search_index(request: web.Request) -> web.Response:
    """Rebuild FTS search indexes. Superadmin only."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    user = await db.get_user_by_id(token.user_id)
    if not user or user.get("role") != "superadmin":
        return web.json_response({"error": "Superadmin required"}, status=403)
    # While the index is being backfilled (minutes on a large history) or rebuilt, answer at
    # once instead of holding the request until it is done
    try:
        counts = await db.rebuild_search_index(wait=False)
    except SearchIndexBusy:
        return web.json_response(
            {"error": "The search index is being built right now (backfill or rebuild); try again when it has finished"},
            status=409)
    return web.json_response({"rebuilt": True, "indexed": counts})


# =========================================================================
# Data Retention / Cleanup API
# =========================================================================

async def http_get_retention_config(request: web.Request) -> web.Response:
    """Get data retention configuration. Admin only."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    user = await db.get_user_by_id(token.user_id)
    if not user or not (user.get("is_admin") or user.get("role") in ("superadmin", "admin")):
        return web.json_response({"error": "Admin required"}, status=403)
    config = await db.get_retention_config()
    return web.json_response(config)


async def http_set_retention_config(request: web.Request) -> web.Response:
    """Update data retention configuration. Superadmin only."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    user = await db.get_user_by_id(token.user_id)
    if not user or user.get("role") != "superadmin":
        return web.json_response({"error": "Superadmin required"}, status=403)
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    before = (await db.get_retention_config()).get("retention_security_events_days")
    await db.set_retention_config(data)
    config = await db.get_retention_config()
    after = config.get("retention_security_events_days")
    if after != before:
        # A shorter (or switched-off) event log weakens the record, so the change is itself an event.
        await security_event("security_retention_changed", request=request, user=user,
                             details={"old_days": before, "new_days": after})
    return web.json_response({"updated": True, "config": config})


async def http_run_cleanup_now(request: web.Request) -> web.Response:
    """Run data cleanup immediately. Superadmin only."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    user = await db.get_user_by_id(token.user_id)
    if not user or user.get("role") != "superadmin":
        return web.json_response({"error": "Superadmin required"}, status=403)
    config = await db.get_retention_config()
    results = {}
    errors = []
    file_stats = {"files": 0, "bytes": 0}
    try:
        chat_days = int(config.get("retention_chat_days", 7))
        if chat_days > 0:
            results["chat_messages"] = await db.cleanup_old_chat_messages(days=chat_days, stats=file_stats)
    except Exception as e:
        errors.append(f"chat: {e}")
    try:
        dm_days = int(config.get("retention_dm_days", 30))
        if dm_days > 0:
            results["dm_messages"] = await db.cleanup_old_dm_messages(days=dm_days, stats=file_stats)
    except Exception as e:
        errors.append(f"dm: {e}")
    results["chat_files"] = file_stats["files"]
    results["chat_file_bytes"] = file_stats["bytes"]
    if file_stats.get("skipped"):
        results["chat_files_skipped"] = file_stats["skipped"]
    try:
        results["chat_orphan_sweep"] = await db.sweep_orphan_chat_uploads()
        await db.set_setting("chat_orphan_sweep_last", str(time()))
    except Exception as e:
        errors.append(f"chat_orphan_sweep: {e}")
    try:
        notif_days = int(config.get("retention_notifications_days", 30))
        if notif_days > 0:
            results["notifications"] = await db.cleanup_old_notifications(days=notif_days)
    except Exception as e:
        errors.append(f"notifications: {e}")
    try:
        activity_max = int(config.get("retention_activity_max", 500))
        results["activity_log"] = await db.cleanup_old_activity_log(keep=activity_max)
    except Exception as e:
        errors.append(f"activity: {e}")
    try:
        results["expired_tokens"] = await db.cleanup_expired_tokens()
        results["expired_api_keys"] = await db.cleanup_expired_api_keys()
    except Exception as e:
        errors.append(f"tokens: {e}")
    try:
        logs_max = int(config.get("retention_service_logs_max", 1000))
        service_ids = await db.get_all_service_ids()
        svc_total = 0
        for sid in service_ids:
            svc_total += await db.clear_service_logs(sid, keep_recent=logs_max)
        results["service_logs"] = svc_total
    except Exception as e:
        errors.append(f"service_logs: {e}")
    try:
        devm_days = int(config.get("retention_device_metrics_days", 14))
        if devm_days > 0:
            results["device_metrics"] = await db.cleanup_device_metrics(days=devm_days)
    except Exception as e:
        errors.append(f"device_metrics: {e}")
    try:
        rec_days = int(config.get("retention_recordings_days", 30))
        if rec_days > 0:
            results["recordings"] = await db.cleanup_old_recordings(days=rec_days)
    except Exception as e:
        errors.append(f"recordings: {e}")
    try:
        results["recording_orphans"] = await db.cleanup_orphan_recordings()
    except Exception as e:
        errors.append(f"recording_orphans: {e}")
    try:
        sec_days = int(config.get("retention_security_events_days", 180))
        if sec_days > 0:
            results["security_events"] = await db.cleanup_old_security_events(days=sec_days)
            if results["security_events"]:
                await security_event("security_events_pruned", request=request, user=user,
                                     details={"deleted": results["security_events"], "days": sec_days,
                                              "via": "run_cleanup_now"})
    except Exception as e:
        errors.append(f"security_events: {e}")
    try:
        results["invite_codes"] = await db.cleanup_old_invite_codes(days=30)
    except Exception as e:
        errors.append(f"invite_codes: {e}")
    try:
        results["webhook_logs"] = await db.cleanup_old_webhook_logs(max_age_days=7)
    except Exception as e:
        errors.append(f"webhook_logs: {e}")
    try:
        if config.get("auto_vacuum", "true") == "true":
            results["vacuumed"] = await db.vacuum_database(force=True)
    except Exception as e:
        errors.append(f"vacuum: {e}")
    # Clean stale webhook rate limit entries
    stale_wh = [k for k, v in _webhook_rate_limits.items() if not v]
    for k in stale_wh:
        del _webhook_rate_limits[k]
    stale_inc = [k for k, v in _webhook_incoming_rate_limits.items() if not v]
    for k in stale_inc:
        del _webhook_incoming_rate_limits[k]
    resp = {"cleanup_complete": True, "deleted": results}
    if errors:
        resp["errors"] = errors
    return web.json_response(resp)


async def _broadcast_to_dm(conversation_id: int, message: dict, exclude_user_id: int = None):
    """Broadcast a message to all online participants of a DM conversation."""
    try:
        participants = await db.get_dm_participant_ids(conversation_id)
    except (OSError, ValueError) as e:
        logger.warning("Failed to get DM participants for %s: %s", conversation_id, e)
        return
    for uid in participants:
        if uid == exclude_user_id:
            continue
        dead = set()
        for raw in dm_user_connections.get(uid, set()).copy():
            try:
                if not raw.closed:
                    await raw.send_json(message)
                else:
                    dead.add(raw)
            except (ConnectionError, ConnectionResetError, TypeError):
                dead.add(raw)
        if dead and uid in dm_user_connections:
            dm_user_connections[uid] -= dead


async def _send_dm_to_user(user_id: int, message: dict):
    """Send a message to all WebSocket connections for a specific user."""
    dead = set()
    for raw in dm_user_connections.get(user_id, set()).copy():
        try:
            if not raw.closed:
                await raw.send_json(message)
            else:
                dead.add(raw)
        except (ConnectionError, ConnectionResetError, TypeError):
            dead.add(raw)
    if dead and user_id in dm_user_connections:
        dm_user_connections[user_id] -= dead


async def broadcast_users_list(channel: str):
    """Broadcast the full users list to everyone in a channel."""
    if channel not in chat_rooms or not chat_rooms[channel]:
        return
    user_ids = [entry[1] for entry in chat_rooms[channel]]
    users_info = await db.get_users_status(list(set(user_ids)))
    # One list per viewer: anonymous participants are shown without their id
    # to ordinary members.
    # The room can empty out and be removed while the lookups above and the
    # sends below are awaited.
    dead_connections = set()
    for entry in list(chat_rooms.get(channel, ())):
        ws = entry[0]
        try:
            if not ws.closed:
                await ws.send_json({
                    "type": "users",
                    "users": _chat_users_list(users_info, channel, entry[1], entry[3] if len(entry) > 3 else None)
                })
            else:
                dead_connections.add(entry)
        except (ConnectionError, ConnectionResetError, TypeError):
            dead_connections.add(entry)
    if dead_connections and channel in chat_rooms:
        chat_rooms[channel] -= dead_connections


async def broadcast_to_channel(channel: str, message: dict, exclude=None, anon_subject=None):
    """Broadcast a message to all users in a channel.

    anon_subject is the account id of an anonymous participant the payload is
    about (author, poster, moderation target). Staff and that participant get
    the payload as is; everyone else gets a copy without the real id and role.
    """
    if channel not in chat_rooms:
        return

    hidden = None
    dead_connections = set()
    for entry in list(chat_rooms[channel]):
        # Handle both old (3-tuple) and new (5-tuple) formats during transition
        ws = entry[0]
        if ws == exclude:
            continue
        payload = message
        if anon_subject is not None and not _viewer_sees_identity(
                entry[1], entry[3] if len(entry) > 3 else None, anon_subject):
            if hidden is None:
                hidden = _hide_subject(message, anon_subject, channel)
            payload = hidden
        try:
            if not ws.closed:
                await ws.send_json(payload)
            else:
                dead_connections.add(entry)
        except (ConnectionError, ConnectionResetError, TypeError):
            dead_connections.add(entry)

    # Clean up dead connections (the room may have been removed meanwhile)
    if dead_connections and channel in chat_rooms:
        chat_rooms[channel] -= dead_connections


ANON_VOICE_MESSAGE = "Voice chat in a channel is not available in anonymous mode"


async def drop_channel_voice(user_id: int) -> None:
    """Take a user out of every channel voice room and tell them why.

    Used when anonymous mode is switched on: voice payloads carry the real
    account id, so the member cannot stay in a channel voice room. A session
    that is waiting to reconnect is dropped too (its old socket is closed, so
    the notice only goes to a socket that is still open).
    """
    for room in list(voice_state.keys()):
        users = voice_state.get(room)
        if not users or user_id not in users or room.startswith("dm:"):
            continue
        entry = users[user_id]
        try:
            if not entry["ws"].closed:
                await entry["ws"].send_json({"type": "voice_denied", "message": ANON_VOICE_MESSAGE})
        except (ConnectionError, ConnectionResetError, TypeError):
            pass
        await _voice_remove(room, user_id, entry)


# Voice sessions. voice_state[room][user_id] is one entry per account:
#   ws            the socket that owns the session (the wrapper the handler uses)
#   reconnecting  True while that socket is gone and the grace period runs
#   resume_token  random per join, sent only to the joiner; a resume needs it
#   token_id      the web session / key the owning socket authenticated with
#   grace_task    the task that removes the entry when the grace period ends
VOICE_RESUME_GRACE = 20.0
_voice_grace_tasks: set = set()


def _voice_find(user_id: int):
    """(room, entry) of the user's voice session, or (None, None)."""
    for room, users in voice_state.items():
        entry = users.get(user_id)
        if entry is not None:
            return room, entry
    return None, None


def _voice_owned(room, user_id: int, ws):
    """The user's entry in room when ws owns it and it is not reconnecting."""
    if not room:
        return None
    entry = voice_state.get(room, {}).get(user_id)
    if entry is None or entry.get("ws") is not ws or entry.get("reconnecting"):
        return None
    return entry


def _voice_users_payload(room: str) -> list:
    return [
        {
            "user_id": vid,
            "username": vdata["username"],
            "muted": vdata["muted"],
            "deafened": vdata["deafened"],
            "speaking": vdata["speaking"],
            "screen_sharing": vdata.get("screen_sharing", False),
            "reconnecting": bool(vdata.get("reconnecting")),
        }
        for vid, vdata in voice_state.get(room, {}).items()
    ]


async def _voice_remove(room: str, user_id: int, expected=None) -> bool:
    """The leave sequence: drop the entry, stop a screen share, tell the room.

    expected, when given, makes this a no-op unless that exact entry is still
    the user's (a grace timer must not remove a session that was resumed)."""
    users = voice_state.get(room)
    entry = users.get(user_id) if users else None
    if entry is None or (expected is not None and entry is not expected):
        return False
    del users[user_id]
    if not users:
        voice_state.pop(room, None)
    task = entry.pop("grace_task", None)
    if task is not None and task is not asyncio.current_task():
        task.cancel()
    _voice_speaking_last.pop((room, user_id), None)
    try:
        if entry.get("screen_sharing"):
            await broadcast_to_voice_room(room, {"type": "screen_share_stopped", "user_id": user_id})
        await broadcast_to_voice_room(room, {"type": "voice_user_left", "user_id": user_id})
        if not room.startswith("dm:"):
            await broadcast_users_list(room)
    except (ConnectionError, ConnectionResetError, TypeError, KeyError):
        pass
    logger.info(f"[Voice] {entry.get('username', user_id)} left voice in {room}")
    return True


async def _voice_grace_expire(room: str, user_id: int, entry: dict) -> None:
    try:
        await asyncio.sleep(VOICE_RESUME_GRACE)
        if entry.get("grace_task") is not asyncio.current_task() or not entry.get("reconnecting"):
            return
        await _voice_remove(room, user_id, entry)
    except asyncio.CancelledError:
        raise
    except Exception as e:
        logger.error(f"[Voice] Grace expiry failed in {room}: {e}")


async def _voice_enter_grace(room: str, user_id: int, entry: dict) -> None:
    """The owning socket closed: keep the entry for VOICE_RESUME_GRACE seconds."""
    entry["reconnecting"] = True
    task = asyncio.create_task(_voice_grace_expire(room, user_id, entry))
    entry["grace_task"] = task
    _voice_grace_tasks.add(task)
    task.add_done_callback(_voice_grace_tasks.discard)
    try:
        await broadcast_to_voice_room(room, {"type": "voice_user_reconnecting", "user_id": user_id})
        if not room.startswith("dm:"):
            await broadcast_users_list(room)
    except Exception as e:
        # The entry is already marked and the timer runs; telling the room is
        # best effort and must not stop the caller's own cleanup.
        logger.warning(f"[Voice] Could not announce the lost connection in {room}: {e}")
    logger.info(f"[Voice] {entry.get('username', user_id)} lost the connection in {room}, waiting to resume")


async def _voice_socket_closed(ws, user_id: int) -> None:
    """Called when a chat socket closes: start the grace period for the voice
    entries this socket owns and leave every other entry alone."""
    for room in list(voice_state.keys()):
        entry = (voice_state.get(room) or {}).get(user_id)
        if entry is None or entry.get("ws") is not ws or entry.get("reconnecting"):
            continue
        await _voice_enter_grace(room, user_id, entry)


async def _voice_close_safely(ws, user_id: int) -> None:
    """_voice_socket_closed for the end of the chat handler: whatever goes
    wrong with the voice entries is logged, so the chat-room cleanup that
    follows always runs."""
    try:
        await _voice_socket_closed(ws, user_id)
    except Exception as e:
        logger.error(f"[Voice] Cleanup after a closed chat socket failed for user {user_id}: {e}")


async def _voice_leave_with_token(user_id: int, data: dict) -> bool:
    """voice_leave that carries the resume token: ends the caller's own voice
    session from any socket of the account, also while it is only being held
    (a Leave clicked while the connection was down). The caller's account id
    selects the entry and the token must match, so another account or another
    tab without the token cannot end it."""
    room, entry = _voice_find(user_id)
    presented = data.get("resume_token")
    if entry is None or not isinstance(presented, str):
        return False
    if data.get("room") is not None and data.get("room") != room:
        return False
    if not hmac.compare_digest(presented.encode("utf-8"), str(entry.get("resume_token", "")).encode("utf-8")):
        return False
    return await _voice_remove(room, user_id, entry)


async def _voice_eject_if_not_allowed(user_id: int) -> None:
    """After a ban or a membership removal: if the user's current voice room is
    no longer open to them, take them out of it at once. Never raises."""
    try:
        room, entry = _voice_find(user_id)
        if entry is None:
            return
        role = await _chat_role_of_user(user_id)
        if await _voice_room_allowed(room, user_id, role):
            return
        ws = entry.get("ws")
        if ws is not None and not entry.get("reconnecting"):
            try:
                await asyncio.wait_for(ws.send_json({
                    "type": "voice_denied",
                    "message": "You can no longer take part in this voice chat"}), 2)
            except (asyncio.TimeoutError, ConnectionError, ConnectionResetError, TypeError, RuntimeError):
                pass
        await _voice_remove(room, user_id, entry)
    except Exception as e:
        logger.warning(f"[Voice] Could not re-check voice access for user {user_id}: {e}")


async def _voice_revoke_user(user_id: int, spares) -> None:
    """Remove at once (no grace) every voice entry whose owning session is
    being closed. spares(token_id) is True for sessions that stay."""
    for room in list(voice_state.keys()):
        entry = (voice_state.get(room) or {}).get(user_id)
        if entry is None or entry.get("token_id") is None or spares(entry["token_id"]):
            continue
        # A failure while telling the room must never keep the revoked
        # sockets open, so it is logged and the caller goes on to close them.
        try:
            await _voice_remove(room, user_id, entry)
        except Exception as e:
            logger.warning(f"[Voice] Could not announce the end of a revoked call in {room}: {e}")


async def _voice_room_allowed(room: str, user_id: int, user_role: str) -> bool:
    """Whether the user may still be in this voice room (checked on resume)."""
    if room.startswith("dm:"):
        try:
            return await db.is_dm_participant(int(room.split(":", 1)[1]), user_id)
        except (ValueError, IndexError):
            return False
    # The read check of join and history: a stream chat closed to the member, a
    # stream ban and a private channel the member does not belong to all count
    channel = await db.get_chat_channel_by_name(room)
    return bool(await _can_read_channel(channel, user_id, user_role))


async def _voice_notify_replaced(old_ws) -> None:
    try:
        await asyncio.wait_for(
            old_ws.send_json({"type": "voice_denied", "message": "Voice moved to a newer connection"}), 2)
    except (asyncio.TimeoutError, ConnectionError, ConnectionResetError, TypeError, RuntimeError):
        pass


async def _voice_resume(ws, user_id: int, user_role: str, token_id, my_state: dict, data: dict):
    """voice_join with resume:true. Re-attaches ws to the user's own voice
    entry and returns its room, or answers voice_resume_failed and returns None.

    The entry is looked up by the caller's own account id, and the caller must
    present the random resume token that voice_join returned to the socket that
    created the session. It is taken over only while the entry is reconnecting
    or while its current socket is being replaced by this one. A second tab,
    which never saw the token, cannot do either."""
    async def fail():
        await ws.send_json({"type": "voice_resume_failed",
                            "message": "Voice session could not be resumed"})
        return None

    room, entry = _voice_find(user_id)
    presented = data.get("resume_token")
    if entry is None or not isinstance(presented, str) or data.get("room") != room:
        return await fail()
    if not hmac.compare_digest(presented.encode("utf-8"), str(entry.get("resume_token", "")).encode("utf-8")):
        return await fail()
    if my_state["anonymous"] and not room.startswith("dm:"):
        await ws.send_json({"type": "voice_denied", "message": ANON_VOICE_MESSAGE})
        await _voice_remove(room, user_id, entry)
        return None
    if not await _voice_room_allowed(room, user_id, user_role):
        await _voice_remove(room, user_id, entry)
        return await fail()

    # No await from here to the swap: the grace timer cannot slip in between.
    if voice_state.get(room, {}).get(user_id) is not entry:
        return await fail()
    old_ws = entry.get("ws")
    if old_ws is not ws:
        task = entry.pop("grace_task", None)
        if task is not None:
            task.cancel()
        entry["ws"] = ws
        entry["reconnecting"] = False
        entry["token_id"] = token_id
        entry["username"] = "Anonymous" if my_state["anonymous"] else (my_state["nickname"] or entry["username"])

    if old_ws is not ws and old_ws is not None and not old_ws.closed:
        # The replaced socket may be half open; do not wait for it.
        notice = asyncio.create_task(_voice_notify_replaced(old_ws))
        _voice_grace_tasks.add(notice)
        notice.add_done_callback(_voice_grace_tasks.discard)
    try:
        await ws.send_json({
            "type": "voice_state",
            "channel": room,
            "users": _voice_users_payload(room),
            "resume_token": entry["resume_token"],
            "resumed": True,
        })
    except (ConnectionError, ConnectionResetError, TypeError):
        pass
    if old_ws is not ws:
        await broadcast_to_voice_room(room, {"type": "voice_user_resumed", "user_id": user_id}, exclude=ws)
        if not room.startswith("dm:"):
            await broadcast_users_list(room)
        logger.info(f"[Voice] {entry['username']} resumed voice in {room}")
    return room


async def broadcast_to_voice_room(room: str, message: dict, exclude=None):
    """Broadcast a message to all users in a voice room. Members that are
    reconnecting have no live socket and are skipped."""
    if room not in voice_state:
        return
    for vid, vdata in list(voice_state[room].items()):
        if vdata.get("reconnecting"):
            continue
        vws = vdata.get("ws")
        if vws and vws != exclude:
            try:
                if not vws.closed:
                    await vws.send_json(message)
            except (ConnectionError, ConnectionResetError, TypeError):
                pass


async def send_notification(user_id: int, type: str, title: str,
                            message: str = "", data: dict = None):
    """Create a notification and push it to connected WebSockets."""
    notif_id = await db.create_notification(user_id, type, title, message, data)
    await _push_notification_frame(user_id, notif_id, type, title, message, data)


async def _push_notification_frame(user_id: int, notif_id: int, type: str, title: str,
                                   message: str = "", data: dict = None):
    """Push an already stored notification to the member's connected WebSockets."""
    if user_id in notification_subscribers:
        dead = set()
        payload = {
            "type": "notification",
            "notification": {
                "id": notif_id,
                "type": type,
                "title": title,
                "message": message,
                "data": data or {},
                "is_read": False,
                "created_at": datetime.now(timezone.utc).isoformat()
            }
        }
        for ws in notification_subscribers[user_id]:
            try:
                if not ws.closed:
                    await ws.send_json(payload)
                else:
                    dead.add(ws)
            except (ConnectionError, ConnectionResetError, TypeError):
                dead.add(ws)
        notification_subscribers[user_id] -= dead


async def broadcast_notification(type: str, title: str, message: str = "",
                                  data: dict = None, exclude_user_id: int = None):
    """Send a notification to all users (e.g., stream went live)."""
    users = await db.get_all_users()
    for user in users:
        if user["id"] != exclude_user_id:
            await send_notification(user["id"], type, title, message, data)


async def http_get_notifications(request: web.Request) -> web.Response:
    """Get notifications for the current user."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    unread_only = request.query.get("unread") == "1"
    try:
        limit = min(int(request.query.get("limit", "50")), 100)
        offset = max(int(request.query.get("offset", "0")), 0)
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid limit or offset parameter"}, status=400)
    notifications = await db.get_notifications(token.user_id, unread_only=unread_only,
                                                limit=limit, offset=offset)
    unread_count = await db.get_unread_notification_count(token.user_id)
    return web.json_response({"notifications": notifications, "unread_count": unread_count})


async def http_mark_notification_read(request: web.Request) -> web.Response:
    """Mark a notification as read."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    notif_id = request.match_info.get("id")
    if not notif_id or not notif_id.isdigit():
        return web.json_response({"error": "Invalid notification ID"}, status=400)

    updated = await db.mark_notification_read(int(notif_id), token.user_id)
    if not updated:
        return web.json_response({"error": "Notification not found"}, status=404)
    return web.json_response({"success": True})


async def http_mark_all_notifications_read(request: web.Request) -> web.Response:
    """Mark all notifications as read."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    count = await db.mark_all_notifications_read(token.user_id)
    return web.json_response({"success": True, "count": count})


async def http_get_current_user(request: web.Request) -> web.Response:
    """Get current authenticated user info."""
    token = await authenticate_request(request)
    if not token:
        return web.json_response({"error": "Not authenticated"}, status=401)

    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)

    role = user.get("role") or ("admin" if user.get("is_admin") else "user")
    is_admin = role in ("admin", "superadmin")
    # Parse avatar JSON
    avatar = {}
    if user.get("avatar"):
        try:
            avatar = json.loads(user["avatar"])
        except (json.JSONDecodeError, TypeError):
            pass
    return web.json_response({
        "id": user["id"],
        "username": user["username"],
        "nickname": user.get("nickname"),
        "status": user.get("status", "online"),
        "status_message": user.get("status_message"),
        "role": role,
        "chat_anonymous": bool(user.get("chat_anonymous")),
        "avatar": avatar,
        "is_admin": is_admin,
        "scopes": token.scopes,
        # {service_id: ["control","logs"]} — managed services this (non-admin)
        # user may control/read without being an admin. Empty for admins (they
        # can already do everything).
        "granted_services": {} if is_admin else await db.get_user_granted_service_ids(token.user_id),
        "permissions": {
            "can_manage_users": get_role_level(role) >= get_role_level("moderator"),
            "can_reset_passwords": get_role_level(role) >= get_role_level("admin"),
            "can_delete_users": role == "superadmin",
            "manageable_roles": get_manageable_roles(role),
            "can_add_connections": is_admin or (await db.get_setting("allow_user_connections")) != "false",
            "can_add_streams": is_admin or (await db.get_setting("allow_user_streams")) != "false",
        }
    })


async def http_change_password(request: web.Request) -> web.Response:
    """Change the current user's password."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, dict):
        return web.json_response({"error": "JSON object required"}, status=400)

    current_password = data.get("current_password")
    new_password = data.get("new_password")

    if (not current_password or not new_password
            or not isinstance(current_password, str)
            or not isinstance(new_password, str)):
        return web.json_response(
            {"error": "current_password and new_password required"},
            status=400
        )

    if len(new_password) < 8:
        return web.json_response(
            {"error": "New password must be at least 8 characters"},
            status=400
        )

    # Get user and verify current password
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)

    if not verify_password(current_password, user["password_hash"]):
        logger.warning(f"Failed password change attempt for user {token.user_id}")
        security_event_nowait("password_change_failed", request=request, user=user,
                              result="bad_current_password")
        return web.json_response({"error": "Current password is incorrect"}, status=401)

    # Update password
    new_hash = hash_password(new_password)
    await db.update_password_hash(token.user_id, new_hash)

    # Revoke all existing tokens except the current session
    await db.revoke_user_tokens(token.user_id, except_token_id=token.token_id)
    # API keys and stream keys are not revoked here, so their sockets stay open.
    await close_user_websockets(token.user_id, except_token_id=token.token_id,
                                keep_prefixes=("apikey-", "streamkey-"))

    logger.info(f"Password changed for user {token.user_id}")
    await security_event("password_changed", request=request, user=user,
                         details={"other_sessions_revoked": True})

    return web.json_response({"message": "Password changed successfully"})


async def http_update_user_status(request: web.Request) -> web.Response:
    """Update user's chat status."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    status = data.get("status")
    status_message = data.get("status_message", "")

    if not status:
        return web.json_response({"error": "status required"}, status=400)

    valid_statuses = ('online', 'away', 'busy', 'dnd', 'offline')
    if status not in valid_statuses:
        return web.json_response(
            {"error": f"Invalid status. Must be one of: {', '.join(valid_statuses)}"},
            status=400
        )

    if status_message and len(status_message) > 100:
        return web.json_response({"error": "Status message too long (max 100 chars)"}, status=400)

    await db.set_user_status(token.user_id, status, status_message, update_preference=True)

    # Broadcast status change to all chat rooms the user is in
    user = await db.get_user_by_id(token.user_id)
    username = user["username"] if user else "Unknown"
    is_anon = bool(user.get("chat_anonymous")) if user else False
    for channel, users in chat_rooms.items():
        for entry in users:
            if entry[1] == token.user_id:
                await broadcast_to_channel(channel, {
                    "type": "user_status_changed",
                    "user_id": token.user_id,
                    "username": "Anonymous" if is_anon else username,
                    "status": status,
                    "status_message": status_message
                }, anon_subject=token.user_id if is_anon else None)
                break

    return web.json_response({
        "status": status,
        "status_message": status_message
    })


async def http_update_user_nickname(request: web.Request) -> web.Response:
    """Update user's chat nickname."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    nickname = data.get("nickname", "").strip()

    # Validate nickname (allow empty to clear)
    if nickname:
        if len(nickname) < 2 or len(nickname) > 32:
            return web.json_response({"error": "Nickname must be 2-32 characters"}, status=400)
        # Only allow alphanumeric, spaces, underscores, dashes
        if not re.match(r'^[\w\s\-]+$', nickname):
            return web.json_response({"error": "Nickname can only contain letters, numbers, spaces, underscores and dashes"}, status=400)

    await db.set_user_nickname(token.user_id, nickname if nickname else None)

    # Update live WS handler state immediately
    if token.user_id in chat_user_state:
        chat_user_state[token.user_id]["nickname"] = nickname if nickname else None

    # Broadcast nickname change to all chat rooms
    user = await db.get_user_by_id(token.user_id)
    username = user["username"] if user else "Unknown"
    # An anonymous participant's nickname is not shown to anyone; the user
    # list is refreshed when anonymous mode is switched off.
    for channel, users in ([] if (user and user.get("chat_anonymous")) else chat_rooms.items()):
        for entry in users:
            if entry[1] == token.user_id:
                await broadcast_to_channel(channel, {
                    "type": "user_nickname_changed",
                    "user_id": token.user_id,
                    "username": username,
                    "nickname": nickname if nickname else None
                })
                break

    return web.json_response({
        "nickname": nickname if nickname else None
    })


# Rate limiting for the anonymous-mode toggle: user_id -> list of timestamps.
# Every toggle rebroadcasts the user list of each room the user is in.
_anonymous_toggle_times: dict[int, list[float]] = {}
_ANONYMOUS_TOGGLE_LIMIT = 5
_ANONYMOUS_TOGGLE_WINDOW = 60.0


async def http_update_chat_anonymous(request: web.Request) -> web.Response:
    """Update user's chat anonymous mode (hide username)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    now = monotonic()
    times = _anonymous_toggle_times.setdefault(token.user_id, [])
    times[:] = [t for t in times if now - t < _ANONYMOUS_TOGGLE_WINDOW]
    if len(times) >= _ANONYMOUS_TOGGLE_LIMIT:
        return web.json_response(
            {"error": "Too many changes, try again in a minute"}, status=429,
            headers={"Retry-After": str(int(_ANONYMOUS_TOGGLE_WINDOW))})
    times.append(now)
    for uid in [k for k, v in _anonymous_toggle_times.items()
                if not v or now - v[-1] >= _ANONYMOUS_TOGGLE_WINDOW]:
        del _anonymous_toggle_times[uid]

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    anonymous = bool(data.get("anonymous", False))

    await db.set_chat_anonymous(token.user_id, anonymous)

    # Update live WS handler state immediately
    if token.user_id in chat_user_state:
        chat_user_state[token.user_id]["anonymous"] = anonymous
    if anonymous:
        await drop_channel_voice(token.user_id)

    # Broadcast change to all chat rooms
    user = await db.get_user_by_id(token.user_id)
    username = user["username"] if user else "Unknown"
    nickname = chat_user_state.get(token.user_id, {}).get("nickname")
    display_name = "Anonymous" if anonymous else (nickname or username)
    for channel, users in list(chat_rooms.items()):
        for entry in list(users):
            if entry[1] == token.user_id:
                await broadcast_to_channel(channel, {
                    "type": "user_anonymous_changed",
                    "user_id": token.user_id,
                    "username": display_name,
                    "anonymous": anonymous
                }, anon_subject=token.user_id if anonymous else None)
                # Replace every viewer's user list so the entry changes
                # between the real identity and "Anonymous" in one step.
                await broadcast_users_list(channel)
                break

    return web.json_response({
        "anonymous": anonymous
    })


async def http_update_avatar(request: web.Request) -> web.Response:
    """Update user's avatar settings."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    # Validate avatar settings
    avatar = {}
    if "color" in data:
        color = data["color"]
        # Validate hex color
        if not isinstance(color, str) or not color.startswith("#") or len(color) != 7:
            return web.json_response({"error": "Invalid color format. Use #RRGGBB"}, status=400)
        avatar["color"] = color

    if "emoji" in data:
        emoji = data["emoji"]
        if emoji and len(emoji) > 4:  # Emoji can be up to 4 chars with modifiers
            return web.json_response({"error": "Invalid emoji"}, status=400)
        avatar["emoji"] = emoji if emoji else None

    if "initials" in data:
        initials = data["initials"].upper()[:2] if data["initials"] else None
        avatar["initials"] = initials

    await db.set_avatar(token.user_id, avatar)

    # Update live WS handler state immediately
    if token.user_id in chat_user_state:
        chat_user_state[token.user_id]["avatar"] = avatar

    # Broadcast avatar change to all chat rooms
    user = await db.get_user_by_id(token.user_id)
    username = user["username"] if user else "Unknown"
    # An anonymous participant's avatar is not shown to anyone.
    for channel, users in ([] if (user and user.get("chat_anonymous")) else chat_rooms.items()):
        for entry in users:
            if entry[1] == token.user_id:
                await broadcast_to_channel(channel, {
                    "type": "user_avatar_changed",
                    "user_id": token.user_id,
                    "username": username,
                    "avatar": avatar
                })
                break

    return web.json_response({"avatar": avatar})


# =============================================================================
# Two-Factor Authentication Endpoints
# =============================================================================

async def http_2fa_status(request: web.Request) -> web.Response:
    """Get 2FA status for current user."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)

    backup_codes_remaining = 0
    if user.get("backup_codes"):
        backup_codes_remaining = len([c for c in user["backup_codes"].split(",") if c])

    logger.debug(f"2FA status checked for user {token.user_id}")

    return web.json_response({
        "enabled": bool(user.get("totp_enabled")),
        "backup_codes_remaining": backup_codes_remaining
    })


async def http_2fa_setup(request: web.Request) -> web.Response:
    """Start 2FA setup - generate secret and return provisioning URI."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)

    if user.get("totp_enabled"):
        return web.json_response({"error": "2FA is already enabled"}, status=400)

    # Generate new TOTP secret
    secret = generate_totp_secret()
    uri = get_totp_uri(secret, user["username"], Config.TOTP_ISSUER)

    # Store secret temporarily (not enabled yet until verified)
    await db.set_user_totp_secret(token.user_id, secret)

    logger.info(f"2FA setup initiated for user {token.user_id}")

    return web.json_response({
        "secret": secret,
        "uri": uri,
        "issuer": Config.TOTP_ISSUER
    })


async def http_2fa_verify(request: web.Request) -> web.Response:
    """Verify TOTP code and enable 2FA."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    code = data.get("code")
    if not code:
        return web.json_response({"error": "Verification code required"}, status=400)

    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)

    if user.get("totp_enabled"):
        return web.json_response({"error": "2FA is already enabled"}, status=400)

    secret = user.get("totp_secret")
    if not secret:
        return web.json_response(
            {"error": "2FA not set up. Call /api/user/2fa/setup first"},
            status=400
        )

    # Verify the code
    if not verify_totp(secret, code):
        logger.warning(f"Invalid 2FA verification code for user {token.user_id}")
        return web.json_response({"error": "Invalid verification code"}, status=400)

    # Generate backup codes and enable 2FA
    backup_codes = generate_backup_codes(10)
    await db.enable_user_totp(token.user_id, backup_codes)

    logger.info(f"2FA enabled for user {token.user_id}")
    await security_event("2fa_enabled", request=request, user=user)

    return web.json_response({
        "status": "enabled",
        "backup_codes": backup_codes,
        "message": "2FA enabled successfully. Save your backup codes securely."
    })


async def http_2fa_disable(request: web.Request) -> web.Response:
    """Disable 2FA (requires password confirmation)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    password = data.get("password")
    if not password:
        return web.json_response({"error": "Password required to disable 2FA"}, status=400)

    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)

    if not user.get("totp_enabled"):
        return web.json_response({"error": "2FA is not enabled"}, status=400)

    # Verify password
    if not verify_password(password, user["password_hash"]):
        logger.warning(f"Failed 2FA disable attempt for user {token.user_id} - wrong password")
        security_event_nowait("2fa_disable_failed", request=request, user=user, result="bad_password")
        return web.json_response({"error": "Invalid password"}, status=401)

    # Disable 2FA
    await db.disable_user_totp(token.user_id)

    logger.info(f"2FA disabled for user {token.user_id}")
    await security_event("2fa_disabled", request=request, user=user)

    return web.json_response({
        "status": "disabled",
        "message": "Two-factor authentication has been disabled"
    })


async def get_user_role_from_token(token) -> str:
    """Get the role of the user from their token."""
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return "user"
    return user.get("role") or ("admin" if user.get("is_admin") else "user")


async def http_list_users(request: web.Request) -> web.Response:
    """List all users (moderator+ only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    actor_role = await get_user_role_from_token(token)
    if get_role_level(actor_role) < get_role_level("moderator"):
        return forbidden_response(request)

    users = await db.get_all_users()

    return web.json_response({
        "users": [
            {
                "id": u["id"],
                "username": u["username"],
                "role": u.get("role", "user"),
                "is_admin": bool(u.get("is_admin")),
                "created_at": u["created_at"]
            }
            for u in users
        ],
        "actor_role": actor_role,
        "manageable_roles": get_manageable_roles(actor_role)
    })


async def http_update_user_role(request: web.Request) -> web.Response:
    """Update user role (requires appropriate permissions).

    Permission rules:
    - superadmin: can assign any role (admin, moderator, user)
    - admin: can assign moderator, user
    - moderator: can assign user only
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    actor_role = await get_user_role_from_token(token)
    if get_role_level(actor_role) < get_role_level("moderator"):
        return forbidden_response(request)

    user_id = request.match_info.get("id")
    if not user_id or not user_id.isdigit():
        return web.json_response({"error": "Invalid user ID"}, status=400)

    user_id = int(user_id)

    # Don't allow modifying yourself
    if user_id == token.user_id:
        return web.json_response(
            {"error": "Cannot modify your own role"},
            status=400
        )

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, dict):
        return web.json_response({"error": "JSON object required"}, status=400)

    new_role = data.get("role")

    # Handle legacy is_admin field for backward compatibility
    if new_role is None and "is_admin" in data:
        new_role = "admin" if data["is_admin"] else "user"

    if not new_role:
        return web.json_response({"error": "role field required"}, status=400)

    if new_role not in ROLE_HIERARCHY:
        return web.json_response(
            {"error": f"Invalid role. Must be one of: {', '.join(ROLE_HIERARCHY)}"},
            status=400
        )

    target_user = await db.get_user_by_id(user_id)
    if not target_user:
        return web.json_response({"error": "User not found"}, status=404)

    target_role = target_user.get("role") or ("admin" if target_user.get("is_admin") else "user")

    # Check if actor can manage the target user
    if not can_manage_role(actor_role, target_role):
        return web.json_response(
            {"error": f"You cannot modify users with role '{target_role}'"},
            status=403
        )

    # Check if actor can assign the new role
    if not can_assign_role(actor_role, new_role):
        return web.json_response(
            {"error": f"You cannot assign the role '{new_role}'"},
            status=403
        )

    await db.set_user_role(user_id, new_role)

    # Revoke all tokens - user must re-authenticate with new role scopes
    await db.revoke_user_tokens(user_id)
    # API keys carry the scopes of the role they were created under.
    await db.revoke_user_api_keys(user_id)
    await close_user_websockets(user_id)

    logger.info(f"Role changed for user {target_user['username']} from {target_role} to {new_role} by user {token.user_id}")

    actor = await db.get_user_by_id(token.user_id)
    await audit_log("role_change", token.user_id, actor["username"] if actor else "unknown",
                    target_id=user_id, target_type="user",
                    target_name=target_user["username"],
                    details=json.dumps({"old_role": target_role, "new_role": new_role}))
    await security_event("role_changed", request=request, user_id=token.user_id,
                         username=actor["username"] if actor else None,
                         details={"target_user_id": user_id,
                                  "target_username": target_user["username"],
                                  "old_role": target_role, "new_role": new_role})

    return web.json_response({
        "id": user_id,
        "username": target_user["username"],
        "role": new_role,
        "is_admin": new_role in ("admin", "superadmin"),
        "message": f"Role updated to {new_role}"
    })


async def http_update_user_admin(request: web.Request) -> web.Response:
    """Legacy endpoint - redirects to role update."""
    return await http_update_user_role(request)


async def http_delete_user(request: web.Request) -> web.Response:
    """Delete a user (superadmin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    actor_role = await get_user_role_from_token(token)

    # Only superadmins can delete users
    if actor_role != "superadmin":
        return web.json_response(
            {"error": "Only superadmins can delete users"},
            status=403
        )

    user_id = request.match_info.get("id")
    if not user_id or not user_id.isdigit():
        return web.json_response({"error": "Invalid user ID"}, status=400)

    user_id = int(user_id)

    # Don't allow deleting yourself
    if user_id == token.user_id:
        return web.json_response(
            {"error": "Cannot delete your own account"},
            status=400
        )

    target_user = await db.get_user_by_id(user_id)
    if not target_user:
        return web.json_response({"error": "User not found"}, status=404)

    # Superadmins can delete anyone (except themselves, checked above)
    target_role = target_user.get("role") or ("admin" if target_user.get("is_admin") else "user")

    # Delete user and all associated data via ORM
    await db.delete_user(user_id)
    # The user's streams went with the account
    _playback_cache_forget(everything=True)
    # A deleted account must not keep working through sockets it already had open.
    try:
        await close_user_websockets(user_id)
    except Exception as e:
        logger.warning(f"Could not close sockets of deleted user {user_id}: {e}")

    logger.info(f"User {target_user['username']} deleted by superadmin {token.user_id}")
    actor_name = await _username_of(token.user_id)
    await audit_log("user_delete", token.user_id, actor_name or "unknown",
                    target_id=user_id, target_type="user",
                    target_name=target_user["username"],
                    details={"target_role": target_role})
    await security_event("user_deleted", request=request, user_id=token.user_id,
                         username=actor_name,
                         details={"target_user_id": user_id,
                                  "target_username": target_user["username"],
                                  "target_role": target_role})

    return web.json_response({
        "message": f"User '{target_user['username']}' deleted"
    })


async def http_reset_user_password(request: web.Request) -> web.Response:
    """Reset a user's password (admin+ for managed users, moderator for self only).

    Permission rules:
    - superadmin: can reset any user's password (including other superadmins)
    - admin: can reset moderator and user passwords
    - moderator: can only reset their own password via /api/me/password
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    actor_role = await get_user_role_from_token(token)
    if get_role_level(actor_role) < get_role_level("admin"):
        return web.json_response(
            {"error": "Only admins and superadmins can reset passwords"},
            status=403
        )

    user_id = request.match_info.get("id")
    if not user_id or not user_id.isdigit():
        return web.json_response({"error": "Invalid user ID"}, status=400)

    user_id = int(user_id)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, dict):
        return web.json_response({"error": "JSON object required"}, status=400)

    new_password = data.get("new_password")
    if not new_password or not isinstance(new_password, str):
        return web.json_response({"error": "new_password required"}, status=400)

    if len(new_password) < 8:
        return web.json_response(
            {"error": "Password must be at least 8 characters"},
            status=400
        )

    target_user = await db.get_user_by_id(user_id)
    if not target_user:
        return web.json_response({"error": "User not found"}, status=404)

    target_role = target_user.get("role") or ("admin" if target_user.get("is_admin") else "user")

    # Check if actor can manage the target user
    if not can_manage_role(actor_role, target_role):
        return web.json_response(
            {"error": f"You cannot reset passwords for users with role '{target_role}'"},
            status=403
        )

    # Hash and save new password
    new_hash = hash_password(new_password)
    await db.reset_user_password(user_id, new_hash)

    # Sign the target out everywhere; an admin resetting their own password
    # keeps the session they are using.
    keep_token_id = token.token_id if user_id == token.user_id else None
    revoked = await db.revoke_user_tokens(user_id, except_token_id=keep_token_id)
    # API keys outlive browser sessions, so they go too, as do WebSockets opened
    # with the revoked sessions. A self-reset keeps the caller's own credential.
    keys_revoked = await db.revoke_user_api_keys(user_id, except_token_id=keep_token_id)
    # Stream keys are not revoked by a reset, so their sockets stay open.
    ws_closed = await close_user_websockets(user_id, except_token_id=keep_token_id,
                                            keep_prefixes=("streamkey-",))

    logger.info(f"Password reset for user {target_user['username']} by {actor_role} {token.user_id}")

    actor = await db.get_user_by_id(token.user_id)
    await audit_log("password_reset", token.user_id, actor["username"] if actor else "unknown",
                    target_id=user_id, target_type="user",
                    target_name=target_user["username"],
                    details={"sessions_revoked": revoked,
                             "api_keys_revoked": keys_revoked,
                             "websockets_closed": ws_closed})
    await security_event("password_reset", request=request, user_id=token.user_id,
                         username=actor["username"] if actor else None,
                         details={"target_user_id": user_id,
                                  "target_username": target_user["username"],
                                  "sessions_revoked": revoked,
                                  "api_keys_revoked": keys_revoked,
                                  "websockets_closed": ws_closed})

    return web.json_response({
        "message": f"Password reset for user '{target_user['username']}'"
    })


