async def _admin_only(request: web.Request):
    """(token, error_response) for a credential with admin power whose account is an admin or superadmin now."""
    token = await authenticate_request(request)
    if not token:
        return None, unauthorized_response(request)
    if not token.has_scope("admin") and not token.has_scope("*"):
        return None, forbidden_response(request)
    # The role comes from the database: a session made before a demotion keeps its scopes.
    if get_role_level(await get_user_role_from_token(token)) < get_role_level("admin"):
        return None, forbidden_response(request)
    return token, None


def _never_ban_view(request: web.Request, admin_nets=None) -> dict:
    """The never-ban state as the admin page shows it, with a note on the caller's own address."""
    nets = _never_ban_admin_nets if admin_nets is None else admin_nets
    my_ip = get_client_ip(request)
    source = _never_ban_reason(my_ip, admin_nets=nets)
    return {
        "entries": [str(n) for n in nets],
        "env_warnings": list(_never_ban_env_warnings),
        "effective": _never_ban_effective(),
        "limits": {
            "max_entries": ipguard.MAX_NEVER_BAN_ENTRIES,
            "min_prefix_ipv4": ipguard.MIN_PREFIX_V4,
            "min_prefix_ipv6": ipguard.MIN_PREFIX_V6,
        },
        "your_ip": my_ip,
        "your_ip_covered": source is not None,
        "your_ip_source": source,
    }


async def http_get_never_ban(request: web.Request) -> web.Response:
    """GET /api/admin/never-ban - the admin list and the effective list with its sources (superadmin)."""
    user, err = await _backup_superadmin(request)
    if err:
        return err
    return web.json_response(_never_ban_view(request))


async def http_put_never_ban(request: web.Request) -> web.Response:
    """PUT /api/admin/never-ban - replace the admin list: {"entries": ["203.0.113.0/24", ...]} (superadmin)."""
    user, err = await _backup_superadmin(request)
    if err:
        return err
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, dict):
        return web.json_response({"error": "Body must be an object with an entries list"}, status=400)
    try:
        nets = ipguard.validate_cidr_list(data.get("entries"))
    except ipguard.ListError as e:
        return web.json_response({"error": str(e)}, status=400)
    global _never_ban_admin_nets
    before = {str(n) for n in _never_ban_admin_nets}
    await db.set_setting(NEVER_BAN_SETTING, json.dumps([str(n) for n in nets]))
    _never_ban_admin_nets = nets
    cleared = _forget_probe_state(nets)
    saved = [str(n) for n in nets]
    # Counts only, in both records: moderators can read the audit log, the never-ban list is
    # for superadmins, and it names the owner's own addresses.
    added, removed = len(set(saved) - before), len(before - set(saved))
    await audit_log("never_ban.update", user["id"], user.get("username", "unknown"),
                    details={"added": added, "removed": removed, "total": len(saved),
                             "scanner_blocks_cleared": cleared})
    await security_event("never_ban_changed", request=request, user=user,
                         details={"entries": len(saved), "added": added, "removed": removed,
                                  "scanner_blocks_cleared": cleared})
    logger.info(f"Never-ban list set to {len(nets)} entr(ies) by user {user['id']}")
    view = _never_ban_view(request)
    view["saved"] = True
    view["scanner_blocks_cleared"] = cleared
    return web.json_response(view)


async def http_get_proxy_trust(request: web.Request) -> web.Response:
    """GET /api/admin/proxy-trust - the proxy-trust self-check (admin)."""
    token, err = await _admin_only(request)
    if err:
        return err
    return web.json_response(_proxy_trust_status())


async def _cf_ranges_view() -> dict:
    enabled = (await db.get_setting(CF_SETTING_ENABLED)) != "false"
    saved = bool(await db.get_setting(CF_SETTING_LIST))
    return {
        "enabled": enabled,
        # What is in use is `source`. A saved list that is not the one in use is "ignored": the
        # refresh was off at start, or the list failed the checks then. The other way round, the
        # refresh switched off while the fetched list runs keeps that list until the next start.
        "saved_list": saved,
        "saved_list_applied": saved and _cf_source == "fetched",
        "saved_list_ignored": saved and _cf_source != "fetched",
        # Why: "refresh_off" (the refresh was off when the portal started) or "failed_checks"
        # (the saved list failed the checks then); null when nothing is ignored.
        "saved_list_ignored_reason": (
            (_cf_saved_ignored or ("refresh_off" if not enabled else "failed_checks"))
            if saved and _cf_source != "fetched" else None),
        "fetched_in_use_until_restart": (not enabled) and _cf_source == "fetched",
        "source": _cf_source,
        "fetched_at": _cf_fetched_at,
        "v4": sum(1 for n in _cf_networks if n.version == 4),
        "v6": sum(1 for n in _cf_networks if n.version == 6),
        "last": await _cf_load_last() or None,
        "pending": await _cf_pending_view(),
        "stage_mode": bool(Config.STAGE_MODE),
    }


async def http_get_cf_ranges(request: web.Request) -> web.Response:
    """GET /api/admin/cf-ranges - the Cloudflare range refresh setting and last result (admin)."""
    token, err = await _admin_only(request)
    if err:
        return err
    return web.json_response(await _cf_ranges_view())


async def http_put_cf_ranges(request: web.Request) -> web.Response:
    """PUT /api/admin/cf-ranges - {"enabled": true|false} turns the weekly refresh on or off (superadmin)."""
    user, err = await _backup_superadmin(request)
    if err:
        return err
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, dict) or not isinstance(data.get("enabled"), bool):
        return web.json_response({"error": "enabled must be true or false"}, status=400)
    was_enabled = (await db.get_setting(CF_SETTING_ENABLED)) != "false"
    await db.set_setting(CF_SETTING_ENABLED, "true" if data["enabled"] else "false")
    if was_enabled != data["enabled"]:
        await security_event("cf_refresh_toggled", request=request, user=user,
                             details={"was": was_enabled, "enabled": data["enabled"]})
    await audit_log("cf_ranges.settings", user["id"], user.get("username", "unknown"),
                    details={"enabled": data["enabled"]})
    return web.json_response(await _cf_ranges_view())


async def http_reset_cf_ranges(request: web.Request) -> web.Response:
    """POST /api/admin/cf-ranges/reset - clear the saved list and use the built-in one at once (superadmin)."""
    user, err = await _backup_superadmin(request)
    if err:
        return err
    before = await reset_cloudflare_ranges()
    await audit_log("cf_ranges.reset", user["id"], user.get("username", "unknown"),
                    details={"was": before["source"], "v4": before["v4"], "v6": before["v6"]})
    await security_event("cf_ranges_reset", request=request, user=user,
                         details={"was": before["source"], "v4": before["v4"], "v6": before["v6"]})
    logger.warning(f"Cloudflare ranges reset to the built-in list by user {user['id']}")
    view = await _cf_ranges_view()
    view["reset"] = True
    return web.json_response(view)


async def _cf_pending_request(request: web.Request):
    """Shared start of the approve and dismiss routes: (user, list id, error response)."""
    user, err = await _backup_superadmin(request, cookie_only=True)
    if err:
        return None, None, err
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return None, None, web.json_response({"error": "Invalid JSON"}, status=400)
    list_id = data.get("id") if isinstance(data, dict) else None
    if not isinstance(list_id, str) or not list_id:
        return None, None, web.json_response({"error": "id of the pending list required"}, status=400)
    return user, list_id, None


async def http_approve_cf_pending(request: web.Request) -> web.Response:
    """POST /api/admin/cf-ranges/pending/approve - {"id": ...} apply the pending list (superadmin, browser session)."""
    user, list_id, err = await _cf_pending_request(request)
    if err:
        return err
    code, result = await approve_cloudflare_pending(list_id)
    if code != 200:
        return web.json_response(result, status=code)
    await audit_log("cf_ranges.approve", user["id"], user.get("username", "unknown"), details=result)
    await security_event("cf_ranges_approved", request=request, user=user, details=result)
    logger.warning(f"Pending Cloudflare ranges approved by user {user['id']}")
    view = await _cf_ranges_view()
    view["approved"] = True
    return web.json_response(view)


async def http_dismiss_cf_pending(request: web.Request) -> web.Response:
    """POST /api/admin/cf-ranges/pending/dismiss - {"id": ...} drop the pending list (superadmin, browser session)."""
    user, list_id, err = await _cf_pending_request(request)
    if err:
        return err
    code, result = await dismiss_cloudflare_pending(list_id)
    if code != 200:
        return web.json_response(result, status=code)
    await audit_log("cf_ranges.dismiss", user["id"], user.get("username", "unknown"), details=result)
    await security_event("cf_ranges_dismissed", request=request, user=user, details=result)
    logger.info(f"Pending Cloudflare ranges dismissed by user {user['id']}")
    view = await _cf_ranges_view()
    view["dismissed"] = True
    return web.json_response(view)


