@web.middleware
async def security_headers_middleware(request: web.Request, handler):
    """Block banned IPs app-wide, then add security headers to all responses."""
    client_ip = get_client_ip(request)
    _note_request_peer(request)
    if _is_ip_blocked(client_ip) or _is_probe_blocked(client_ip):
        response = web.json_response({"error": "Access denied"}, status=403)
    else:
        try:
            response = await handler(request)
        except web.HTTPException as exc:
            # HTTPException (redirects, 404s, etc.) are also Response objects.
            # Catch them so we can add security headers before returning.
            response = exc
        if _is_scanner_probe(request, response.status):
            _record_probe(client_ip, request.path, secevents.user_agent_of(request))

    # HSTS - Enforce HTTPS for 1 year, include subdomains
    response.headers.setdefault('Strict-Transport-Security',
        'max-age=31536000; includeSubDomains; preload')

    # Prevent clickjacking
    response.headers.setdefault('X-Frame-Options', 'SAMEORIGIN')

    # Prevent MIME type sniffing
    response.headers.setdefault('X-Content-Type-Options', 'nosniff')

    # Enable XSS filter in older browsers
    response.headers.setdefault('X-XSS-Protection', '1; mode=block')

    # Referrer policy
    response.headers.setdefault('Referrer-Policy', 'strict-origin-when-cross-origin')

    # Permissions policy - restrict sensitive features
    response.headers.setdefault('Permissions-Policy',
        'geolocation=(), microphone=(self), camera=(), display-capture=(self), payment=()')

    # Cache control and CSP for HTML pages
    content_type = response.headers.get('Content-Type', '')
    if 'text/html' in content_type:
        # Prevent CDN/browser from serving stale HTML — always revalidate
        response.headers.setdefault('Cache-Control', 'no-cache')

        csp = (
            "default-src 'self'; "
            "script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net blob:; "
            "style-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net; "
            "img-src 'self' data: https:; "
            "font-src 'self' https://cdn.jsdelivr.net; "
            "connect-src 'self' wss:; "
            "media-src 'self' blob:; "
            "frame-src 'self' https://www.youtube.com https://www.youtube-nocookie.com; "
            "worker-src 'self' blob:; "
            "frame-ancestors 'self'; "
            "base-uri 'self'; "
            "form-action 'self';"
        )
        response.headers.setdefault('Content-Security-Policy', csp)

    # Suppress server version to prevent information leakage
    response.headers['Server'] = 'Open Relay Portal'

    return response


